def _require_login_enabled():
    try:
        return bool(config_manager.get('security.require_login', False)) if config_manager else False
    except Exception:
        return False


# --- Login gate (opt-in username/password mode; replaces the launch PIN) ---
@app.before_request
def _enforce_login():
    """Server-side enforcement of username/password login. No-op unless
    security.require_login is on. When on, an unauthenticated session can only
    reach the page shell + the login flow + the key-authed public API."""
    if not _require_login_enabled():
        return
    from core.security.login_gate import login_request_is_blocked
    from core.security.launch_lock import is_html_navigation
    if login_request_is_blocked(
        request.path, request.method,
        require_login=True,
        authenticated=bool(session.get('login_authenticated', False)),
    ):
        if is_html_navigation(request.method, request.headers.get('Accept', ''),
                              request.headers.get('Sec-Fetch-Mode', '')):
            return redirect('/')
        return jsonify({"error": "login_required", "login_required": True}), 401


# --- Launch PIN gate (before_request hook) ---
@app.before_request
def _enforce_launch_pin():
    """Server-side enforcement of the launch PIN (#832).

    The PIN was previously a client-only overlay — removing the div (Safari
    "Hide Distracting Items", devtools, curl) gave full API access. This rejects
    every request from an unverified session with 401 while the launch lock is
    on, except the page shell + the unlock flow + the key-authed public API.
    No-ops entirely when ``security.require_pin_on_launch`` is off (the default).
    """
    # Login mode replaces the launch PIN entirely — when it's on, _enforce_login
    # owns the gate and this no-ops.
    if _require_login_enabled():
        return
    try:
        require_pin = bool(config_manager.get('security.require_pin_on_launch', False)) if config_manager else False
    except Exception:
        require_pin = False
    if not require_pin:
        return
    from core.security.launch_lock import request_is_locked, is_html_navigation
    # An auth proxy (Authelia/Authentik/oauth2-proxy) that already authenticated the
    # user counts as verified — opt-in via security.auth_proxy_header, OFF (empty)
    # by default so a direct install is unaffected.
    from core.security.auth_proxy import trusted_proxy_user
    try:
        _proxy_header = config_manager.get('security.auth_proxy_header', '') or ''
    except Exception:
        _proxy_header = ''
    _verified = bool(session.get('launch_pin_verified', False)) or bool(
        trusted_proxy_user(request.headers.get, _proxy_header)
    )
    if request_is_locked(
        request.path, request.method,
        require_pin=require_pin,
        pin_verified=_verified,
    ):
        # A browser navigating to a sub-page (deep link / refresh) should land
        # on the lock screen, not raw JSON — bounce it to the root, which serves
        # the lock UI. Programmatic fetch/XHR get the JSON so the frontend reacts.
        if is_html_navigation(
            request.method,
            request.headers.get('Accept', ''),
            request.headers.get('Sec-Fetch-Mode', ''),
        ):
            return redirect('/')
        return jsonify({"error": "locked", "launch_pin_required": True}), 401


# --- Profile Context (before_request hook) ---
@app.before_request
def _set_profile_context():
    """Set g.profile_id from session for every request"""
    g.request_start_monotonic = time.perf_counter()
    # Skip for profile management, static, and root routes
    path = request.path
    if (path.startswith('/api/profiles') or
        path.startswith('/static/') or
        path == '/' or
        path.startswith('/api/v1/')):
        g.profile_id = session.get('profile_id', 1)
        return

    pid = session.get('profile_id', 1)

    # Validate session profile still exists (handles deleted profiles), and stash
    # download permission on g so isolated blueprints (video) can gate without a
    # music-DB read. Admin (1) is always allowed.
    g.can_download = True
    g.profile_name = "Admin"   # display name for isolated blueprints (video issues reporter)
    g.is_admin = True          # profile 1 is always admin; others per their is_admin flag
    g.allowed_sides = 'both'   # per-profile side access (music|video|both); admins always both
    if pid != 1 and 'profile_id' in session:
        g.is_admin = False
        try:
            database = get_database()
            profile = database.get_profile(pid)
            if not profile:
                session.pop('profile_id', None)
                from flask import jsonify as _jsonify
                return _jsonify({"error": "profile_required", "message": "Profile no longer exists"}), 401
            g.can_download = bool((profile or {}).get('can_download', True))
            g.profile_name = (profile or {}).get('name') or ("Profile %s" % pid)
            g.is_admin = bool((profile or {}).get('is_admin', False))
            # get_profile resolves defaults (non-admin NULL → 'music'), so the
            # video blueprint can gate off g without a second music-DB read.
            g.allowed_sides = (profile or {}).get('allowed_sides') or 'music'
        except Exception as e:
            logger.debug("profile session validate: %s", e)

    g.profile_id = pid


@app.after_request
def _log_slow_request(response):
    """Log slow HTTP requests so we can identify UI stall sources."""
    try:
        path = request.path
        if path.startswith('/socket.io/'):
            return response

        start = getattr(g, 'request_start_monotonic', None)
        if start is None:
            return response

        elapsed_ms = (time.perf_counter() - start) * 1000
        slow_threshold_ms = 1000.0
        if elapsed_ms >= slow_threshold_ms:
            logger.warning(
                "Slow request: %s %s -> %s in %.1fms",
                request.method,
                request.full_path.rstrip('?'),
                response.status_code,
                elapsed_ms,
            )
    except Exception as e:
        logger.debug("slow request log failed: %s", e)

    return response


@app.after_request
def _force_module_script_mimetype(response):
    """#979/#986: force a valid JS Content-Type on .js/.mjs responses so the
    React bundle's <script type="module"> is never refused (Import/Stats black
    screen). HTTP-layer, so it doesn't depend on the OS mimetypes registry —
    which is unreliable across Docker base images."""
    try:
        fixed = corrected_script_content_type(request.path, response.headers.get('Content-Type'))
        if fixed:
            response.headers['Content-Type'] = fixed
    except Exception as e:
        logger.debug("module-script mimetype fix failed: %s", e)
    return response


@app.after_request
def _add_discover_cache_headers(response):
    """Browser-cache discover GETs for 5 minutes.

    The discover surface (hero, similar artists, recent releases, release
    radar, deep cuts, etc.) returns semi-stable data that's expensive to
    compute and not user-action-driven within a session. A short browser
    cache eliminates redundant fetches when the user toggles between
    Discover sections or navigates back.

    Scope: only `/api/discover/` and `/api/discovery/` paths, only GET,
    only successful 2xx responses. Any endpoint that explicitly sets
    its own Cache-Control wins (we don't override).

    Uses `private` not `public` because discover data is user-specific
    (hero artists from your watchlist, similar artists from your taste,
    etc.). `private` keeps it browser-only — intermediate proxies
    (corporate caching proxies, Cloudflare with cache rules, Nginx
    proxy_cache) won't store one user's response and serve it to another.
    """
    try:
        if request.method != 'GET':
            return response
        if not (request.path.startswith('/api/discover/')
                or request.path.startswith('/api/discovery/')):
            return response
        if not (200 <= response.status_code < 300):
            return response
        if response.headers.get('Cache-Control'):
            return response
        # The two rec rows re-rank on the live adventurousness dial, which lives in server-side config
        # (NOT the URL). A browser cache would freeze them at the first load's value — the slider would
        # flicker but never move (the reported bug). Never cache these; the rest of discover still is.
        if request.path in ('/api/discover/similar-artists', '/api/discover/listening-recommendations'):
            response.headers['Cache-Control'] = 'no-store'
            return response
        response.headers['Cache-Control'] = 'private, max-age=300'
    except Exception as exc:
        # Don't let a header-tagging bug turn a successful response into
        # a 500 — log and ship the response without the cache header.
        logger.warning(f"[discover-cache-headers] failed for {request.path}: {exc}")
    return response


