def _register_automation_handlers():
    """Register real SoulSync action handlers with the automation engine.

    Per-handler bodies live in ``core.automation.handlers``. This
    function wires the dependency-injection surface (clients,
    callables, mutable state) into a single ``AutomationDeps`` object
    and hands it to ``register_all``.

    NOTE: extraction is in progress. The first batch of handlers
    (``process_wishlist`` / ``scan_watchlist`` / ``scan_library``)
    has been moved to ``core/automation/handlers/``; the remaining
    closures still live below until subsequent commits in the same
    branch finish the lift.
    """
    global _automation_deps, _playlist_source_registry

    if not automation_engine:
        return

    from core.automation.deps import AutomationDeps, AutomationState
    from core.automation.handlers import register_all as _register_extracted_handlers
    from core.playlists.sources.bootstrap import build_playlist_source_registry

    # Mutable shared state previously lived as module-level globals
    # (`_scan_library_automation_id`, `_pipeline_running`, etc).
    # Keeping the legacy globals AS WELL as the new state object during
    # the transitional period so the not-yet-extracted closures still
    # work; they'll be removed once the rest of the lift is done.
    _automation_state = AutomationState()

    from core.watchlist_scanner import get_watchlist_scanner as _get_watchlist_scanner_fn

    # ListenBrainz / Last.fm are profile-scoped, so the manager getter
    # resolves the current profile's manager on each call. iTunes-link
    # parsing lives as a module helper rather than a class — wrap it in
    # a callable that matches the adapter contract.
    def _lb_manager_for_registry():
        try:
            manager, _username, _source = _get_profile_lb_manager()
            return manager
        except Exception:
            return None

    def _itunes_link_parser_for_registry(url):
        # ``parse_itunes_link_endpoint`` is a Flask route handler; the
        # actual parsing work needs the underlying helpers. For now
        # we punt — Phase 2 will lift the parsing into a pure helper
        # the adapter can call directly. Refresh of itunes_link
        # mirrors is not yet wired (current handler skips them).
        return None

    # Discovery callable for the LB / Last.fm adapters' ``discover_tracks``.
    # Wraps the pure ``match_mb_tracks`` helper with the live matching
    # engine + Spotify / iTunes clients. Adapter calls it per refresh
    # when any track has ``needs_discovery=True``.
    from core.discovery.matching import MBMatchDeps, match_mb_tracks

    _mb_match_deps = MBMatchDeps(
        matching_engine=matching_engine,
        score_candidates=_discovery_score_candidates,
        spotify_client_getter=lambda: spotify_client,
        itunes_client_getter=_get_itunes_client,
        prefer_spotify_getter=lambda: (_get_active_discovery_source() == 'spotify'),
    )

    def _discover_callable_for_registry(tracks):
        return match_mb_tracks(tracks, _mb_match_deps)

    _playlist_source_registry = build_playlist_source_registry(
        # Per-profile source reads: the adapter calls these fresh on every read,
        # so they resolve the CURRENT profile's account (their session
        # interactively, their automation's owner in the background — via
        # core.profile_context). Admin/profile 1 → the global client, so the
        # admin's existing auto-sync pipelines are unchanged. (Deezer/Qobuz stay
        # global for now — their playlist login is tangled with downloads.)
        spotify_client_getter=get_spotify_client_for_profile,
        tidal_client_getter=get_tidal_client_for_profile,
        qobuz_client_getter=_get_qobuz_client_for_sync,
        deezer_client_getter=_get_deezer_client,
        youtube_parser=parse_youtube_playlist,
        ytmusic_auth_getter=_ytmusic_auth_headers,
        itunes_link_parser=_itunes_link_parser_for_registry,
        listenbrainz_manager_getter=_lb_manager_for_registry,
        lastfm_manager_getter=_lb_manager_for_registry,
        personalized_manager_getter=_build_personalized_manager,
        profile_id_getter=get_current_profile_id,
        discover_callable=_discover_callable_for_registry,
    )

    _automation_deps = AutomationDeps(
        engine=automation_engine,
        state=_automation_state,
        config_manager=config_manager,
        update_progress=_update_automation_progress,
        logger=logger,
        get_database=get_database,
        spotify_client=spotify_client,
        tidal_client=tidal_client,
        web_scan_manager=web_scan_manager,
        process_wishlist_automatically=_process_wishlist_automatically,
        process_watchlist_scan_automatically=_process_watchlist_scan_automatically,
        is_wishlist_actually_processing=is_wishlist_actually_processing,
        is_watchlist_actually_scanning=is_watchlist_actually_scanning,
        get_watchlist_scan_state=lambda: watchlist_scan_state,
        run_playlist_discovery_worker=_run_playlist_discovery_worker,
        run_sync_task=_run_sync_task,
        run_playlist_organize_download=_run_playlist_organize_download,
        missing_download_executor=missing_download_executor,
        load_sync_status_file=_load_sync_status_file,
        get_deezer_client=_get_deezer_client,
        parse_youtube_playlist=parse_youtube_playlist,
        get_sync_states=lambda: sync_states,
        playlist_source_registry=_playlist_source_registry,
        set_db_update_automation_id=_set_db_update_automation_id,
        get_db_update_state=lambda: db_update_state,
        db_update_lock=db_update_lock,
        db_update_executor=db_update_executor,
        run_db_update_task=_run_db_update_task,
        run_deep_scan_task=_run_deep_scan_task,
        get_duplicate_cleaner_state=lambda: duplicate_cleaner_state,
        duplicate_cleaner_lock=duplicate_cleaner_lock,
        duplicate_cleaner_executor=duplicate_cleaner_executor,
        run_duplicate_cleaner=_run_duplicate_cleaner,
        run_repair_job_now=(
            lambda job_id, scope=None, respect_enabled=False: repair_worker.run_job_now(
                job_id, scope=scope, respect_enabled=respect_enabled)
            if repair_worker else None
        ),
        download_orchestrator=download_orchestrator,
        run_async=run_async,
        tasks_lock=tasks_lock,
        get_download_batches=lambda: download_batches,
        get_download_tasks=lambda: download_tasks,
        sweep_empty_download_directories=_sweep_empty_download_directories,
        get_staging_path=get_staging_path,
        docker_resolve_path=docker_resolve_path,
        get_current_profile_id=get_current_profile_id,
        get_watchlist_scanner=_get_watchlist_scanner_fn,
        get_app=lambda: app,
        get_beatport_data_cache=lambda: _beatport_api_cache,
        init_automation_progress=_init_automation_progress,
        record_progress_history=_auto_progress.record_history,
        build_personalized_manager=_build_personalized_manager,
        lastfm_import_worker=lastfm_import_worker,
    )
    _register_extracted_handlers(_automation_deps)

    # Bridge the isolated video download monitor's batch-complete signal into the
    # automation engine (core/video can't import the engine). Mirrors how the music
    # web_scan_manager forwards library_scan_completed. ONE forwarder relays EVERY
    # published video event (batch complete, download completed/failed, repair
    # findings, wishlist/watchlist changes, ...) to its same-named event trigger.
    if automation_engine is not None:
        try:
            from core.video.download_events import register_event_forwarder
            register_event_forwarder(
                lambda etype, data: automation_engine.emit(etype, data or {}))
        except Exception:
            logger.exception("Could not wire video events -> automation engine")
    # Notifications (arr-parity P11): a second forwarder fans the same events
    # out to configured Discord/webhook/Telegram connections. Independent of
    # the engine — notify still works if automations are off.
    try:
        from core.video.download_events import register_event_forwarder as _reg_fw
        from core.video.notifications import handle_event as _notify_handle
        _reg_fw(_notify_handle)
    except Exception:
        logger.exception("Could not wire video events -> notifications")

    logger.info("Automation action handlers registered")

