@app.route('/api/debug/memory/objects')
def debug_memory_objects():
    """One-shot memory breakdown by live object type (plain gc — NO tracemalloc, so it
    won't lock up a loaded app). Hit this once when RSS is high to see which type/cache
    dominates: a big 'count' reveals accumulation (a cache that never evicts); a big
    'mb' under bytes/str reveals blob retention. Pinpoints the leak without tracing."""
    import gc
    import sys
    from collections import defaultdict
    try:
        gc.collect()
        objs = gc.get_objects()
        counts = defaultdict(int)
        sizes = defaultdict(int)
        biggest = []
        for o in objs:
            tn = type(o).__name__
            counts[tn] += 1
            try:
                sz = sys.getsizeof(o)
            except Exception:
                sz = 0
            sizes[tn] += sz
            if sz > 1_000_000 and isinstance(o, (dict, list, set, frozenset, bytes, bytearray, str, tuple)):
                try:
                    biggest.append((sz, tn, len(o)))
                except Exception:  # noqa: S110 — debug stat, len() on an exotic obj is non-fatal
                    pass
        biggest.sort(reverse=True)
        rss = None
        try:
            import psutil
            rss = round(psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024), 1)
        except Exception:  # noqa: S110 — psutil optional; rss stays None in the debug payload
            pass
        return jsonify({
            'rss_mb': rss,
            'total_objects': len(objs),
            'top_by_size_mb': [
                {'type': t, 'count': counts[t], 'mb': round(sizes[t] / (1024 * 1024), 1)}
                for t, _ in sorted(sizes.items(), key=lambda x: x[1], reverse=True)[:20]
            ],
            'top_by_count': [
                {'type': t, 'count': c, 'mb': round(sizes[t] / (1024 * 1024), 1)}
                for t, c in sorted(counts.items(), key=lambda x: x[1], reverse=True)[:20]
            ],
            'biggest_containers': [
                {'mb': round(s / (1024 * 1024), 1), 'type': t, 'len': ln}
                for s, t, ln in biggest[:15]
            ],
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/activity/feed')
def get_activity_feed():
    """Get recent activity feed for dashboard"""
    try:
        with activity_feed_lock:
            # Return last 10 activities in reverse chronological order
            return jsonify({'activities': activity_feed[-10:][::-1]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/activity/toasts')
def get_recent_toasts():
    """Get recent activities that should show toasts"""
    try:
        import time
        current_time = time.time()

        with activity_feed_lock:
            # Return activities from last 10 seconds that should show toasts
            recent_toasts = [
                activity for activity in activity_feed
                if activity.get('show_toast', True) and
                   (current_time - activity.get('timestamp', 0)) <= 10
            ]
            return jsonify({'toasts': recent_toasts})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/logs')
def get_activity_logs():
    """Get formatted activity feed for display in sync page log area"""
    try:
        with activity_feed_lock:
            # Get the last 50 activities (more than the dashboard shows)
            recent_activities = activity_feed[-50:] if len(activity_feed) > 50 else activity_feed[:]

            # Reverse order so newest appears at top
            recent_activities = recent_activities[::-1]

            # Format activities as readable log entries
            formatted_logs = []

            if not recent_activities:
                formatted_logs = [
                    "No recent activity.",
                    "Sync and download operations will appear here in real-time."
                ]
            else:
                for activity in recent_activities:
                    # Format: [TIME] ICON TITLE - SUBTITLE
                    timestamp = activity.get('time', 'Unknown')
                    icon = activity.get('icon', '•')
                    title = activity.get('title', 'Activity')
                    subtitle = activity.get('subtitle', '')

                    # Create a clean, readable log entry
                    if subtitle:
                        log_entry = f"[{timestamp}] {icon} {title} - {subtitle}"
                    else:
                        log_entry = f"[{timestamp}] {icon} {title}"

                    formatted_logs.append(log_entry)

            return jsonify({'logs': formatted_logs})

    except Exception as e:
        return jsonify({'logs': [f'Error reading activity feed: {str(e)}']})

