@app.route('/api/v1/api-keys-internal', methods=['GET'])
@admin_only
def list_api_keys_internal():
    """List API keys for the settings page (no auth required — same as all UI routes)."""
    keys = config_manager.get('api_keys', [])
    safe_keys = [
        {
            "id": k.get("id"),
            "label": k.get("label", ""),
            "key_prefix": k.get("key_prefix", ""),
            "created_at": k.get("created_at"),
            "last_used_at": k.get("last_used_at"),
        }
        for k in keys
    ]
    return jsonify({"success": True, "data": {"keys": safe_keys}})

@app.route('/api/v1/api-keys-internal/generate', methods=['POST'])
@admin_only
def generate_api_key_internal():
    """Generate API key from settings page (no auth required)."""
    from api.auth import generate_api_key
    body = request.get_json(silent=True) or {}
    label = body.get("label", "")
    raw_key, record = generate_api_key(label)
    keys = config_manager.get('api_keys', [])
    keys.append(record)
    config_manager.set('api_keys', keys)
    return jsonify({"success": True, "data": {
        "key": raw_key,
        "id": record["id"],
        "label": record["label"],
        "key_prefix": record["key_prefix"],
        "created_at": record["created_at"],
    }}), 201

@app.route('/api/v1/api-keys-internal/revoke/<key_id>', methods=['DELETE'])
@admin_only
def revoke_api_key_internal(key_id):
    """Revoke API key from settings page (no auth required)."""
    keys = config_manager.get('api_keys', [])
    original_len = len(keys)
    keys = [k for k in keys if k.get("id") != key_id]
    if len(keys) == original_len:
        return jsonify({"success": False, "error": {"message": "Key not found"}}), 404
    config_manager.set('api_keys', keys)
    return jsonify({"success": True, "data": {"message": "API key revoked"}})


@app.route('/api/settings', methods=['GET', 'POST'])
@admin_only
def handle_settings():
    global tidal_client # Declare that we might modify the global instance
    if not config_manager:
        return jsonify({"error": "Server configuration manager is not initialized."}), 500
    if request.method == 'POST':
        try:
            new_settings = request.get_json()
            if not new_settings:
                return jsonify({"success": False, "error": "No data received."}), 400

            # Validate connection settings before persisting any part of the form.
            if 'musicbrainz' in new_settings:
                from core.musicbrainz_client import validate_server_settings
                mb_settings = new_settings['musicbrainz']
                if not isinstance(mb_settings, dict):
                    return jsonify({"success": False, "error": "MusicBrainz settings must be an object."}), 400
                try:
                    mb_url, mb_interval = validate_server_settings(
                        mb_settings.get('base_url', config_manager.get('musicbrainz.base_url')),
                        mb_settings.get('request_interval', config_manager.get('musicbrainz.request_interval')))
                except ValueError as exc:
                    return jsonify({"success": False, "error": str(exc)}), 400
                mb_settings.update(base_url=mb_url, request_interval=mb_interval)

            # Anti-lockout: refuse to turn ON login mode until the admin account
            # has a password — otherwise enabling it would lock everyone out.
            _sec_in = new_settings.get('security') or {}
            if _sec_in.get('require_login') and not config_manager.get('security.require_login', False):
                if not get_database().profile_has_password(1):
                    return jsonify({"success": False,
                                    "error": "Set an admin password before enabling login mode."}), 400
                # No-gaps: every member must have a password too, or they'd be
                # locked out the moment login turns on.
                from core.security.login_provisioning import members_without_password
                _stranded = members_without_password(get_database().get_all_profiles())
                if _stranded:
                    _names = ', '.join(str(m.get('name') or '?') for m in _stranded)
                    return jsonify({"success": False,
                                    "error": f"These members have no login password and "
                                             f"couldn't sign in: {_names}. Set their passwords "
                                             f"in Manage Profiles first.",
                                    "members_without_password": _stranded}), 400

            # YouTube pasted cookies.txt (server/Docker path): pull it out BEFORE the
            # generic persist so the raw cookie blob never lands in config.json — it's
            # secret + bulky. We validate up front and store only a file path.
            _yt_in = new_settings.get('youtube')
            _yt_paste = _yt_in.pop('cookies_paste', None) if isinstance(_yt_in, dict) else None
            if _yt_paste is not None and str(_yt_paste).strip():
                from core.youtube_cookies import looks_like_cookiefile, write_pasted_cookiefile
                if not looks_like_cookiefile(_yt_paste):
                    return jsonify({"success": False,
                                    "error": "That doesn't look like a cookies.txt file. Export it "
                                             "with a 'Get cookies.txt LOCALLY' browser extension and "
                                             "paste the whole file."}), 400
                _cookie_path = str(config_manager.config_path.parent / "youtube_cookies.txt")
                if write_pasted_cookiefile(_yt_paste, _cookie_path):
                    config_manager.set('youtube.cookies_file', _cookie_path)

            _experimental_in = new_settings.get('experimental')
            _metadata_in = new_settings.get('metadata')

            from core.metadata.registry import resolve_settings_metadata_primary
            _primary_err, _primary_override = resolve_settings_metadata_primary(
                _experimental_in,
                _metadata_in,
                config_manager.get,
            )
            if _primary_err:
                return jsonify({"success": False, "error": _primary_err}), 400

            if 'active_media_server' in new_settings:
                config_manager.set_active_media_server(new_settings['active_media_server'])

            # ONE database write for the whole page save. Per-leaf saves were
            # hundreds of encrypt+serialize+commit cycles per click — enough
            # self-inflicted lock contention to shove the config onto the
            # (previously non-atomic) JSON fallback path (#1137).
            with config_manager.batch():
                if isinstance(_experimental_in, dict):
                    for key, value in _experimental_in.items():
                        config_manager.set(f'experimental.{key}', value)

                for service in ['spotify', 'plex', 'jellyfin', 'navidrome', 'soulseek', 'download_source', 'settings', 'database', 'metadata_enhancement', 'file_organization', 'playlist_sync', 'tidal', 'tidal_download', 'qobuz', 'hifi_download', 'deezer_download', 'amazon_download', 'lidarr_download', 'prowlarr', 'torrent_client', 'usenet_client', 'listenbrainz', 'acoustid', 'lastfm', 'genius', 'import', 'lossy_copy', 'album_downloads', 'listening_stats', 'ui_appearance', 'youtube', 'content_filter', 'itunes', 'm3u_export', 'musicbrainz', 'deezer', 'audiodb', 'metadata', 'hydrabase', 'security', 'discogs', 'concerts', 'library', 'discover', 'wishlist', 'genre_whitelist', 'post_processing', 'playlists', 'experimental', 'image_cache']:
                    if service in new_settings:
                        if service == 'experimental' and isinstance(_experimental_in, dict):
                            continue
                        for key, value in new_settings[service].items():
                            config_manager.set(f'{service}.{key}', value)

                if _primary_override:
                    config_manager.set('metadata.fallback_source', _primary_override)

            # The Settings → Quality page's toggles are saved as config keys
            # (above), but the pipeline enforces the PROFILE row (live, per
            # item). Write the quality-owned keys through to the active
            # default profile so "the page edits the active profile" holds —
            # without this, a checkbox change here would never reach the
            # pipeline (see MusicDatabase.sync_default_quality_profile_from_config).
            if 'image_cache' in new_settings:
                # The cache is a singleton built from config on first use, so a
                # new size limit would otherwise not apply until a restart.
                try:
                    from core.image_cache import reset_image_cache
                    reset_image_cache()
                except Exception as _ic_err:
                    logger.debug("image cache reset after settings save failed: %s", _ic_err)

            if 'concerts' in new_settings:
                # Answers are cached for six hours. Without this, fixing a
                # rejected API key would keep showing the failure it produced
                # for the rest of the afternoon, which reads as "my key doesn't
                # work" rather than "the old answer is still cached".
                try:
                    from core.concerts_client import clear_cache as _clear_concerts
                    _clear_concerts()
                except Exception as _cc_err:
                    logger.debug("concert cache clear after settings save failed: %s", _cc_err)

            if any(s in new_settings for s in ('acoustid', 'lossy_copy', 'post_processing', 'import')):
                try:
                    get_database().sync_default_quality_profile_from_config()
                except Exception as _qp_sync_err:
                    logger.error(f"Default quality profile sync failed: {_qp_sync_err}")

            logger.info("Settings saved successfully via Web UI.")

            # Add activity for settings save
            changed_services = list(new_settings.keys())
            services_text = ", ".join(changed_services)
            add_activity_item("", "Settings Updated", f"{services_text} configuration saved", "Now")

            # Reload service clients with new settings (guard against None from partial init)
            if spotify_client:
                spotify_client.reload_config()
            if media_server_engine.client('plex'):
                media_server_engine.client('plex').server = None
            if media_server_engine.client('jellyfin'):
                media_server_engine.client('jellyfin').reload_config()
            if media_server_engine.client('navidrome'):
                media_server_engine.client('navidrome').reload_config()
            # Reload orchestrator settings (download source mode, hybrid_primary, etc.)
            if download_orchestrator:
                download_orchestrator.reload_settings()
                # Reload YouTube client settings (rate limiting, cookies)
                _yt = download_orchestrator.client("youtube")
                if _yt:
                    _yt.reload_settings()
            # FIX: Re-instantiate the global tidal_client to pick up new settings
            try:
                tidal_client = TidalClient()
            except Exception as e:
                logger.debug("tidal client re-init: %s", e)
            # Reload enrichment worker clients for key-based services
            if lastfm_worker:
                lastfm_worker._init_client()
            if genius_worker:
                genius_worker._init_client()
            if tidal_enrichment_worker:
                tidal_enrichment_worker.client = tidal_client
            if 'spotify' in new_settings:
                publish_spotify_status(
                    connected=False,
                    authenticated=False,
                    rate_limited=False,
                    rate_limit=None,
                    post_ban_cooldown=None,
                )
            # Invalidate status cache so next poll reflects new settings (e.g. fallback source change)
            invalidate_metadata_status_caches()
            logger.info("Service clients re-initialized with new settings.")
            return jsonify({"success": True, "message": "Settings saved successfully."})
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500
    else:  # GET request
        try:
            # Masks every configured secret (API keys, tokens, passwords) as a
            # sentinel so decrypted credentials never reach the browser/devtools/
            # HAR captures (#832 follow-up). Deep copy — safe to mutate below.
            data = config_manager.redacted_config()
            # Also drop the Spotify OAuth token payload — not a settings field
            # and not in the sensitive-paths list.
            if isinstance(data.get('spotify'), dict) and 'token_info' in data['spotify']:
                data['spotify'] = {k: v for k, v in data['spotify'].items() if k != 'token_info'}
            # Include which download sources are configured so the UI can auto-disable unconfigured ones
            try:
                data['_source_status'] = download_orchestrator.get_source_status()
            except Exception as e:
                logger.debug("download source status read failed: %s", e)
            # Deployment environment: the folder-paths guidance differs by world
            # (Docker: leave container paths alone / bare-metal-LXC: you MUST edit
            # them). A fresh non-Docker install still on the ./Transfer default
            # dumps every download onto the install disk — Proxmox LXCs default
            # to an 8GB root, which fills until the container hangs — so the UI
            # needs to know which story to tell and when to warn.
            data['_environment'] = {'docker': os.path.exists('/.dockerenv')}
            return jsonify(data)
        except Exception as e:
            return jsonify({"error": str(e)}), 500


