@app.route('/api/config/export', methods=['GET'])
@admin_only
def export_config_bundle():
    """One portable JSON bundle for BOTH sides. ?secrets=1 embeds real
    credentials (plaintext — the UI gates this behind an explicit opt-in);
    default redacts them so the export is safe to share."""
    if not config_manager:
        return jsonify({"error": "Config manager unavailable"}), 500
    from datetime import datetime, timezone

    from api.video import get_video_db
    from core.config_export import build_bundle
    include_secrets = request.args.get('secrets', '0') in ('1', 'true', 'yes')
    # Plaintext-credential export is the ONLY endpoint that leaks real secrets,
    # so it must sit behind actual authentication. With login OFF, @admin_only
    # trusts every LAN request as admin — refuse, or anyone who can reach the
    # port could pull every key. The redacted export stays available to all.
    if include_secrets and not _require_login_enabled():
        return jsonify({
            "success": False,
            "error": "Exporting credentials requires login mode. Enable "
                     "Settings → Security → Require login first, or export "
                     "without credentials (they'll be re-entered on the new install).",
        }), 403
    bundle = build_bundle(
        config_manager, get_video_db(),
        include_secrets=include_secrets,
        exported_at=datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),
        app_version=SOULSYNC_VERSION.split('+')[0],
    )
    return jsonify(bundle)


@app.route('/api/config/import', methods=['POST'])
@admin_only
def import_config_bundle():
    """Apply a config bundle exported from another install. Validates the
    marker/version first; a secrets-redacted bundle never blanks existing
    credentials (the config_manager's per-leaf guard skips the mask)."""
    if not config_manager:
        return jsonify({"error": "Config manager unavailable"}), 500
    from api.video import get_video_db
    from core.config_export import apply_bundle
    data = request.get_json(silent=True)
    try:
        summary = apply_bundle(config_manager, get_video_db(), data or {})
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    except Exception as e:   # noqa: BLE001
        logger.exception("config import failed")
        return jsonify({"success": False, "error": str(e)}), 500
    return jsonify({"success": True, **summary,
                    "note": "Config imported. Restart SoulSync so every service picks it up."})


# ── Per-service verify cache ──
# Stores the last verify result per service for 5 minutes to prevent
# hammering external APIs when the user rapidly expands/collapses cards.
_settings_verify_cache = {}    # service -> {'success': bool, 'message': str, 'error': str, 'ts': float}
_settings_verify_cache_lock = threading.Lock()
_SETTINGS_VERIFY_TTL_SECONDS = 300


def _get_cached_verify_result(service: str):
    with _settings_verify_cache_lock:
        entry = _settings_verify_cache.get(service)
        if entry and (time.time() - entry['ts']) < _SETTINGS_VERIFY_TTL_SECONDS:
            return entry
        return None


def _store_verify_result(service: str, success: bool, message: str):
    with _settings_verify_cache_lock:
        _settings_verify_cache[service] = {
            'success': bool(success),
            'message': message or '',
            'error': '' if success else (message or 'Unknown error'),
            'ts': time.time(),
        }


def _run_single_verify(service: str):
    """Run verify for one service, reading its current saved config. Returns cached
    result if recent, else executes run_service_test and caches the outcome.
    """
    if service not in SERVICE_CONFIG_REGISTRY:
        return {'success': False, 'error': f'Unknown service: {service}', 'cached': False}

    cached = _get_cached_verify_result(service)
    if cached:
        return {
            'success': cached['success'],
            'error': cached.get('error', ''),
            'message': cached.get('message', ''),
            'cached': True,
        }

    try:
        saved_config = config_manager.get(service, {}) or {}
        success, message = run_service_test(service, saved_config)
        _store_verify_result(service, success, message)
        return {
            'success': bool(success),
            'error': '' if success else (message or 'Verification failed'),
            'message': message or '',
            'cached': False,
        }
    except Exception as e:
        logger.error(f"verify error for {service}: {e}")
        _store_verify_result(service, False, str(e))
        return {'success': False, 'error': str(e), 'cached': False}


@app.route('/api/settings/verify', methods=['POST'])
@admin_only
def settings_verify_endpoint():
    """Run connection verification for one or more services.

    Body:  {"services": ["spotify", "deezer"]}  — which services to check
    Query: ?force=true                           — bust cache and re-run
    Returns {service: {success, error, message, cached}} per requested service.
    Concurrency capped at 3 to avoid rate-limiting ourselves on Expand All.
    """
    try:
        data = request.get_json(silent=True) or {}
        services = data.get('services') or []
        if isinstance(services, str):
            services = [services]
        if not services:
            return jsonify({'error': 'No services specified'}), 400

        force = (request.args.get('force') or '').strip().lower() in ('1', 'true', 'yes')
        if force:
            with _settings_verify_cache_lock:
                for svc in services:
                    _settings_verify_cache.pop(svc, None)

        from concurrent.futures import ThreadPoolExecutor, as_completed
        results = {}
        with ThreadPoolExecutor(max_workers=3) as pool:
            futures = {pool.submit(_run_single_verify, svc): svc for svc in services}
            for fut in as_completed(futures):
                svc = futures[fut]
                try:
                    results[svc] = fut.result()
                except Exception as e:
                    results[svc] = {'success': False, 'error': str(e), 'cached': False}

        return jsonify(results)
    except Exception as e:
        logger.error(f"settings/verify error: {e}")
        return jsonify({'error': str(e)}), 500


@app.route('/api/test-dashboard-connection', methods=['POST'])
def test_dashboard_connection_endpoint():
    """Test connection from dashboard - creates specific dashboard activity items"""
    data = request.get_json()
    service = data.get('service')
    if not service:
        return jsonify({"success": False, "error": "No service specified."}), 400

    logger.info(f"Received dashboard test connection request for: {service}")

    # Get the current settings from the main config manager to test with
    test_config = config_manager.get(service, {})

    # For media servers, the service name might be 'server'
    if service == 'server':
        active_server = config_manager.get_active_media_server()
        test_config = config_manager.get(active_server, {})
        service = active_server # use the actual server name for the test

    success, message = run_service_test(service, test_config)

    # Update status cache immediately when test succeeds to reflect current state
    import time
    if success:
        current_time = time.time()
        if service == 'spotify':
            invalidate_metadata_status_caches()
            logger.info("Updated Spotify status cache after successful dashboard test")
        elif service in ['plex', 'jellyfin', 'navidrome', 'soulsync']:
            _status_cache['media_server']['connected'] = True
            _status_cache['media_server']['type'] = service
            _status_cache_timestamps['media_server'] = current_time
            logger.info(f"Updated {service} status cache after successful dashboard test")
        elif service == 'soulseek':
            _status_cache['soulseek']['connected'] = True
            _status_cache_timestamps['soulseek'] = current_time
            logger.info("Updated Soulseek status cache after successful dashboard test")

    # Add activity for dashboard connection test (different from settings test)
    if success:
        add_activity_item("", "Dashboard Test", message, "Now")
    else:
        add_activity_item("", "Dashboard Test", f"{service.title()} service check failed", "Now")

    return jsonify({"success": success, "error": "" if success else message, "message": message if success else ""})

