def _sync_tracks_to_server(track_rows, server_type):
    """Sync metadata for tracks to the active media server after writing file tags.

    Args:
        track_rows: list of track dicts (must include 'id', 'title', 'artist_name', 'album_title', 'year', 'server_source')
        server_type: 'plex', 'jellyfin', or 'navidrome'

    Returns:
        dict with 'synced', 'failed', 'skipped' counts and 'errors' list
    """
    result = {'synced': 0, 'failed': 0, 'skipped': 0, 'errors': []}

    if server_type == 'navidrome':
        # Navidrome auto-detects file tag changes, no action needed
        result['synced'] = len(track_rows)
        return result

    if server_type == 'plex':
        for track_data in track_rows:
            # Only sync tracks that came from this server
            if track_data.get('server_source') and track_data['server_source'] != 'plex':
                result['skipped'] += 1
                continue
            try:
                metadata = {}
                if track_data.get('title'):
                    metadata['title'] = track_data['title']
                if track_data.get('artist_name'):
                    metadata['artist'] = track_data['artist_name']
                if track_data.get('album_title'):
                    metadata['album'] = track_data['album_title']
                if track_data.get('year'):
                    metadata['year'] = track_data['year']
                if metadata:
                    success = media_server_engine.client('plex').update_track_metadata(str(track_data['id']), metadata)
                    if success:
                        result['synced'] += 1
                    else:
                        result['failed'] += 1
                        result['errors'].append({'track_id': track_data['id'], 'error': 'Plex update returned false'})
                else:
                    result['skipped'] += 1
            except Exception as e:
                result['failed'] += 1
                result['errors'].append({'track_id': track_data['id'], 'error': str(e)})

    elif server_type == 'jellyfin':
        # Jellyfin: just trigger a library scan once after all file writes
        try:
            success = media_server_engine.client('jellyfin').trigger_library_scan()
            if success:
                result['synced'] = len(track_rows)
            else:
                result['failed'] = len(track_rows)
                result['errors'].append({'error': 'Jellyfin library scan failed'})
        except Exception as e:
            result['failed'] = len(track_rows)
            result['errors'].append({'error': f'Jellyfin scan error: {e}'})

    return result


_resolve_library_diag_logged = False


def _resolve_library_file_path(file_path):
    """Resolve a library file path to an actual file on disk."""
    if not file_path:
        return None
    if os.path.exists(file_path):
        return file_path

    # Try resolving server-side paths to local directories
    # Check transfer path, download path, and media server library paths
    transfer_dir = docker_resolve_path(config_manager.get('soulseek.transfer_path', './Transfer'))
    download_dir = docker_resolve_path(config_manager.get('soulseek.download_path', './downloads'))

    # Also check the media server's music library path (handles Docker↔host path mismatch).
    # ``get_music_library_locations`` handles both single-library mode and
    # all-libraries mode (unions location paths across every music section).
    library_dirs = set()
    try:
        plex = media_server_engine.client('plex')
        if plex and plex.server:
            for loc in plex.get_music_library_locations():
                library_dirs.add(loc)
    except Exception as e:
        logger.debug("plex library locations lookup failed: %s", e)

    # Check user-configured music library paths (Settings > Library)
    try:
        music_paths = config_manager.get('library.music_paths', [])
        if isinstance(music_paths, list):
            for p in music_paths:
                if p and isinstance(p, str):
                    resolved_p = docker_resolve_path(p.strip())
                    if resolved_p:
                        library_dirs.add(resolved_p)
    except Exception as e:
        logger.debug("library music paths read failed: %s", e)

    # Build the set of candidate base directories (absolute forms only, so
    # os.path.join produces unambiguous paths). Config often stores RELATIVE
    # paths ("./Transfer") — take os.path.abspath() so they resolve from the
    # current working directory of the server process.
    library_dir_list = list(library_dirs)
    raw_bases = [transfer_dir, download_dir] + library_dir_list
    abs_bases = []
    seen_abs = set()
    for b in raw_bases:
        if not b:
            continue
        for form in [os.path.abspath(b), b, '/' + b.replace('./', '', 1).lstrip('/')]:
            a = os.path.abspath(form) if not os.path.isabs(form) else form
            if a and a not in seen_abs and os.path.isdir(a):
                seen_abs.add(a)
                abs_bases.append(a)

    # --- Fast path: direct join ---
    # When the DB stores a clean relative path ("Artist/Album/Track.flac") this
    # is all that's needed. No component-by-component descent, no confusable
    # folding. This handles the common Docker case where CWD is /app, config
    # says ./Transfer, and files live at /app/Transfer/Artist/Album/Track.flac.
    clean_rel = file_path.replace('\\', '/')
    for abs_base in abs_bases:
        candidate = os.path.join(abs_base, clean_rel)
        if os.path.exists(candidate):
            logger.debug("[PathResolve] direct join: %r → %r", file_path, candidate)
            return candidate

    # --- Slow path: confusable-tolerant suffix scan ---
    # Handles paths with typographic apostrophes/dashes that differ between the
    # DB metadata and the actual on-disk filename (#833).
    path_parts = clean_rel.split('/')
    from core.library.path_resolve import find_on_disk
    for abs_base in abs_bases:
        for i in range(0, len(path_parts)):
            found = find_on_disk(abs_base, path_parts[i:])
            if found:
                return found

    # --- Last resort: wrong INTERIOR segment (#1127) ---
    # Everything above can only repair a wrong PREFIX. Navidrome synthesizes the
    # Subsonic path from tags, so the album folder AND the filename can both be
    # wrong. Shared with core/library/path_resolver so the repair jobs and this
    # resolver can't drift — this copy never had the sibling-album step at all,
    # which is why the same library resolved from a repair job and failed here.
    try:
        from core.library.path_resolver import resolve_via_last_resort_fallbacks
        interior = resolve_via_last_resort_fallbacks(clean_rel, abs_bases)
        if interior:
            logger.debug("[PathResolve] interior-segment fallback: %r → %r", file_path, interior)
            return interior
    except Exception as e:
        logger.debug("[PathResolve] interior-segment fallback failed: %s", e)

    # Couldn't resolve — log the bases we searched, throttled to once per 10
    # minutes. The old once-per-PROCESS guard self-silenced forever, which hid
    # intermittent failures completely (TheHomeGuy: an NFS mount that drops and
    # comes back reads as 'occasionally get this error' with no pattern —
    # because all the other occurrences were swallowed).
    global _resolve_library_diag_logged
    _now = time.monotonic()
    if not isinstance(_resolve_library_diag_logged, float) or _now - _resolve_library_diag_logged > 600:
        _resolve_library_diag_logged = _now
        # Name the FAILURE MODE, not just the miss: a genuinely absent file
        # stats as ENOENT, while a broken NFS/bind mount surfaces ESTALE or
        # EIO — and a base dir that suddenly lists 0 entries is an unmounted
        # mountpoint. Turns "file not found, shrug" into "the mount under it
        # is broken" (TheHomeGuy's Proxmox LXC bind-of-NFS).
        import errno as _errno
        _stat_err = 'ENOENT (plain not-found)'
        try:
            os.stat(file_path)
        except OSError as _se:
            _stat_err = '%s (errno=%s)' % (_errno.errorcode.get(_se.errno, type(_se).__name__), _se.errno)
        _base_counts = []
        for _b in abs_bases:
            try:
                _base_counts.append('%s: %d entries' % (_b, len(os.listdir(_b))))
            except OSError as _le:
                _base_counts.append('%s: UNLISTABLE (%s)' % (_b, _errno.errorcode.get(_le.errno, type(_le).__name__)))
        logger.warning(
            "[PathResolve] Could not resolve %r — tried direct-join + suffix-scan under %r (cwd=%r). "
            "Raw-path stat: %s. Base dirs: %s. "
            "If files live elsewhere, set soulseek.transfer_path to the absolute mount or add "
            "the dir under Settings > Library music paths. A base showing 0 entries or "
            "ESTALE/EIO means the mount under it is broken (remount / restart the container).",
            file_path, abs_bases, os.getcwd(), _stat_err, '; '.join(_base_counts) or 'none',
        )
    return None


def _build_library_stream_url(track_id, file_path):
    """Build a media-server stream URL for a library track that isn't on the
    SoulSync filesystem (#809 — play via the server's API, no disk mount).

    Navidrome/Subsonic only for now (it has a clean token-authed stream
    endpoint). ``track_id`` is the server's mapped song id; if missing, look it
    up by file_path. Returns None when the
    active server isn't Navidrome or no id resolves."""
    try:
        if config_manager.get_active_media_server() != 'navidrome':
            return None
        client = media_server_engine.client('navidrome')
        if not client:
            return None

        song_id = str(track_id) if track_id else None
        if not song_id and file_path:
            # Fall back to a DB lookup by stored path (handles callers that
            # didn't pass the id).
            try:
                db = get_database()
                with db._get_connection() as conn:
                    row = conn.cursor().execute(
                        "SELECT m.server_id FROM lib2_track_files f "
                        "JOIN lib2_media_server_mappings m ON m.entity_type='track' "
                        "AND m.entity_id=f.track_id AND m.server_source='navidrome' "
                        "WHERE f.path = ? LIMIT 1",
                        (file_path,)).fetchone()
                if row and row[0]:
                    song_id = str(row[0])
            except Exception as e:
                logger.debug("navidrome stream id lookup failed: %s", e)
        if not song_id:
            return None
        return client.build_stream_url(song_id)
    except Exception as e:
        logger.debug("build library stream url failed: %s", e)
        return None


def _get_file_not_found_error(file_path):
    """Return a helpful error message when a library file can't be found."""
    active_server = config_manager.get_active_media_server()
    if active_server == 'navidrome':
        # Check if path looks like a Navidrome fake path (no real filesystem root)
        # Fake paths look like: "Artist/Album/01 - Track.flac" or just "Track.flac"
        if file_path and ('/' not in file_path or not file_path.startswith('/')):
            return ('File not found — Navidrome may be sending virtual paths. '
                    'Go to Navidrome → Profile → Players → select SoulSync → enable "Report Real Path", '
                    'then run a full database refresh in SoulSync.')
        return ('File not found on disk — check that your Navidrome music folder '
                'is mounted in the SoulSync container and that "Report Real Path" is enabled '
                'in Navidrome\'s player settings.')
    return 'File not found on disk'


@app.route('/api/library/play', methods=['POST'])
def library_play_track():
    """Start playing a track directly from the user's library (no download needed)."""
    try:
        data = request.get_json()
        if not data or not data.get('file_path'):
            return jsonify({"success": False, "error": "file_path is required"}), 400

        file_path = data['file_path']

        # Resolve server-side paths (e.g. /mnt/musicBackup/...) to local transfer path
        resolved = _resolve_library_file_path(file_path)
        stream_url = None
        if resolved:
            file_path = resolved
        else:
            # Not on disk. For a streaming server (Navidrome/Subsonic) we can
            # play it through the server's own stream API instead of requiring
            # the library to be mounted into the SoulSync container (#809).
            server_track_id = (
                data.get('server_track_id') or data.get('legacy_track_id')
                or (None if data.get('lib2_track_id') else data.get('track_id'))
            )
            if not server_track_id and data.get('lib2_track_id'):
                active_server = config_manager.get_active_media_server()
                if active_server in ('plex', 'jellyfin', 'navidrome'):
                    with get_database()._get_connection() as conn:
                        row = conn.execute(
                            "SELECT server_id FROM lib2_media_server_mappings "
                            "WHERE entity_type='track' AND entity_id=? "
                            "AND server_source=? LIMIT 1",
                            (data.get('lib2_track_id'), active_server),
                        ).fetchone()
                    server_track_id = row[0] if row else None
            stream_url = _build_library_stream_url(server_track_id, file_path)
            if not stream_url:
                return jsonify({"success": False, "error": _get_file_not_found_error(file_path)}), 404

        if stream_url:
            logger.info("Library play request (server stream): %s",
                        data.get('title') or os.path.basename(file_path or ''))
        else:
            logger.info(f"Library play request: {os.path.basename(file_path)}")

        # Set THIS listener's stream state to ready. Either a local file_path
        # (served from disk) or a stream_url (proxied from the media server).
        sess = _current_stream_state()
        with sess.lock:
            sess.update({
                "status": "ready",
                "progress": 100,
                "track_info": {
                    "title": data.get('title', os.path.basename(file_path or '')),
                    "artist": data.get('artist', 'Unknown Artist'),
                    "album": data.get('album', 'Unknown Album'),
                },
                "file_path": None if stream_url else file_path,
                "stream_url": stream_url,
                "error_message": None,
                "is_library": True
            })

        return jsonify({"success": True, "message": "Library track ready for playback"})

    except Exception as e:
        logger.error(f"Error playing library track: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/library/log-play', methods=['POST'])
def library_log_play():
    """Record a SoulSync web-player play into listening_history + bump the
    track's play_count/last_played (feeds 'recently played' and smart radio).

    Fire-and-forget from the frontend ~10s into a track. Best-effort: a logging
    failure never affects playback, so we always return 200-ish.
    """
    try:
        from core.playback.play_log import build_play_event
        data = request.get_json(silent=True) or {}
        track = data.get('track') or data
        played_at = datetime.now().isoformat()
        duration_ms = data.get('duration_ms', 0)
        event = build_play_event(track, played_at, duration_ms)
        if not event:
            return jsonify({"success": False, "skipped": True}), 200
        get_database().record_web_player_play(event)
        return jsonify({"success": True})
    except Exception as e:
        logger.debug(f"log-play failed (non-fatal): {e}")
        return jsonify({"success": False, "error": str(e)}), 200

_enrichment_locks = {svc: threading.Lock() for svc in ('audiodb', 'deezer', 'musicbrainz', 'spotify', 'itunes', 'lastfm', 'genius', 'tidal', 'qobuz', 'discogs', 'bandcamp', 'jiosaavn')}

@app.route('/api/library/enrich', methods=['POST'])
def library_enrich_entity():
    """Trigger enrichment of a specific entity from a single service.
    Body: { entity_type: 'artist'|'album'|'track', entity_id: str, service: str,
            name: str, artist_name: str? }
    service: 'audiodb', 'deezer', 'musicbrainz', 'spotify', 'itunes', 'lastfm', 'genius', 'tidal', 'qobuz'
    """
    try:
        data = request.get_json()
        if not data:
            return jsonify({"success": False, "error": "No data provided"}), 400

        entity_type = data.get('entity_type')  # artist, album, track
        entity_id = data.get('entity_id')
        service = data.get('service')
        name = data.get('name', '')
        artist_name = data.get('artist_name', '')

        if not entity_type or not entity_id or not service:
            return jsonify({"success": False, "error": "entity_type, entity_id, and service are required"}), 400

        if entity_type not in ('artist', 'album', 'track'):
            return jsonify({"success": False, "error": "entity_type must be artist, album, or track"}), 400

        valid_services = ('audiodb', 'deezer', 'musicbrainz', 'spotify', 'itunes', 'lastfm', 'genius', 'tidal', 'qobuz', 'discogs', 'bandcamp', 'jiosaavn')
        if service not in valid_services:
            return jsonify({"success": False, "error": f"service must be one of: {', '.join(valid_services)}"}), 400

        # Per-service lock to avoid thread-safety issues with shared worker clients
        lock = _enrichment_locks.get(service)
        if not lock:
            return jsonify({"success": False, "error": f"Unknown service: {service}"}), 400

        acquired = lock.acquire(blocking=False)
        if not acquired:
            return jsonify({"success": False, "error": f"{service} enrichment already in progress. Please wait."}), 429

        try:
            results = {}
            try:
                result = _run_single_enrichment(service, entity_type, entity_id, name, artist_name)
                results[service] = result
            except Exception as e:
                results[service] = {"success": False, "error": str(e)}
        finally:
            lock.release()

        # Re-fetch updated data to return fresh state
        database = get_database()
        updated = database.get_artist_full_detail(
            data.get('artist_id', entity_id) if entity_type == 'artist' else
            _get_artist_id_for_entity(database, entity_type, entity_id)
        )

        # Fix image URLs in updated data
        if updated.get('success'):
            if updated.get('artist', {}).get('thumb_url'):
                updated['artist']['thumb_url'] = fix_artist_image_url(updated['artist']['thumb_url'])
            for album in updated.get('albums', []):
                if album.get('thumb_url'):
                    album['thumb_url'] = fix_artist_image_url(album['thumb_url'])

        return jsonify({
            "success": True,
            "results": results,
            "updated_data": updated if updated.get('success') else None
        })

    except Exception as e:
        logger.error(f"Error enriching entity: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"success": False, "error": str(e)}), 500


def _get_artist_id_for_entity(database, entity_type, entity_id):
    """Look up the artist_id for an album or track."""
    try:
        with database._get_connection() as conn:
            cursor = conn.cursor()
            if entity_type == 'album':
                cursor.execute("SELECT primary_artist_id AS artist_id FROM lib2_albums WHERE id = ?", (entity_id,))
            elif entity_type == 'track':
                cursor.execute(
                    "SELECT al.primary_artist_id AS artist_id FROM lib2_tracks t"
                    "  JOIN lib2_albums al ON al.id = t.album_id WHERE t.id = ?", (entity_id,))
            else:
                return entity_id
            row = cursor.fetchone()
            return row['artist_id'] if row else entity_id
    except Exception:
        return entity_id


def _run_single_enrichment(service, entity_type, entity_id, name, artist_name):
    """Run a single enrichment service on a single entity."""
    if service == 'audiodb':
        if not audiodb_worker:
            return {"success": False, "error": "AudioDB worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name}
        if entity_type in ('album', 'track'):
            item['artist'] = artist_name
        audiodb_worker._process_item(item)
        return {"success": True, "message": f"AudioDB lookup complete for {entity_type}"}

    elif service == 'deezer':
        if not deezer_worker:
            return {"success": False, "error": "Deezer worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name, 'artist': artist_name}
        if entity_type == 'artist':
            deezer_worker._process_artist(entity_id, name)
        elif entity_type == 'album':
            deezer_worker._process_album(entity_id, name, artist_name, item)
        elif entity_type == 'track':
            deezer_worker._process_track(entity_id, name, artist_name, item)
        return {"success": True, "message": f"Deezer lookup complete for {entity_type}"}

    elif service == 'jiosaavn':
        if not jiosaavn_worker:
            return {"success": False, "error": "JioSaavn worker not initialized"}
        from core.metadata.registry import is_jiosaavn_enabled
        if not is_jiosaavn_enabled():
            return {"success": False, "error": "JioSaavn is disabled (experimental feature off)"}
        if entity_type == 'artist':
            jiosaavn_worker._process_artist(entity_id, name)
        elif entity_type == 'album':
            jiosaavn_worker._process_album(entity_id, name, artist_name)
        elif entity_type == 'track':
            jiosaavn_worker._process_track(entity_id, name, artist_name)
        return {"success": True, "message": f"JioSaavn lookup complete for {entity_type}"}

    elif service == 'musicbrainz':
        if not mb_worker:
            return {"success": False, "error": "MusicBrainz worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name}
        if entity_type in ('album', 'track'):
            item['artist'] = artist_name
        mb_worker._process_item(item)
        return {"success": True, "message": f"MusicBrainz lookup complete for {entity_type}"}

    elif service == 'spotify':
        if not spotify_enrichment_worker:
            return {"success": False, "error": "Spotify worker not initialized"}
        if entity_type == 'artist':
            spotify_enrichment_worker._process_artist({'type': 'artist', 'id': entity_id, 'name': name})
        elif entity_type == 'album':
            spotify_enrichment_worker._process_album_individual({'type': 'album_individual', 'id': entity_id, 'name': name, 'artist': artist_name})
        elif entity_type == 'track':
            spotify_enrichment_worker._process_track_individual({'type': 'track_individual', 'id': entity_id, 'name': name, 'artist': artist_name})
        return {"success": True, "message": f"Spotify lookup complete for {entity_type}"}

    elif service == 'itunes':
        if not itunes_enrichment_worker:
            return {"success": False, "error": "iTunes worker not initialized"}
        if entity_type == 'artist':
            itunes_enrichment_worker._process_artist({'type': 'artist', 'id': entity_id, 'name': name})
        elif entity_type == 'album':
            itunes_enrichment_worker._process_album_individual({'type': 'album_individual', 'id': entity_id, 'name': name, 'artist': artist_name})
        elif entity_type == 'track':
            itunes_enrichment_worker._process_track_individual({'type': 'track_individual', 'id': entity_id, 'name': name, 'artist': artist_name})
        return {"success": True, "message": f"iTunes lookup complete for {entity_type}"}

    elif service == 'lastfm':
        if not lastfm_worker:
            return {"success": False, "error": "Last.fm worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name}
        if entity_type in ('album', 'track'):
            item['artist'] = artist_name
        lastfm_worker._process_item(item)
        return {"success": True, "message": f"Last.fm lookup complete for {entity_type}"}

    elif service == 'genius':
        if not genius_worker:
            return {"success": False, "error": "Genius worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name}
        if entity_type == 'track':
            item['artist'] = artist_name
        elif entity_type == 'album':
            return {"success": False, "error": "Genius does not support album enrichment"}
        genius_worker._process_item(item)
        return {"success": True, "message": f"Genius lookup complete for {entity_type}"}

    elif service == 'tidal':
        if not tidal_enrichment_worker:
            return {"success": False, "error": "Tidal worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name, 'artist': artist_name}
        if entity_type == 'artist':
            tidal_enrichment_worker._process_artist(entity_id, name)
        elif entity_type == 'album':
            tidal_enrichment_worker._process_album(entity_id, name, artist_name, item)
        elif entity_type == 'track':
            tidal_enrichment_worker._process_track(entity_id, name, artist_name, item)
        return {"success": True, "message": f"Tidal lookup complete for {entity_type}"}

    elif service == 'qobuz':
        if not qobuz_enrichment_worker:
            return {"success": False, "error": "Qobuz worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name, 'artist': artist_name}
        if entity_type == 'artist':
            qobuz_enrichment_worker._process_artist(entity_id, name)
        elif entity_type == 'album':
            qobuz_enrichment_worker._process_album(entity_id, name, artist_name, item)
        elif entity_type == 'track':
            qobuz_enrichment_worker._process_track(entity_id, name, artist_name, item)
        return {"success": True, "message": f"Qobuz lookup complete for {entity_type}"}

    elif service == 'discogs':
        if not discogs_worker:
            return {"success": False, "error": "Discogs worker not initialized"}
        item = {'type': entity_type, 'id': entity_id, 'name': name}
        if entity_type in ('album', 'track'):
            item['artist'] = artist_name
        if entity_type == 'track':
            return {"success": False, "error": "Discogs does not support track-level enrichment"}
        discogs_worker._process_item(item)
        return {"success": True, "message": f"Discogs lookup complete for {entity_type}"}

    elif service == 'bandcamp':
        if not bandcamp_worker:
            return {"success": False, "error": "Bandcamp worker not initialized"}
        from core.metadata.registry import is_source_enabled
        if not is_source_enabled('bandcamp'):
            return {"success": False, "error": "Bandcamp is disabled (experimental feature off)"}
        if entity_type == 'artist':
            return {"success": False, "error": "Bandcamp does not support artist-level enrichment"}
        if entity_type == 'album':
            bandcamp_worker._process_album(entity_id, name, artist_name)
        elif entity_type == 'track':
            bandcamp_worker._process_track(entity_id, name, artist_name)
        return {"success": True, "message": f"Bandcamp lookup complete for {entity_type}"}

    else:
        return {"success": False, "error": f"Unknown service: {service}"}


@app.route('/api/library/search-service', methods=['POST'])
def library_search_service():
    """Search a specific service for matching entities (for manual matching).
    Body: { service: str, entity_type: str, query: str }
    Returns normalized list of results.
    """
    try:
        data = request.get_json()
        if not data:
            return jsonify({"success": False, "error": "Invalid or missing JSON body"}), 400
        service = data.get('service', '')
        entity_type = data.get('entity_type', '')
        query = data.get('query', '').strip()

        if not service or not entity_type or not query:
            return jsonify({"success": False, "error": "service, entity_type, and query are required"}), 400

        results = _search_service(service, entity_type, query)
        return jsonify({"success": True, "results": results})

    except Exception as e:
        logger.error(f"Error searching service: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/library/match-artist-releases', methods=['POST'])
def library_match_artist_releases():
    """Return a lean release strip for one exact artist match candidate.

    Kept separate from artist search so eight candidates do not force eight
    provider discography calls. Library v2 auto-loads only the top candidates
    and lets the user expand the rest on demand.
    """
    try:
        data = request.get_json(silent=True) or {}
        service = str(data.get('service') or '').strip().lower()
        artist_id = str(data.get('artist_id') or '').strip()
        if not service or not artist_id:
            return jsonify({"success": False, "error": "service and artist_id are required"}), 400
        preview = artist_release_preview(
            service,
            artist_id,
            artist_name=data.get('artist_name') or '',
            limit=data.get('limit', 6),
        )
        return jsonify({"success": True, **preview})
    except Exception as e:
        logger.debug("Artist match release preview failed: %s", e)
        # Candidate search remains usable even when a provider's release
        # endpoint is unavailable or rate-limited.
        return jsonify({"success": True, "supported": True, "albums": []})


