@app.route('/api/server/playlists', methods=['GET'])
def get_server_playlists():
    """Get all playlists from the active media server."""
    try:
        active_server = config_manager.get_active_media_server()
        logger.info(f"[ServerPlaylists] Active server: {active_server}")
        if not active_server:
            return jsonify({"success": False, "error": "No media server configured"}), 400

        playlists_data = []
        if active_server == 'plex' and media_server_engine.client('plex') and media_server_engine.client('plex').is_connected():
            # Use raw Plex API to get playlist metadata without fetching all tracks
            try:
                raw_playlists = media_server_engine.client('plex').server.playlists()
                logger.info(f"[ServerPlaylists] Plex returned {len(raw_playlists)} total playlists")
                for playlist in raw_playlists:
                    if getattr(playlist, 'playlistType', None) == 'audio':
                        playlists_data.append({
                            'id': str(playlist.ratingKey),
                            'name': playlist.title,
                            'track_count': playlist.leafCount,
                        })
                logger.info(f"[ServerPlaylists] Found {len(playlists_data)} audio playlists")
            except Exception as e:
                logger.error(f"[ServerPlaylists] Error fetching Plex playlists: {e}", exc_info=True)
                return jsonify({"success": False, "error": f"Plex error: {str(e)}"}), 500
        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin') and media_server_engine.client('jellyfin').is_connected():
            for pl in media_server_engine.client('jellyfin').get_all_playlists():
                playlists_data.append({
                    'id': pl.id,
                    'name': pl.title,
                    'track_count': pl.leaf_count,
                })
        elif active_server == 'navidrome' and media_server_engine.client('navidrome') and media_server_engine.client('navidrome').is_connected():
            for pl in media_server_engine.client('navidrome').get_all_playlists():
                playlists_data.append({
                    'id': pl.id,
                    'name': pl.title,
                    'track_count': pl.leaf_count,
                })
        else:
            logger.warning(f"[ServerPlaylists] Server '{active_server}' not connected. plex_client={media_server_engine.client('plex') is not None}, jellyfin_client={media_server_engine.client('jellyfin') is not None}, navidrome_client={media_server_engine.client('navidrome') is not None}")
            return jsonify({"success": False, "error": f"{active_server} not connected"}), 400

        return jsonify({"success": True, "server_type": active_server, "playlists": playlists_data})
    except Exception as e:
        logger.error(f"Error getting server playlists: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/server/playlist/<playlist_id>/tracks', methods=['GET'])
def get_server_playlist_tracks(playlist_id):
    """Get tracks from a server playlist with source match info from sync history."""
    try:
        active_server = config_manager.get_active_media_server()
        playlist_name = request.args.get('name', '')

        # Get tracks from server
        server_tracks = []
        if active_server == 'plex' and media_server_engine.client('plex'):
            try:
                # Try by ID first, fall back to name lookup (ID changes when playlist is recreated)
                raw_playlist = None
                try:
                    raw_playlist = media_server_engine.client('plex').server.fetchItem(int(playlist_id))
                except Exception as e:
                    logger.debug("plex playlist fetchItem failed: %s", e)
                if not raw_playlist and playlist_name:
                    try:
                        raw_playlist = media_server_engine.client('plex').server.playlist(playlist_name)
                    except Exception as e:
                        logger.debug("plex playlist by-name lookup failed: %s", e)
                if not raw_playlist:
                    logger.warning(
                        f"[ServerPlaylistTracks] Plex playlist not found by "
                        f"id={playlist_id} or name='{playlist_name}' — "
                        f"compare view will show every source track as Find & Add"
                    )
                if raw_playlist:
                    if not playlist_name:
                        playlist_name = raw_playlist.title
                    plex_base = getattr(media_server_engine.client('plex').server, '_baseurl', '') or ''
                    plex_token = getattr(media_server_engine.client('plex').server, '_token', '') or ''
                    if not plex_base:
                        # Fallback: get from config
                        _pc = config_manager.get_plex_config()
                        plex_base = (_pc.get('base_url', '') or '').rstrip('/')
                        plex_token = plex_token or _pc.get('token', '')
                    logger.debug(f"[ServerPlaylistTracks] Plex base URL: {plex_base}")
                    for item in raw_playlist.items():
                        grandparent = getattr(item, 'grandparentTitle', '') or ''
                        parent = getattr(item, 'parentTitle', '') or ''
                        # Build full thumb URL from Plex relative path
                        thumb = ''
                        raw_thumb = getattr(item, 'thumb', '') or getattr(item, 'parentThumb', '') or ''
                        if raw_thumb and plex_base and plex_token:
                            thumb = f"{plex_base}{raw_thumb}?X-Plex-Token={plex_token}"
                        server_tracks.append({
                            'id': str(item.ratingKey),
                            'title': item.title,
                            'artist': grandparent,
                            'album': parent,
                            'duration': item.duration or 0,
                            'thumb': thumb,
                        })
            except Exception as e:
                logger.error(f"[ServerPlaylistTracks] Plex error: {e}", exc_info=True)
        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin'):
            tracks = media_server_engine.client('jellyfin').get_playlist_tracks(playlist_id)
            for t in (tracks or []):
                raw = t._data if hasattr(t, '_data') else {}
                artists = raw.get('Artists', [])
                # Through the token-safe proxy, NOT a raw {jf_base}/Items/...
                # URL. The raw form handed the BROWSER an unauthenticated
                # request against whatever address SOULSYNC uses for Jellyfin —
                # and Jellyfin answers those with 200 and an empty body, which
                # is #1159's "all requests for the images return a 200 response
                # but with an empty body", verbatim. The server-activity proxy
                # already exists for exactly this (its jellyfin fetch even
                # guards on `r.content` because someone hit the empty-200
                # before); it attaches the api_key server-side so the token
                # never reaches the browser, same reason Navidrome thumbs go
                # through /api/navidrome/cover/.
                album_id = raw.get('AlbumId', '')
                thumb = f"/api/server-activity/image?path=jf:{album_id}" if album_id else ''
                server_tracks.append({
                    'id': str(t.ratingKey),
                    'title': t.title,
                    'artist': artists[0] if artists else raw.get('AlbumArtist', ''),
                    'album': raw.get('Album', ''),
                    'duration': t.duration,
                    'thumb': thumb,
                })
        elif active_server == 'navidrome' and media_server_engine.client('navidrome'):
            tracks = media_server_engine.client('navidrome').get_playlist_tracks(playlist_id)
            for t in (tracks or []):
                raw = t._data if hasattr(t, '_data') else {}
                # Navidrome cover art via Subsonic API
                cover_id = raw.get('coverArt', '') or raw.get('albumId', '')
                thumb = f"/api/navidrome/cover/{cover_id}" if cover_id else ''
                server_tracks.append({
                    'id': str(t.ratingKey),
                    'title': t.title,
                    'artist': raw.get('artist', ''),
                    'album': raw.get('album', ''),
                    'duration': t.duration,
                    'thumb': thumb,
                })

        # Get source tracks — prefer mirrored playlist, fall back to sync history
        source_tracks = []
        mirrored_id = request.args.get('mirrored_playlist_id')
        if mirrored_id:
            db = get_database()
            raw_tracks = db.get_mirrored_playlist_tracks(int(mirrored_id))

            # No art pre-borrowing here (#1164). This used to fill an art-less
            # source row from any server track sharing its title — with a
            # title-ONLY fallback, so an UNMATCHED "XO" by John Mayer wore the
            # cover of "XO" by Eden Project. The reconcile's own borrow (#766)
            # keys off the actual pairing and already covers every matched
            # row; an unmatched source row with no art of its own now shows
            # none, which is what it has.
            for t in raw_tracks:
                img = t.get('image_url') or ''

                source_tracks.append({
                    'name': t.get('track_name', ''),
                    'artist': t.get('artist_name', ''),
                    'album': t.get('album_name', ''),
                    'image_url': img,
                    'duration_ms': t.get('duration_ms', 0),
                    'position': t.get('position', 0),
                    # Spotify track id — required for the user-confirmed
                    # match override lookup (sync_match_cache). Null for
                    # iTunes-only sources.
                    'source_track_id': t.get('source_track_id') or '',
                })
        elif playlist_name:
            # Legacy fallback: cross-reference with sync history
            db = get_database()
            _hist_profile_id = get_current_profile_id()
            entries, _ = db.get_sync_history(page=1, limit=50, profile_id=_hist_profile_id)
            for entry in entries:
                if entry.get('playlist_name', '').lower() == playlist_name.lower():
                    full_entry = db.get_sync_history_entry(entry['id'], profile_id=_hist_profile_id)
                    if full_entry:
                        try:
                            tr = json.loads(full_entry.get('track_results') or '[]')
                            source_tracks = tr if isinstance(tr, list) else []
                        except (json.JSONDecodeError, TypeError):
                            pass
                        if not source_tracks:
                            try:
                                source_tracks = json.loads(full_entry.get('tracks_json') or '[]')
                            except (json.JSONDecodeError, TypeError):
                                pass
                    break

        # Reconcile source vs server playlist. Three-pass matcher lifted to
        # core.sync.playlist_reconcile (pure + tested) — fixes #768 (YouTube
        # "Artist - Title" sources now match, and source_track_id is echoed
        # back so manual "Find & add" overrides persist).
        from core.sync.playlist_reconcile import compute_order_status, reconcile_playlist

        # Pass 0: User-confirmed match overrides from sync_match_cache.
        # When a user previously picked a local file via "Find & Add",
        # the (source_track_id → server_track_id) mapping was persisted
        # at confidence=1.0. Apply those FIRST so they bypass the
        # exact/fuzzy passes entirely. Stale-cache safe — if the cached
        # server track no longer exists, the override is silently
        # skipped and normal matching runs.
        from core.sync.match_overrides import build_bulk_override_lookup, resolve_match_overrides
        _db_for_overrides = get_database()
        # Set of server track ids currently in this playlist — used to validate
        # a cached/durable match actually exists in this playlist before pairing it.
        _server_ids = {str(t.get('id')) for t in server_tracks if isinstance(t, dict) and t.get('id') is not None}
        _ov_profile = get_current_profile_id()

        # Validated fast-cache hit, else durable manual match (#787) which
        # self-heals a stale library id via the stored file path. A cache hit
        # that no longer points into THIS playlist must not short-circuit the
        # durable path, or the manual match silently never applies (wolf39us).
        # Bulk-backed (#1005): the per-track resolver opened 2-3 fresh SQLite
        # connections (and committed per cache hit) for EVERY source track —
        # ~15s of pass-0 churn on a 1500-track playlist.
        _override_lookup = build_bulk_override_lookup(
            _db_for_overrides, _ov_profile, active_server, _server_ids, source_tracks)

        _override_pairs = resolve_match_overrides(source_tracks, server_tracks, _override_lookup)

        combined = reconcile_playlist(source_tracks, server_tracks, _override_pairs)

        # A durable manual match whose library track isn't in THIS playlist yet
        # can't be applied above, so its row renders as a plain "missing" with
        # Find & Add — indistinguishable from a track that was never matched at
        # all. Users then re-match the same track every single sync and nothing
        # ever tells them it already took (#1128). The match IS honoured by the
        # real sync (services/sync_service.py resolves it, with file-path and
        # live-Plex fallbacks); only this preview was silent about it. Flag the
        # rows so the UI can say "already matched, not in the playlist yet".
        try:
            _mm_ids = set()
            if hasattr(_db_for_overrides, "find_manual_library_matches_bulk"):
                _src_ids = [str(s.get("source_track_id")) for s in source_tracks
                            if isinstance(s, dict) and s.get("source_track_id")]
                if _src_ids:
                    _mm_ids = set(_db_for_overrides.find_manual_library_matches_bulk(
                        _ov_profile, _src_ids, active_server) or {})
            # A saved match the lookup could NOT apply by any route is dead —
            # its file was deleted, or the library row vanished. Flagging those
            # rows "already matched" is what stranded #1138: the UI then offers
            # neither Find & Add nor a download, so reprocessing the playlist
            # skipped the track silently, run after run. Mark them stale
            # instead, so they render as the missing tracks they are.
            _dead_ids = getattr(_override_lookup, 'dead_match_source_ids', None) or set()
            if _mm_ids:
                for _row in combined:
                    if _row.get('override'):
                        continue   # already applied — the row shows as matched
                    _sid = str((_row.get('source_track') or {}).get('source_track_id') or '')
                    if not _sid or _sid not in _mm_ids:
                        continue
                    if _sid in _dead_ids:
                        _row['manual_match_stale'] = True
                    else:
                        _row['has_manual_match'] = True
        except Exception as _mm_err:   # noqa: BLE001 - a badge must never fail the view
            logger.debug("manual-match flagging failed: %s", _mm_err)

        # Order status: the editor renders the server column in SOURCE order, so a
        # reordered-but-same-membership playlist reads "in sync" when Navidrome's real
        # order differs. Surface that (one-way: source order is truth). `server_order`
        # is the server's ACTUAL sequence, for the read-only "view server order" view.
        order_status = compute_order_status(combined)
        server_order = [
            {
                "title": t.get("title"),
                "artist": t.get("artist"),
                "thumb": t.get("thumb"),
                "id": t.get("id"),
            }
            for t in server_tracks if isinstance(t, dict)
        ]

        return jsonify({
            "success": True,
            "server_type": active_server,
            "playlist_name": playlist_name,
            "tracks": combined,
            "server_track_count": len(server_tracks),
            "source_track_count": len(source_tracks),
            "order_status": order_status,
            "server_order": server_order,
        })
    except Exception as e:
        logger.error(f"Error getting server playlist tracks: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/server/playlist/<playlist_id>/align', methods=['POST'])
def server_playlist_align(playlist_id):
    """Align a server playlist's ORDER to the source ('Align playlists').

    Order-only and metadata-free: the client sends the matched server-track ids in
    SOURCE order (`matched_ids`) plus the extras choice (`keep_extras`); the server
    validates every id is currently in the playlist (so this can only reorder/drop
    tracks already there — never inject one) and rewrites the playlist in that order
    via the overwrite primitive. Does NOT touch membership-completeness — missing
    tracks are the normal sync's job. Navidrome only for now."""
    try:
        data = request.get_json() or {}
        playlist_name = (data.get('playlist_name') or '').strip()
        matched_ids = data.get('matched_ids') or []
        keep_extras = bool(data.get('keep_extras', False))
        if not playlist_name:
            return jsonify({"success": False, "error": "playlist_name required"}), 400
        if not matched_ids:
            return jsonify({"success": False, "error": "no matched tracks to align"}), 400

        active_server = config_manager.get_active_media_server()
        client = media_server_engine.client(active_server) if active_server else None
        if active_server not in ('navidrome', 'plex', 'jellyfin') or not client:
            return jsonify({"success": False,
                            "error": "Align isn't supported on this server yet"}), 400

        # Current playlist track ids (in current server order) — per server.
        if active_server == 'navidrome':
            current_tracks = client.get_playlist_tracks(playlist_id) or []
            current_ids = [str(t.ratingKey) for t in current_tracks if getattr(t, 'ratingKey', None)]
        elif active_server == 'plex':
            current_ids = client.get_playlist_track_ids(playlist_id, playlist_name)
        else:  # jellyfin
            current_ids = client.get_playlist_track_ids(playlist_id)

        from core.sync.playlist_edit import plan_align_rewrite
        ordered = plan_align_rewrite(current_ids, matched_ids, keep_extras=keep_extras)
        if ordered is None:
            return jsonify({"success": False,
                            "error": "Playlist changed on the server — reload and try again"}), 409

        if active_server == 'navidrome':
            ok = client.rewrite_playlist_order(playlist_id, playlist_name, ordered)
        else:  # plex / jellyfin — in-place reorder
            ok = client.reorder_playlist(playlist_id, playlist_name, ordered)
        if not ok:
            return jsonify({"success": False, "error": "Failed to reorder playlist"}), 500
        return jsonify({"success": True, "track_count": len(ordered),
                        "kept_extras": keep_extras})
    except Exception as e:
        logger.error(f"Error aligning server playlist '{playlist_id}': {e}")
        return jsonify({"success": False, "error": str(e)}), 500


def _jellyfin_playlist_tracks_fresh(jf, playlist_id, playlist_name):
    """Playlist tracks by id, falling back to a by-name re-resolve — and which
    id actually worked.

    Jellyfin edits are delete-and-recreate (update_playlist), so the id a page
    loaded goes stale the moment ANYTHING edits the playlist — a sync run, or
    the previous click in this same editor. A fetch against the dead id comes
    back empty, remove_one_occurrence removes nothing, and the endpoint 404s:
    "Remove from playlist" looked like it did nothing at all (#1159, AfonsoG6,
    on Jellyfin). The Plex branches have done ID-first-name-fallback since the
    beginning, for the same delete-recreate reason — Jellyfin's never did.

    An empty-but-alive playlist resolves to the same id again, which is
    harmless: there is nothing to remove or replace in it either way.
    """
    tracks = jf.get_playlist_tracks(playlist_id) or []
    if tracks:
        return tracks, playlist_id
    try:
        fresh = jf.get_playlist_by_name(playlist_name) if playlist_name else None
    except Exception as e:
        logger.debug("jellyfin by-name playlist re-resolve failed: %s", e)
        fresh = None
    fresh_id = str(getattr(fresh, 'id', '') or '') if fresh else ''
    if fresh_id and fresh_id != str(playlist_id):
        logger.info("[ServerPlaylist] Stale Jellyfin playlist id %s — re-resolved '%s' to %s",
                    playlist_id, playlist_name, fresh_id)
        return (jf.get_playlist_tracks(fresh_id) or []), fresh_id
    return tracks, playlist_id


def _jellyfin_recreated_playlist_id(playlist_name):
    """The id a Jellyfin playlist got when update_playlist recreated it.

    Best-effort: the edit already succeeded, so failing to learn the new id
    must not fail the request — the client just keeps the old one and the
    fallback above rescues the next edit.
    """
    try:
        fresh = media_server_engine.client('jellyfin').get_playlist_by_name(playlist_name)
        return str(fresh.id) if fresh else None
    except Exception as e:
        logger.debug("jellyfin post-edit id re-resolve failed: %s", e)
        return None


@app.route('/api/server/playlist/<playlist_id>/replace-track', methods=['POST'])
def server_playlist_replace_track(playlist_id):
    """Replace a track in a server playlist. Rebuilds the playlist with the swap."""
    try:
        data = request.get_json()
        old_track_id = data.get('old_track_id')
        new_track_id = data.get('new_track_id')
        playlist_name = data.get('playlist_name', '')

        if not old_track_id or not new_track_id:
            return jsonify({"success": False, "error": "old_track_id and new_track_id required"}), 400
        if not playlist_name:
            return jsonify({"success": False, "error": "playlist_name required"}), 400

        active_server = config_manager.get_active_media_server()

        # Persist the correction, exactly as Find & Add does. This endpoint
        # used to edit the server playlist and store NOTHING, so a fixed bad
        # match existed only as a playlist edit: the 0.75 auto-match the sync
        # had cached stayed in sync_match_cache, pass 0 of the next compare
        # re-pinned it, and the next sync re-added the wrong track to the
        # server. The user's hand-picked pairing landed in Extras every time
        # (#1159, AfonsoG6 — "incorrect matches reappear after I have manually
        # changed them"). save_sync_match_cache is INSERT OR REPLACE, so the
        # confidence-1.0 write also overwrites that bad cached row.
        # source_track_id is absent for non-mirrored compares — nothing to key
        # a pairing by, so there is nothing to persist (the edit still runs).
        _src_track_id = (data.get('source_track_id') or '').strip()
        _src_title = data.get('source_title', '')
        _src_artist = data.get('source_artist', '')
        _src_source = data.get('source') or 'spotify'
        _new_track_title = data.get('new_track_title', '')

        def _persist_replacement():
            if not _src_track_id:
                logger.debug("[ServerPlaylist] replace-track: no source_track_id in payload — pairing not persisted")
                return
            _persist_find_and_add_match(
                _src_track_id, active_server, new_track_id, _new_track_title,
                _src_title, _src_artist, source=_src_source)

        if active_server == 'plex' and media_server_engine.client('plex'):
            # ID-first, name-fallback (Plex deletes + recreates on edit
            # so the cached rating key can be stale).
            plex_server = media_server_engine.client('plex').server
            raw_playlist = None
            try:
                raw_playlist = plex_server.fetchItem(int(playlist_id))
            except Exception as e:
                logger.debug("plex playlist fetchItem failed: %s", e)
            if not raw_playlist and playlist_name:
                try:
                    raw_playlist = plex_server.playlist(playlist_name)
                except Exception as e:
                    logger.debug("plex playlist by-name lookup failed: %s", e)
            if not raw_playlist:
                logger.warning(f"[ServerPlaylist] replace-track: playlist not found by id={playlist_id} or name='{playlist_name}'")
                return jsonify({"success": False, "error": "Playlist not found on server"}), 404

            # Build new track list with replacement
            new_tracks = []
            replaced = False
            for item in raw_playlist.items():
                if str(item.ratingKey) == str(old_track_id) and not replaced:
                    new_item = media_server_engine.client('plex').server.fetchItem(int(new_track_id))
                    if new_item:
                        new_tracks.append(new_item)
                        replaced = True
                    else:
                        new_tracks.append(item)
                else:
                    new_tracks.append(item)

            if replaced:
                # Delete old and recreate directly (avoid update_playlist's backup logic)
                raw_playlist.delete()
                from plexapi.playlist import Playlist
                new_pl = Playlist.create(media_server_engine.client('plex').server, playlist_name, items=new_tracks)
                _persist_replacement()
                return jsonify({"success": True, "message": "Track replaced", "new_playlist_id": str(new_pl.ratingKey)})
            else:
                return jsonify({"success": False, "error": "Old track not found in playlist"}), 404

        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin'):
            _jf = media_server_engine.client('jellyfin')
            current_tracks, _effective_id = _jellyfin_playlist_tracks_fresh(_jf, playlist_id, playlist_name)
            new_track_ids = []
            replaced = False
            for t in (current_tracks or []):
                tid = str(t.ratingKey)
                if tid == str(old_track_id) and not replaced:
                    new_track_ids.append(new_track_id)
                    replaced = True
                else:
                    new_track_ids.append(tid)

            if replaced:
                new_track_objs = [type('T', (), {'ratingKey': tid, 'title': ''})() for tid in new_track_ids]
                _jf.update_playlist(playlist_name, new_track_objs)
                _persist_replacement()
                # update_playlist deletes + recreates, so the caller's id just
                # died — hand back the new one (both editors already apply it).
                return jsonify({"success": True, "message": "Track replaced",
                                "new_playlist_id": _jellyfin_recreated_playlist_id(playlist_name)})
            return jsonify({"success": False, "error": "Old track not found"}), 404

        elif active_server == 'navidrome' and media_server_engine.client('navidrome'):
            current_tracks = media_server_engine.client('navidrome').get_playlist_tracks(playlist_id)
            new_track_ids = []
            replaced = False
            for t in (current_tracks or []):
                tid = str(t.ratingKey)
                if tid == str(old_track_id) and not replaced:
                    new_track_ids.append(new_track_id)
                    replaced = True
                else:
                    new_track_ids.append(tid)

            if replaced:
                new_track_objs = [type('T', (), {'ratingKey': tid, 'title': ''})() for tid in new_track_ids]
                media_server_engine.client('navidrome').create_playlist(playlist_name, new_track_objs, playlist_id=playlist_id)
                _persist_replacement()
                return jsonify({"success": True, "message": "Track replaced"})
            return jsonify({"success": False, "error": "Old track not found"}), 404

        return jsonify({"success": False, "error": f"Unsupported server: {active_server}"}), 400
    except Exception as e:
        logger.error(f"Error replacing track in server playlist: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


def _persist_find_and_add_match(source_track_id, server_source, server_track_id, server_track_title, source_title, source_artist, source='spotify'):
    """Persist a Find & Add selection two ways. No-op when source_track_id is
    missing (e.g. add to a non-mirrored playlist).

    1. ``sync_match_cache`` override — fast auto-match on the next sync, but
       wiped on every library rescan.
    2. A DURABLE manual library match (#787) — survives a rescan, so the
       source→library pairing sticks in the sync display AND the download loop
       stops re-fetching it. This is the unification the issue asked for:
       Find & Add now also records a manual library match (one-way; the manual
       match tool has no playlist to act on, so it doesn't reverse-create)."""
    if not source_track_id:
        # Nothing to key the override by — the pairing will NOT survive a
        # reload. Loud, because to the user this looks like "matched it, then
        # it unmatched itself" (the wolf39us report shape).
        logger.warning(
            "[ServerPlaylist] Find & Add match for '%s' NOT persisted — the source row "
            "carries no source_track_id, so the pairing can't be stored and will "
            "revert on the next compare load.", server_track_title or source_title or server_track_id)
        return
    db = get_database()
    try:
        from core.sync.match_overrides import record_manual_match
        ok = record_manual_match(
            db,
            source_track_id=source_track_id,
            server_source=server_source,
            server_track_id=server_track_id,
            source_title=source_title,
            source_artist=source_artist,
            server_track_title=server_track_title,
        )
        if ok:
            logger.info(f"[ServerPlaylist] Persisted Find & Add override: {source_track_id} → {server_track_id} ({server_source})")
    except Exception as e:
        logger.warning(f"[ServerPlaylist] Failed to persist Find & Add override: {e}")

    # Durable manual library match — survives a rescan (the override above does not).
    try:
        from core.library import manual_library_match as _mlm
        file_path = ''
        try:
            _rows = db.api_get_tracks_by_ids([server_track_id])
            if _rows:
                file_path = _rows[0].get('file_path', '') or ''
        except Exception as _fp_err:
            logger.debug(f"[ServerPlaylist] file_path lookup for manual match failed: {_fp_err}")
        _mlm.save_match(
            db, get_current_profile_id(), (source or 'spotify'), str(source_track_id), str(server_track_id),
            source_title=source_title, source_artist=source_artist,
            server_source=server_source, library_file_path=file_path,
        )
        logger.info(f"[ServerPlaylist] Recorded durable manual library match: {source_track_id} → {server_track_id}")
    except Exception as e:
        logger.warning(f"[ServerPlaylist] Failed to record durable manual match: {e}")


@app.route('/api/server/playlist/<playlist_id>/add-track', methods=['POST'])
def server_playlist_add_track(playlist_id):
    """Add a track to a server playlist at a specific position.

    When the optional `source_track_id` is provided (the Spotify track id
    from a mirrored playlist), the user's selection is also persisted to
    sync_match_cache so future syncs auto-match this source→server pair
    without requiring the user to re-trigger Find & Add.
    """
    try:
        data = request.get_json()
        track_id = data.get('track_id')
        playlist_name = data.get('playlist_name', '')
        position = data.get('position')  # 0-based index; None = append
        # Optional Spotify source track id — when present, the (source →
        # server) mapping is persisted as a hard match override.
        source_track_id = data.get('source_track_id') or ''
        source_title = data.get('source_title') or ''
        source_artist = data.get('source_artist') or ''
        server_track_title = data.get('server_track_title') or ''
        # Provider of the source track (spotify/deezer/...) for the durable
        # manual match. Retrieval is source-agnostic, so this is metadata.
        source_provider = data.get('source') or 'spotify'

        if not track_id:
            return jsonify({"success": False, "error": "track_id required"}), 400
        if not playlist_name:
            return jsonify({"success": False, "error": "playlist_name required"}), 400

        active_server = config_manager.get_active_media_server()

        if active_server == 'plex' and media_server_engine.client('plex'):
            # ID-first, name-fallback — Plex deletes + recreates playlists
            # on edit so the rating key the frontend cached can be stale.
            # The GET tracks endpoint uses the same lookup chain.
            plex_server = media_server_engine.client('plex').server
            raw_playlist = None
            try:
                raw_playlist = plex_server.fetchItem(int(playlist_id))
            except Exception as e:
                logger.debug("plex playlist fetchItem failed: %s", e)
            if not raw_playlist and playlist_name:
                try:
                    raw_playlist = plex_server.playlist(playlist_name)
                except Exception as e:
                    logger.debug("plex playlist by-name lookup failed: %s", e)
            if not raw_playlist:
                logger.warning(f"[ServerPlaylist] add-track: playlist not found by id={playlist_id} or name='{playlist_name}'")
                return jsonify({"success": False, "error": "Playlist not found"}), 404

            new_item = plex_server.fetchItem(int(track_id))
            if not new_item:
                return jsonify({"success": False, "error": "Track not found on server"}), 404

            # Link, don't duplicate: matching an unmatched source to a track
            # already in the playlist should only record the override, never
            # append a second copy (#768).
            if source_track_id:
                try:
                    _existing = {str(it.ratingKey) for it in raw_playlist.items()}
                except Exception:
                    _existing = set()
                if str(track_id) in _existing:
                    _persist_find_and_add_match(source_track_id, active_server, track_id, server_track_title or new_item.title, source_title, source_artist, source_provider)
                    return jsonify({"success": True, "message": "Track linked"})

            logger.info(f"[ServerPlaylist] Adding track: '{new_item.title}' (ratingKey={new_item.ratingKey}) to playlist '{playlist_name}'")

            raw_playlist.addItems([new_item])

            # Move to correct position if specified (addItems always appends to end)
            if position is not None:
                try:
                    raw_playlist.reload()
                    items = list(raw_playlist.items())
                    pos = max(0, min(int(position), len(items) - 1))
                    if pos == 0:
                        raw_playlist.moveItem(items[-1])  # Move to first position
                    elif pos < len(items) - 1:
                        raw_playlist.moveItem(items[-1], after=items[pos - 1])
                    # else: already at end, no move needed
                    logger.info(f"[ServerPlaylist] Moved track to position {pos}")
                except Exception as move_err:
                    logger.warning(f"[ServerPlaylist] Could not reposition track: {move_err}")

            new_id = str(raw_playlist.ratingKey)
            logger.info(f"[ServerPlaylist] Added track to playlist, playlist ID: {new_id}")
            _persist_find_and_add_match(source_track_id, active_server, track_id, server_track_title or new_item.title, source_title, source_artist, source_provider)
            return jsonify({"success": True, "message": "Track added", "new_playlist_id": new_id})

        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin'):
            from core.sync.playlist_edit import plan_playlist_add
            jf = media_server_engine.client('jellyfin')
            current_tracks = jf.get_playlist_tracks(playlist_id) or []
            track_ids = [str(t.ratingKey) for t in current_tracks]
            # Matching an unmatched source to a track already in the playlist
            # is a LINK, not a second copy — don't duplicate it (#768).
            plan = plan_playlist_add(track_ids, track_id, is_link=bool(source_track_id), position=position)
            if plan['should_insert']:
                # #837: append the ONE found track IN PLACE. The old path called
                # update_playlist(full track list), which on Jellyfin/Emby deletes
                # and recreates the playlist — wiping its description + cover image.
                # append_to_playlist adds in place (dedupe-safe), the same
                # non-destructive op the 'append' sync mode already uses. It reads
                # `.id` (not ratingKey) off each track, so set both.
                new_track_obj = type('T', (), {
                    'id': str(track_id), 'ratingKey': str(track_id),
                    'title': server_track_title or '',
                })()
                jf.append_to_playlist(playlist_name, [new_track_obj])
            _persist_find_and_add_match(source_track_id, active_server, track_id, server_track_title, source_title, source_artist, source_provider)
            return jsonify({"success": True, "message": "Track linked" if not plan['should_insert'] else "Track added"})

        elif active_server == 'navidrome' and media_server_engine.client('navidrome'):
            from core.sync.playlist_edit import plan_playlist_add
            current_tracks = media_server_engine.client('navidrome').get_playlist_tracks(playlist_id) or []
            track_ids = [str(t.ratingKey) for t in current_tracks]
            # Matching an unmatched source to a track already in the playlist
            # is a LINK, not a second copy — don't duplicate it (#768).
            plan = plan_playlist_add(track_ids, track_id, is_link=bool(source_track_id), position=position)
            if plan['should_insert']:
                new_track_objs = [type('T', (), {'ratingKey': tid, 'title': ''})() for tid in plan['new_ids']]
                media_server_engine.client('navidrome').create_playlist(playlist_name, new_track_objs, playlist_id=playlist_id)
            _persist_find_and_add_match(source_track_id, active_server, track_id, server_track_title, source_title, source_artist, source_provider)
            return jsonify({"success": True, "message": "Track linked" if not plan['should_insert'] else "Track added"})

        return jsonify({"success": False, "error": f"Unsupported server: {active_server}"}), 400
    except Exception as e:
        logger.error(f"Error adding track to server playlist: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/server/playlist/<playlist_id>/remove-track', methods=['POST'])
def server_playlist_remove_track(playlist_id):
    """Remove a track from a server playlist by its server track ID."""
    try:
        data = request.get_json()
        remove_track_id = data.get('track_id')
        playlist_name = data.get('playlist_name', '')

        if not remove_track_id:
            return jsonify({"success": False, "error": "track_id required"}), 400
        if not playlist_name:
            return jsonify({"success": False, "error": "playlist_name required"}), 400

        active_server = config_manager.get_active_media_server()

        if active_server == 'plex' and media_server_engine.client('plex'):
            # ID-first, name-fallback (Plex deletes + recreates on edit
            # so the cached rating key can be stale).
            plex_server = media_server_engine.client('plex').server
            raw_playlist = None
            try:
                raw_playlist = plex_server.fetchItem(int(playlist_id))
            except Exception as e:
                logger.debug("plex playlist fetchItem failed: %s", e)
            if not raw_playlist and playlist_name:
                try:
                    raw_playlist = plex_server.playlist(playlist_name)
                except Exception as e:
                    logger.debug("plex playlist by-name lookup failed: %s", e)
            if not raw_playlist:
                logger.warning(f"[ServerPlaylist] remove-track: playlist not found by id={playlist_id} or name='{playlist_name}'")
                return jsonify({"success": False, "error": "Playlist not found"}), 404

            # Rebuild without ONE copy of the target track — deleting one
            # duplicate must not wipe every copy (#768).
            current_items = list(raw_playlist.items())
            new_items = list(current_items)
            _removed = False
            for _i, _it in enumerate(new_items):
                if str(_it.ratingKey) == str(remove_track_id):
                    del new_items[_i]
                    _removed = True
                    break
            if not _removed:
                return jsonify({"success": False, "error": "Track not found in playlist"}), 404
            raw_playlist.delete()
            if new_items:
                from plexapi.playlist import Playlist
                new_pl = Playlist.create(media_server_engine.client('plex').server, playlist_name, items=new_items)
                return jsonify({"success": True, "message": "Track removed", "new_playlist_id": str(new_pl.ratingKey)})
            return jsonify({"success": True, "message": "Track removed (playlist now empty)"})

        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin'):
            from core.sync.playlist_edit import remove_one_occurrence
            _jf = media_server_engine.client('jellyfin')
            current_tracks, _effective_id = _jellyfin_playlist_tracks_fresh(_jf, playlist_id, playlist_name)
            track_ids = [str(t.ratingKey) for t in current_tracks]
            # Remove ONE occurrence, not every copy — duplicates are the same
            # track, so deleting one must not wipe them all (#768).
            new_ids, removed = remove_one_occurrence(track_ids, remove_track_id)
            if not removed:
                return jsonify({"success": False, "error": "Track not found in playlist"}), 404
            new_track_objs = [type('T', (), {'ratingKey': tid, 'title': ''})() for tid in new_ids]
            _jf.update_playlist(playlist_name, new_track_objs)
            # Same delete-recreate as replace: report the fresh id.
            return jsonify({"success": True, "message": "Track removed",
                            "new_playlist_id": _jellyfin_recreated_playlist_id(playlist_name)})

        elif active_server == 'navidrome' and media_server_engine.client('navidrome'):
            from core.sync.playlist_edit import remove_one_occurrence
            current_tracks = media_server_engine.client('navidrome').get_playlist_tracks(playlist_id) or []
            track_ids = [str(t.ratingKey) for t in current_tracks]
            # Remove ONE occurrence, not every copy (#768).
            new_ids, removed = remove_one_occurrence(track_ids, remove_track_id)
            if not removed:
                return jsonify({"success": False, "error": "Track not found in playlist"}), 404
            new_track_objs = [type('T', (), {'ratingKey': tid, 'title': ''})() for tid in new_ids]
            media_server_engine.client('navidrome').create_playlist(playlist_name, new_track_objs, playlist_id=playlist_id)
            return jsonify({"success": True, "message": "Track removed"})

        return jsonify({"success": False, "error": f"Unsupported server: {active_server}"}), 400
    except Exception as e:
        logger.error(f"Error removing track from server playlist: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/server/playlist/<playlist_id>/delete', methods=['POST'])
def server_playlist_delete(playlist_id):
    """Delete a server playlist outright — SoulSync-made or not.

    Same id-first, name-fallback shape as every other edit in this family:
    Plex and Jellyfin delete-recreate on edit, so the id the page loaded may
    already be dead (#1159 taught the Jellyfin lesson). A delete against a
    stale id must not strand the LIVE playlist under its new id."""
    try:
        data = request.get_json() or {}
        playlist_name = data.get('playlist_name', '')
        if not playlist_name:
            return jsonify({"success": False, "error": "playlist_name required"}), 400

        active_server = config_manager.get_active_media_server()

        if active_server == 'plex' and media_server_engine.client('plex'):
            plex_server = media_server_engine.client('plex').server
            raw_playlist = None
            try:
                raw_playlist = plex_server.fetchItem(int(playlist_id))
            except Exception as e:
                logger.debug("plex playlist fetchItem failed: %s", e)
            if not raw_playlist:
                try:
                    raw_playlist = plex_server.playlist(playlist_name)
                except Exception as e:
                    logger.debug("plex playlist by-name lookup failed: %s", e)
            if not raw_playlist:
                return jsonify({"success": False, "error": "Playlist not found"}), 404
            raw_playlist.delete()
            logger.info(f"[ServerPlaylist] Deleted Plex playlist '{playlist_name}' ({playlist_id})")
            return jsonify({"success": True, "message": "Playlist deleted"})

        elif active_server == 'jellyfin' and media_server_engine.client('jellyfin'):
            _jf = media_server_engine.client('jellyfin')
            if _jf.delete_playlist(playlist_id):
                logger.info(f"[ServerPlaylist] Deleted Jellyfin playlist '{playlist_name}' ({playlist_id})")
                return jsonify({"success": True, "message": "Playlist deleted"})
            # stale id — the recreate gave the live playlist a new one
            try:
                fresh = _jf.get_playlist_by_name(playlist_name)
            except Exception as e:
                logger.debug("jellyfin by-name playlist re-resolve failed: %s", e)
                fresh = None
            fresh_id = str(getattr(fresh, 'id', '') or '') if fresh else ''
            if fresh_id and fresh_id != str(playlist_id) and _jf.delete_playlist(fresh_id):
                logger.info(f"[ServerPlaylist] Deleted Jellyfin playlist '{playlist_name}' via re-resolved id {fresh_id}")
                return jsonify({"success": True, "message": "Playlist deleted"})
            return jsonify({"success": False, "error": "Playlist not found"}), 404

        elif active_server == 'navidrome' and media_server_engine.client('navidrome'):
            _nd = media_server_engine.client('navidrome')
            if _nd.delete_playlist(playlist_id):
                logger.info(f"[ServerPlaylist] Deleted Navidrome playlist '{playlist_name}' ({playlist_id})")
                return jsonify({"success": True, "message": "Playlist deleted"})
            return jsonify({"success": False, "error": "Playlist not found"}), 404

        return jsonify({"success": False, "error": f"Unsupported server: {active_server}"}), 400
    except Exception as e:
        logger.error(f"Error deleting server playlist: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/library/search-tracks', methods=['GET'])
def library_search_tracks():
    """Search SoulSync's local database for tracks (for manual match correction)."""
    try:
        query = request.args.get('q', '').strip()
        # Optional source-artist relevance hint (Find & Add knows the artist of
        # the track it's matching) — used only to rank exact title+artist matches
        # to the top, NOT to filter.
        artist_hint = request.args.get('artist', '').strip()
        limit = int(request.args.get('limit', 10))
        if not query:
            return jsonify({"success": True, "tracks": []})

        active_server = config_manager.get_active_media_server()
        database = get_database()

        # Build thumb URL resolver for this server. Only Plex was ever
        # handled here — Jellyfin rows store /Items/<id>/Images/Primary and
        # Navidrome rows /rest/getCoverArt?id=<id>, both server-relative
        # paths the BROWSER can't use: relative they hit SoulSync's SPA
        # catch-all (200, index.html), absolutized they hit Jellyfin
        # unauthenticated (200, EMPTY body — #1159's signature). That's why
        # the Add Track / Swap Track modals still had no art after the
        # compare-view fix (#1164). Route both through the same token-safe
        # proxies the compare view uses.
        _art_prefix = ''
        _art_suffix = ''
        if active_server == 'plex' and media_server_engine.client('plex') and media_server_engine.client('plex').server:
            _ab = getattr(media_server_engine.client('plex').server, '_baseurl', '') or ''
            _at = getattr(media_server_engine.client('plex').server, '_token', '') or ''
            if not _ab:
                _pc = config_manager.get_plex_config()
                _ab = (_pc.get('base_url', '') or '').rstrip('/')
                _at = _at or _pc.get('token', '')
            _art_prefix = _ab
            _art_suffix = f"?X-Plex-Token={_at}" if _at else ''

        _jf_item_re = re.compile(r'/Items/([^/?#]+)/Images/Primary')
        _nd_cover_re = re.compile(r'getCoverArt\?(?:[^#]*?[?&])?id=([^&#]+)')

        def _resolve_search_thumb(url):
            if not url:
                return ''
            if active_server == 'jellyfin':
                m = _jf_item_re.search(url)
                if m:
                    return f"/api/server-activity/image?path=jf:{m.group(1)}"
                # external art (enrichment CDN) passes through; a relative
                # path we can't parse renders as no-art, not as index.html
                return url if url.startswith('http') else ''
            if active_server == 'navidrome':
                m = _nd_cover_re.search(url)
                if m:
                    return f"/api/navidrome/cover/{m.group(1)}"
                return url if url.startswith('http') else ''
            if url.startswith('http'):
                return url
            if url.startswith('/') and _art_prefix:
                return f"{_art_prefix}{url}{_art_suffix}"
            return url

        results = database.search_tracks(title=query, artist='', limit=limit,
                                         server_source=active_server, rank_artist=artist_hint)

        tracks = []
        for t in results:
            tracks.append({
                'id': t.id,
                'title': t.title,
                'artist_name': t.artist_name,
                'album_title': getattr(t, 'album_title', ''),
                'album_thumb_url': _resolve_search_thumb(getattr(t, 'album_thumb_url', '')),
                'file_path': getattr(t, 'file_path', ''),
                'bitrate': getattr(t, 'bitrate', 0),
                'duration': getattr(t, 'duration', 0),
                'server_source': getattr(t, 'server_source', ''),
            })

        return jsonify({"success": True, "tracks": tracks})
    except Exception as e:
        logger.error(f"Error searching library tracks: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


