@app.route('/api/manual-library-matches', methods=['POST'])
def mlm_save():
    """Create or replace a manual library match."""
    try:
        from core.library import manual_library_match as mlm
        data = request.get_json(force=True) or {}
        source = data.get('source', '').strip()
        source_track_id = data.get('source_track_id', '').strip()
        library_track_id = mlm.normalize_library_track_id(data.get('library_track_id'))
        if not source or not source_track_id or not library_track_id:
            return jsonify({"success": False, "error": "source, source_track_id, library_track_id required"}), 400
        db = get_database()
        profile_id = get_current_profile_id()
        # Validate library track exists before saving
        _lib_rows = db.api_get_tracks_by_ids([library_track_id])
        if not _lib_rows:
            return jsonify({"success": False, "error": "Library track not found — it may have been removed"}), 400
        # Store the file path so this match re-resolves after a rescan re-keys
        # the track (#787) — same durability the Find & Add path gets.
        _lib_file_path = (_lib_rows[0].get('file_path') or '') if _lib_rows else ''
        ok = mlm.save_match(
            db, profile_id, source, source_track_id, library_track_id,
            source_title=data.get('source_title', ''),
            source_artist=data.get('source_artist', ''),
            source_album=data.get('source_album', ''),
            source_context_json=data.get('source_context_json', ''),
            server_source=data.get('server_source', ''),
            library_file_path=_lib_file_path,
        )
        if not ok:
            return jsonify({"success": False, "error": "Failed to save match"}), 500
        match = db.get_manual_library_match(profile_id, source, source_track_id, data.get('server_source', ''))
        enriched = mlm._enrich_match(match, db) if match else {}
        return jsonify({"success": True, "match": enriched})
    except Exception as e:
        logger.error(f"mlm_save error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/manual-library-matches/<int:match_id>', methods=['DELETE'])
def mlm_delete(match_id):
    """Delete a manual library match by ID.

    Reports whether a row was actually removed (#1138): the delete is scoped to
    the CURRENT profile, so a match saved under another one silently matches
    nothing. Answering "success" to that left the user clicking the same button
    on the same row forever, with no way to tell the difference between "gone"
    and "wouldn't go"."""
    try:
        from core.library import manual_library_match as mlm
        db = get_database()
        profile_id = get_current_profile_id()
        if not mlm.delete_match(db, match_id, profile_id):
            return jsonify({
                "success": False,
                "error": "No matching entry for this profile — it may already be "
                         "removed, or it was saved under a different profile.",
            }), 404
        return jsonify({"success": True})
    except Exception as e:
        logger.error(f"mlm_delete error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/playlists/<playlist_id>/start-missing-process', methods=['POST'])
def start_missing_tracks_process(playlist_id):
    """
    A single, robust endpoint to kick off the entire missing tracks workflow.
    It creates a batch and starts the master worker in the background.
    """
    data = request.get_json() or {}
    tracks = data.get('tracks', [])
    playlist_name = data.get('playlist_name', 'Unknown Playlist')
    force_download_all = data.get('force_download_all', False)
    playlist_folder_mode = data.get('playlist_folder_mode', False)
    wing_it = data.get('wing_it', False)
    ignore_manual_matches = data.get('ignore_manual_matches')
    if ignore_manual_matches is None:
        ignore_manual_matches = bool(force_download_all and not wing_it)

    # Get album/artist context for artist album downloads
    is_album_download = data.get('is_album_download', False)
    album_context = data.get('album_context', None)
    artist_context = data.get('artist_context', None)
    # Issue #797 — per-request "Skip AcoustID verification" toggle from the
    # album-download modal. Stored on the batch and propagated per-track by
    # the master worker so AcoustID never quarantines this request's files.
    skip_acoustid = bool(data.get('skip_acoustid', False))
    # Blocklist override (Phase 2b): set by the modal's "download anyway" confirm.
    ignore_blocklist = bool(data.get('ignore_blocklist', False))
    # Quality Profile chosen in the shared acquisition dialog. Search, Discover,
    # Library, album, single, discography and playlist-explorer all POST here, so
    # this one field gives every manual path the same explicit choice (P1-01).
    # It outranks the mirror's persisted assignment for this action only; the
    # mirror row itself is unchanged unless the user edits it on the playlist.
    requested_quality_profile_id, quality_profile_error = _parse_requested_quality_profile_id(data)
    if quality_profile_error:
        return quality_profile_error
    # Provider hint so a mirror lookup can't be defeated by two providers sharing
    # an upstream playlist id (P2-01).
    playlist_source = data.get('source') or data.get('playlist_source') or None

    if not tracks:
        return jsonify({"success": False, "error": "No tracks provided"}), 400

    # Blocklist up-front check (Phase 2b): if the WHOLE album or artist being
    # downloaded is blocklisted, stop here with a clear, actionable response
    # instead of silently dropping every track in the per-track filter (2a) and
    # leaving an empty batch. Scattered single-track bans still fall through to
    # the per-track filter. The modal re-POSTs with ignore_blocklist=true after
    # the user confirms "download anyway".
    if not ignore_blocklist and (album_context or artist_context):
        try:
            _bsrc = _downloads_history.detect_sync_source(playlist_id)
            _synthetic = {
                'album': {'id': (album_context or {}).get('id'),
                          'name': (album_context or {}).get('name')},
                'artists': [{'id': (artist_context or {}).get('id'),
                             'name': (artist_context or {}).get('name')}],
            }
            _reason = get_database().blocklist_reason_for_track(
                get_current_profile_id(), _synthetic, source=_bsrc)
            if _reason:
                return jsonify({
                    "success": False, "blocked": True,
                    "blocked_entity_type": _reason[0], "blocked_name": _reason[1],
                }), 409
        except Exception as _bl_err:
            logger.debug("blocklist up-front check skipped: %s", _bl_err)

    # Log album context if provided
    if is_album_download and album_context and artist_context:
        logger.info(f"[Artist Album] Received album context: '{album_context.get('name')}' by '{artist_context.get('name')}' ({album_context.get('album_type', 'album')})")
        logger.info(f"   Release: {album_context.get('release_date', 'Unknown')}, Tracks: {album_context.get('total_tracks', len(tracks))}")

    # Log playlist folder mode if enabled
    if playlist_folder_mode:
        logger.info(f"[Playlist Folder] Enabled for playlist: '{playlist_name}'")

    # Persist organize-by-playlist preference on the mirrored playlist row
    try:
        profile_id = get_current_profile_id()
        db_pref = get_database()
        mirrored_pl = db_pref.resolve_mirrored_playlist(
            playlist_id,
            profile_id=profile_id,
            default_source='spotify',
        )
        if mirrored_pl and mirrored_pl.get('id'):
            db_pref.set_mirrored_playlist_organize_by_playlist(
                int(mirrored_pl['id']),
                bool(playlist_folder_mode),
                profile_id=profile_id,
            )
    except Exception as pref_err:
        logger.debug(f"[Playlist Folder] Could not persist mirrored preference: {pref_err}")

    # Limit concurrent analysis processes to prevent resource exhaustion
    with tasks_lock:
        active_analysis_count = sum(1 for batch in download_batches.values()
                                  if batch.get('phase') == 'analysis')
        if active_analysis_count >= 3:  # Allow max 3 concurrent analysis processes
            return jsonify({
                "success": False,
                "error": "Too many analysis processes running. Please wait for one to complete."
            }), 429

    batch_id = str(uuid.uuid4())

    # §52.8/§55.2: an Enhanced-/Global-Search "Begin Analysis" click is a
    # confirmed acquisition intent. Materialize its exact Artist/Release/Track
    # rows before the background search can fail or quarantine, then carry the
    # resolved ids/profile/correlation through the existing task payload. A
    # plain /api/search candidate lookup remains read-only, and non-search
    # playlist batches keep their established mirroring semantics.
    try:
        from core.library2 import ADMIN_PROFILE_ID
        from core.library2.confirmed_intent import (
            is_confirmed_search_process,
            materialize_confirmed_search_tracks,
        )
        _materialize_search = (
            get_current_profile_id() == ADMIN_PROFILE_ID
            and is_confirmed_search_process(playlist_id)
        )
        if _materialize_search:
            _lib2_conn = get_database()._get_connection()
            try:
                _requested_quality_profile = data.get('quality_profile_id')
                if _requested_quality_profile is None:
                    from core.library2.profile_lookup import default_quality_profile_id
                    _requested_quality_profile = default_quality_profile_id(_lib2_conn)
                tracks = list(materialize_confirmed_search_tracks(
                    _lib2_conn,
                    tracks,
                    album_context=album_context,
                    artist_context=artist_context,
                    explicit_profile_id=_requested_quality_profile,
                    profile_id=ADMIN_PROFILE_ID,
                    correlation_id=batch_id,
                ))
                _lib2_conn.commit()
            except Exception:
                _lib2_conn.rollback()
                raise
            finally:
                _lib2_conn.close()
    except ValueError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    except Exception as exc:
        logger.exception("Confirmed Search intent materialization failed")
        return jsonify({
            "success": False,
            "error": f"Could not prepare Library v2 search intent: {exc}",
        }), 500

    with tasks_lock:
        download_batches[batch_id] = {
            'phase': 'analysis',
            'playlist_id': playlist_id,
            'playlist_name': playlist_name,
            'queue': [],
            'active_count': 0,
            'max_concurrent': _get_batch_max_concurrent(is_album=is_album_download),
            # Track state management (replicating sync.py)
            'permanently_failed_tracks': [],
            'cancelled_tracks': set(),
            'queue_index': 0,
            'analysis_total': len(tracks),
            # Profile context for failed track wishlist re-adds
            'profile_id': get_current_profile_id(),
            'analysis_processed': 0,
            'analysis_results': [],
            'force_download_all': force_download_all,  # Pass the force flag to the batch
            # Replace-intent (#1045): ONLY a user-checked Force toggle means
            # "rewrite the existing file". force_download_all alone is NOT that
            # signal — wishlist batches set it to skip ownership checks, and
            # Wing It auto-ors it in client-side — so wing_it is excluded here
            # and the wishlist never sets this key at all.
            'force_replace': bool(force_download_all and not wing_it),
            'ignore_manual_matches': ignore_manual_matches,
            # Blocklist override (Phase 2b) — the user confirmed "download anyway"
            # at the modal, so the per-track filter (2a) skips this batch.
            'ignore_blocklist': ignore_blocklist,
            'playlist_folder_mode': playlist_folder_mode,  # Organize downloads by playlist folder
            # Album context for artist album downloads (explicit folder structure)
            'is_album_download': is_album_download,
            'album_context': album_context,
            'artist_context': artist_context,
            'wing_it': wing_it,
            'skip_acoustid': skip_acoustid,  # #797 per-request AcoustID bypass
            'batch_source': _downloads_history.detect_sync_source(playlist_id),
            # Explicit user choice for this batch — travels onto every track and
            # therefore also onto any failed-download Wishlist row (P1-01).
            'requested_quality_profile_id': requested_quality_profile_id,
            'playlist_source': playlist_source,
        }

    # Record sync history — derive source_page from context
    if playlist_id == 'wishlist':
        _source_page = 'wishlist'
    elif is_album_download:
        _source_page = 'album'
    elif playlist_id.startswith('youtube_'):
        _source_page = 'sync'
    else:
        _source_page = 'sync'
    # Resolve the mirror assignment BEFORE writing history. The per-track stamp
    # is applied later, inside _run_full_missing_tracks_process, so a history row
    # written first saw no stamp and recorded NULL for a mirror-assigned batch
    # (R2-07).
    _history_quality_profile_id = _resolve_batch_quality_profile_id(
        playlist_id, playlist_name,
        profile_id=get_current_profile_id(),
        explicit_quality_profile_id=requested_quality_profile_id,
        source=playlist_source,
    )
    _record_sync_history_start(batch_id, playlist_id, playlist_name, tracks,
                               is_album_download, album_context, artist_context,
                               playlist_folder_mode, source_page=_source_page,
                               quality_profile_id=_history_quality_profile_id)

    # Link YouTube playlist to download process if this is a YouTube playlist
    if playlist_id.startswith('youtube_'):
        url_hash = playlist_id.replace('youtube_', '')
        if url_hash in youtube_playlist_states:
            youtube_playlist_states[url_hash]['download_process_id'] = batch_id
            youtube_playlist_states[url_hash]['phase'] = 'downloading'
            youtube_playlist_states[url_hash]['converted_spotify_playlist_id'] = playlist_id
            logger.info(f"Linked YouTube playlist {url_hash} to download process {batch_id} (converted ID: {playlist_id})")

    # Link Tidal playlist to download process if this is a Tidal playlist
    if playlist_id.startswith('tidal_'):
        tidal_playlist_id = playlist_id.replace('tidal_', '')
        if tidal_playlist_id in tidal_discovery_states:
            tidal_discovery_states[tidal_playlist_id]['download_process_id'] = batch_id
            tidal_discovery_states[tidal_playlist_id]['phase'] = 'downloading'
            tidal_discovery_states[tidal_playlist_id]['converted_spotify_playlist_id'] = playlist_id
            logger.info(f"Linked Tidal playlist {tidal_playlist_id} to download process {batch_id} (converted ID: {playlist_id})")

    # Link Spotify Public playlist to download process if this is a Spotify Public playlist
    if playlist_id.startswith('spotify_public_'):
        sp_url_hash = playlist_id.replace('spotify_public_', '')
        if sp_url_hash in spotify_public_discovery_states:
            spotify_public_discovery_states[sp_url_hash]['download_process_id'] = batch_id
            spotify_public_discovery_states[sp_url_hash]['phase'] = 'downloading'
            spotify_public_discovery_states[sp_url_hash]['converted_spotify_playlist_id'] = playlist_id
            logger.info(f"Linked Spotify Public playlist {sp_url_hash} to download process {batch_id} (converted ID: {playlist_id})")

    # Link iTunes Link playlist to download process if this is an iTunes Link playlist
    if playlist_id.startswith('itunes_link_'):
        itunes_url_hash = playlist_id.replace('itunes_link_', '')
        if itunes_url_hash in itunes_link_discovery_states:
            itunes_link_discovery_states[itunes_url_hash]['download_process_id'] = batch_id
            itunes_link_discovery_states[itunes_url_hash]['phase'] = 'downloading'
            itunes_link_discovery_states[itunes_url_hash]['converted_spotify_playlist_id'] = playlist_id
            logger.info(f"Linked iTunes Link playlist {itunes_url_hash} to download process {batch_id} (converted ID: {playlist_id})")

    # Link Deezer playlist to download process if this is a Deezer playlist
    if playlist_id.startswith('deezer_'):
        deezer_playlist_id = playlist_id.replace('deezer_', '')
        if deezer_playlist_id in deezer_discovery_states:
            deezer_discovery_states[deezer_playlist_id]['download_process_id'] = batch_id
            deezer_discovery_states[deezer_playlist_id]['phase'] = 'downloading'
            deezer_discovery_states[deezer_playlist_id]['converted_spotify_playlist_id'] = playlist_id
            logger.info(f"Linked Deezer playlist {deezer_playlist_id} to download process {batch_id} (converted ID: {playlist_id})")

    # Stamp original index to keep task indices aligned with frontend row order
    for i, track in enumerate(tracks):
        if '_original_index' not in track:
            track['_original_index'] = i

    missing_download_executor.submit(_run_full_missing_tracks_process, batch_id, playlist_id, tracks)

    return jsonify({
        "success": True,
        "batch_id": batch_id
    })

@app.route('/api/tracks/download_missing', methods=['POST'])
def start_missing_downloads():
    """Legacy endpoint - redirect to new playlist-based endpoint"""
    dl_err = check_download_permission()
    if dl_err:
        return dl_err
    data = request.get_json()
    missing_tracks = data.get('missing_tracks', [])

    if not missing_tracks:
        return jsonify({"success": False, "error": "No missing tracks provided"}), 400

    # Use a default playlist_id for legacy compatibility
    playlist_id = "legacy_modal"

    # Call the new endpoint logic directly
    try:
        batch_id = str(uuid.uuid4())

        # Create task queue for this batch
        task_queue = []
        with tasks_lock:
            # Initialize batch management
            download_batches[batch_id] = {
                'queue': [],
                'active_count': 0,
                'max_concurrent': _get_max_concurrent(),
                'queue_index': 0,
                # Track state management (replicating sync.py)
                'permanently_failed_tracks': [],
                'cancelled_tracks': set(),
                # Profile context for failed track wishlist re-adds
                'profile_id': get_current_profile_id()
            }

            for track_index, track_data in enumerate(missing_tracks):
                task_id = str(uuid.uuid4())
                download_tasks[task_id] = {
                    'status': 'pending',
                    'track_info': track_data,
                    'playlist_id': playlist_id,
                    'batch_id': batch_id,
                    'track_index': track_index,
                    'download_id': None,
                    'username': None
                }

                # Add to batch queue instead of submitting immediately
                download_batches[batch_id]['queue'].append(task_id)

        # Start the first batch of downloads (up to 3)
        _start_next_batch_of_downloads(batch_id)

        return jsonify({"success": True, "batch_id": batch_id, "message": f"Queued {len(missing_tracks)} downloads for processing."})

    except Exception as e:
        logger.error(f"Error starting missing downloads: {e}")
        return jsonify({"success": False, "error": str(e)}), 500

