def _load_sync_status_file():
    """Load sync statuses from database."""
    try:
        database = get_database()
        raw = database.get_preference('sync_statuses')
        if raw:
            data = json.loads(raw)
            return data
        return {}
    except Exception as e:
        logger.error(f"Error loading sync status: {e}")
        return {}

def _save_sync_status_file(sync_statuses):
    """Save sync statuses to database."""
    try:
        database = get_database()
        database.set_preference('sync_statuses', json.dumps(sync_statuses))
    except Exception as e:
        logger.error(f"Error saving sync status: {e}")

def _parse_requested_quality_profile_id(data):
    """``(quality_profile_id, error_response)`` for an acquisition request.

    One validator for every manual acquisition surface — Search, Discover,
    Library, album, single, top tracks, discography, playlist explorer — so the
    same request field means the same thing everywhere (P1-01). Absent/None
    keeps whatever the server would have chosen (mirror assignment, then the
    global default); an unknown id is a 400 rather than a silent downgrade.
    """
    if not isinstance(data, dict) or data.get('quality_profile_id') is None:
        return None, None
    parsed = parse_strict_int(data.get('quality_profile_id'))
    if parsed is None or parsed <= 0:
        return None, (jsonify({"success": False, "error": "Invalid quality_profile_id"}), 400)
    if not get_database().quality_profile_exists(parsed):
        return None, (jsonify({"success": False, "error": "Unknown quality_profile_id"}), 400)
    return parsed, None


# _invalidate_mirror_sync_fingerprint moved to api/mirrored_playlists.py


def _sync_status_timestamp(status_info):
    """Return comparable timestamp for a persisted sync-status record."""
    if not status_info or 'last_synced' not in status_info:
        return None
    try:
        return datetime.fromisoformat(status_info['last_synced'])
    except (TypeError, ValueError):
        return None

def _latest_sync_status(*status_infos):
    """Pick the newest non-empty sync-status record."""
    candidates = [s for s in status_infos if s]
    if not candidates:
        return {}
    return max(candidates, key=lambda s: _sync_status_timestamp(s) or datetime.min)

def _mirrored_spotify_sync_status(playlist_id, sync_statuses, *, database=None, profile_id=None):
    """Return auto-sync status for a Spotify playlist mirrored into SoulSync."""
    try:
        db = database or get_database()
        profile = profile_id if profile_id is not None else get_current_profile_id()
        mirrored = db.get_mirrored_playlist_by_source('spotify', str(playlist_id), profile)
        if not mirrored:
            return {}
        return sync_statuses.get(f"auto_mirror_{mirrored.get('id')}", {})
    except Exception as e:
        logger.debug("Spotify mirrored sync-status lookup failed for %s: %s", playlist_id, e)
        return {}

def _resolve_spotify_playlist_sync_status(playlist_id, sync_statuses, *, database=None, profile_id=None):
    """Resolve direct or mirrored sync status for a Spotify playlist card."""
    direct_status = sync_statuses.get(playlist_id, {})
    mirrored_status = _mirrored_spotify_sync_status(
        playlist_id,
        sync_statuses,
        database=database,
        profile_id=profile_id,
    )
    return _latest_sync_status(direct_status, mirrored_status)

def _format_playlist_sync_status(status_info, playlist_snapshot):
    """Build user-facing sync-status text from persisted status + snapshot."""
    if 'last_synced' not in status_info:
        return "Never Synced"
    last_sync_time = datetime.fromisoformat(status_info['last_synced']).strftime('%b %d, %H:%M')
    stored_snapshot = status_info.get('snapshot_id')
    if stored_snapshot and playlist_snapshot and playlist_snapshot != stored_snapshot:
        return f"Last Sync: {last_sync_time}"
    return f"Synced: {last_sync_time}"

def _update_and_save_sync_status(playlist_id, playlist_name, playlist_owner, snapshot_id, **kwargs):
    """Updates the sync status for a given playlist and saves to file (same logic as GUI)."""
    try:
        # Load existing sync statuses
        sync_statuses = _load_sync_status_file()

        # Update this playlist's sync status
        from datetime import datetime
        now = datetime.now()
        status = {
            'name': playlist_name,
            'owner': playlist_owner,
            'snapshot_id': snapshot_id,
            'last_synced': now.isoformat()
        }
        # Store match counts and track hash for smart-skip on scheduled syncs
        # `quality_profile_id` is part of the smart-skip fingerprint: an
        # authoritative profile change must re-run the sync even when the track
        # list is byte-identical (P1-03).
        for key in ('matched_tracks', 'total_tracks', 'discovered_tracks', 'tracks_hash',
                    'mirror_tracks_hash', 'quality_profile_id'):
            if key in kwargs:
                status[key] = kwargs[key]
        sync_statuses[playlist_id] = status

        # Save to file
        _save_sync_status_file(sync_statuses)
        logger.info(f"Updated sync status for playlist '{playlist_name}' (ID: {playlist_id})")

    except Exception as e:
        logger.error(f"Error updating sync status for {playlist_id}: {e}")

@app.route('/api/spotify/playlists', methods=['GET'])
def get_spotify_playlists():
    """Fetches all user playlists from Spotify and enriches them with local sync status."""
    client = get_spotify_client_for_profile()
    if not client or not client.is_authenticated():
        return jsonify({"error": "Spotify not authenticated."}), 401
    try:
        playlists = client.get_user_playlists_metadata_only()
        sync_statuses = _load_sync_status_file()

        playlist_data = []

        # Add regular playlists first
        for p in playlists:
            status_info = _resolve_spotify_playlist_sync_status(p.id, sync_statuses)
            # Handle snapshot_id safely - may not exist in core Playlist class
            playlist_snapshot = getattr(p, 'snapshot_id', '')
            sync_status = _format_playlist_sync_status(status_info, playlist_snapshot)

            if 'last_synced' in status_info:
                stored_snapshot = status_info.get('snapshot_id')
                if stored_snapshot and playlist_snapshot and playlist_snapshot != stored_snapshot:
                    logger.info(
                        "Playlist sync status: name=%s id=%s snapshot=%r stored_snapshot=%r result=Needs Sync display=%s",
                        p.name,
                        p.id,
                        playlist_snapshot,
                        stored_snapshot,
                        sync_status,
                    )
                else:
                    logger.info(
                        "Playlist sync status: name=%s id=%s snapshot=%r stored_snapshot=%r result=Synced display=%s",
                        p.name,
                        p.id,
                        playlist_snapshot,
                        stored_snapshot,
                        sync_status,
                    )
            else:
                logger.warning(
                    "Playlist sync status: name=%s id=%s snapshot=%r result=Never Synced display=%s",
                    p.name,
                    p.id,
                    playlist_snapshot,
                    sync_status,
                )

            playlist_data.append({
                "id": p.id, "name": p.name, "owner": p.owner,
                "track_count": p.total_tracks,
                "image_url": getattr(p, 'image_url', None),
                "sync_status": sync_status,
                "snapshot_id": playlist_snapshot
            })

        # Add virtual "Liked Songs" playlist at the END (just count, no full fetch)
        try:
            liked_songs_count = client.get_saved_tracks_count()
            if liked_songs_count > 0:
                liked_songs_id = "spotify:liked-songs"
                status_info = sync_statuses.get(liked_songs_id, {})
                sync_status = "Never Synced"

                if 'last_synced' in status_info:
                    last_sync_time = datetime.fromisoformat(status_info['last_synced']).strftime('%b %d, %H:%M')
                    sync_status = f"Synced: {last_sync_time}"

                # Get user info for owner name
                user_info = client.get_user_info()
                owner_name = user_info.get('display_name', 'You') if user_info else 'You'

                # Add Liked Songs as LAST playlist
                playlist_data.append({
                    "id": liked_songs_id,
                    "name": "Liked Songs",
                    "owner": owner_name,
                    "track_count": liked_songs_count,
                    "image_url": None,  # Spotify doesn't provide image for Liked Songs
                    "sync_status": sync_status,
                    "snapshot_id": ""  # Liked Songs doesn't have a snapshot_id
                })
                logger.info(f"Added virtual 'Liked Songs' playlist with {liked_songs_count} tracks (count only)")
        except Exception as liked_error:
            logger.error(f"Failed to add Liked Songs playlist: {liked_error}")
            # Don't fail the entire request if Liked Songs fails

        return jsonify(playlist_data)
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/spotify/playlist/<playlist_id>', methods=['GET'])
def get_playlist_tracks(playlist_id):
    """Fetches full track details for a specific playlist."""
    # Use THIS profile's own Spotify (their playlists/private content); falls
    # back to the global/admin client for admin + unconnected profiles.
    client = get_spotify_client_for_profile() or spotify_client
    if not client or not client.is_authenticated():
        return jsonify({"error": "Spotify not authenticated."}), 401
    try:
        # Handle special "Liked Songs" virtual playlist
        if playlist_id == "spotify:liked-songs":
            user_info = client.get_user_info()
            owner_name = user_info.get('display_name', 'You') if user_info else 'You'

            # Fetch raw saved tracks with full album data
            tracks = []
            limit = 50
            offset = 0

            while True:
                if _spotify_rate_limited():
                    return jsonify({"error": "Spotify is currently rate limited. Please try again later."}), 429
                from core.api_call_tracker import api_call_tracker
                api_call_tracker.record_call('spotify', endpoint='current_user_saved_tracks')
                results = client.sp.current_user_saved_tracks(limit=limit, offset=offset)

                if not results or 'items' not in results:
                    break

                for item in results['items']:
                    if item['track'] and item['track']['id']:
                        track_data = item['track']
                        tracks.append({
                            'id': track_data['id'],
                            'name': track_data['name'],
                            'artists': track_data['artists'],  # Full artist objects (matches Download Missing Tracks behavior)
                            'album': track_data['album'],  # Full album object
                            'duration_ms': track_data['duration_ms'],
                            'popularity': track_data.get('popularity', 0),
                            'spotify_track_id': track_data['id']
                        })

                if len(results['items']) < limit or not results.get('next'):
                    break

                offset += limit

            # Create virtual playlist dict for Liked Songs
            playlist_dict = {
                'id': 'spotify:liked-songs',
                'name': 'Liked Songs',
                'description': 'Your saved tracks on Spotify',
                'owner': owner_name,
                'public': False,
                'collaborative': False,
                'track_count': len(tracks),
                'image_url': None,
                'snapshot_id': '',
                'tracks': tracks
            }
            return jsonify(playlist_dict)

        # Handle regular playlists
        if _spotify_rate_limited():
            return jsonify({"error": "Spotify is currently rate limited. Please try again later."}), 429
        # Fetch raw playlist data to preserve full album objects
        from core.api_call_tracker import api_call_tracker
        api_call_tracker.record_call('spotify', endpoint='playlist')
        playlist_data = client.sp.playlist(playlist_id)

        # Fetch all tracks with full album data
        tracks = []
        # The items endpoint intermittently fails for followed playlists — retry
        # once before resorting to the (≈100-capped) public embed scraper, so a
        # transient failure doesn't silently truncate a large playlist.
        results = None
        items_err = None
        for _attempt in range(2):
            try:
                results = client._get_playlist_items_page(playlist_id, limit=100)
                break
            except Exception as _e:
                items_err = _e
                if _attempt == 0:
                    logger.warning(f"Playlist items fetch failed ({_e}); retrying once")
                    time.sleep(0.5)
        if results is None:
            # Both attempts failed (often a 403 on followed playlists) — fall back
            # to the no-auth public path (full track list via anonymous token,
            # embed scraper if that fails).
            logger.warning(f"Playlist items unavailable after retry ({items_err}), trying public fetch")
            try:
                from core.spotify_public_scraper import fetch_spotify_public
                embed_data = fetch_spotify_public('playlist', playlist_id)
                if embed_data and not embed_data.get('error') and embed_data.get('tracks'):
                    for t in embed_data['tracks']:
                        artists = t.get('artists', [])
                        tracks.append({
                            'id': t.get('id', ''),
                            'name': t.get('name', ''),
                            'artists': artists if artists else [{'name': 'Unknown'}],
                            'album': {'name': '', 'images': []},
                            'duration_ms': t.get('duration_ms', 0),
                            'popularity': 0,
                            'spotify_track_id': t.get('id', '')
                        })
                    playlist_dict = {
                        'id': playlist_data['id'],
                        'name': playlist_data['name'],
                        'description': playlist_data.get('description', ''),
                        'owner': playlist_data['owner']['display_name'],
                        'public': playlist_data.get('public', False),
                        'collaborative': playlist_data.get('collaborative', False),
                        'track_count': len(tracks),
                        'image_url': playlist_data['images'][0]['url'] if playlist_data.get('images') else None,
                        'snapshot_id': playlist_data.get('snapshot_id', ''),
                        'tracks': tracks,
                        # Embed scrape is capped at ~100 — mark as incomplete.
                        'incomplete': True,
                        'expected_total': (playlist_data.get('tracks') or {}).get('total'),
                    }
                    return jsonify(playlist_dict)
            except Exception as scrape_err:
                logger.warning(f"Public embed scraper also failed: {scrape_err}")
            raise items_err  # Re-raise original error if both failed

        while results:
            for item in results['items']:
                # Handle both old API ('track') and new Feb 2026 API ('item') field names
                track_data = item.get('track') or item.get('item')
                if track_data and track_data.get('id'):
                    tracks.append({
                        'id': track_data['id'],
                        'name': track_data['name'],
                        'artists': track_data['artists'],  # Full artist objects (matches Download Missing Tracks behavior)
                        'album': track_data['album'],  # Full album object with album_type, total_tracks, etc.
                        'duration_ms': track_data['duration_ms'],
                        'popularity': track_data.get('popularity', 0),
                        'spotify_track_id': track_data['id']  # Also include as spotify_track_id for consistency
                    })

            if results.get('next'):
                api_call_tracker.record_call('spotify', endpoint='playlist_tracks_page')
                results = client.sp.next(results)
            else:
                results = None

        # Guard against silent truncation: Spotify occasionally returns a short
        # first page (next=None) for some playlists, so the loop above can end
        # early. Compare against the playlist's known total and flag it rather
        # than presenting a partial list as complete (bug #736).
        expected_total = (playlist_data.get('tracks') or {}).get('total')
        incomplete = bool(expected_total) and len(tracks) < expected_total
        if incomplete:
            logger.warning(
                f"Playlist {playlist_id} ('{playlist_data.get('name')}'): fetched "
                f"{len(tracks)}/{expected_total} tracks — Spotify returned incomplete "
                f"items data (flagged, not silently truncated)"
            )

        # Convert playlist to dict
        playlist_dict = {
            'id': playlist_data['id'],
            'name': playlist_data['name'],
            'description': playlist_data.get('description', ''),
            'owner': playlist_data['owner']['display_name'],
            'public': playlist_data.get('public', False),
            'collaborative': playlist_data.get('collaborative', False),
            'track_count': len(tracks),
            'image_url': playlist_data['images'][0]['url'] if playlist_data.get('images') else None,
            'snapshot_id': playlist_data.get('snapshot_id', ''),
            'tracks': tracks,
            'incomplete': incomplete,
            'expected_total': expected_total,
        }
        return jsonify(playlist_dict)
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/spotify/album/<album_id>', methods=['GET'])
def get_spotify_album_tracks(album_id):
    """Fetches full track details for a specific album."""
    _mark_request_free_ok_for_spotify('spotify')  # the URL itself targets Spotify
    use_hydrabase = _is_hydrabase_active()

    # Try Hydrabase first when active — look up by album soul_id
    if use_hydrabase:
        album_name = request.args.get('name', '')
        album_artist = request.args.get('artist', '')
        try:
            hydra_tracks = hydrabase_client.get_album_tracks(album_id, limit=50)
            if hydra_tracks:
                track_items = []
                for t in hydra_tracks:
                    artist_list = t.artists if isinstance(t.artists, list) else [t.artists] if t.artists else []
                    track_items.append({
                        'name': t.name,
                        'track_number': t.track_number or 0,
                        'disc_number': t.disc_number or 1,
                        'duration_ms': t.duration_ms,
                        'id': t.id,
                        'artists': [{'name': a} if isinstance(a, str) else a for a in artist_list],
                        'uri': ''
                    })
                return jsonify({
                    'id': album_id,
                    'name': album_name or hydra_tracks[0].album or '',
                    'artists': [{'name': album_artist}] if album_artist else [],
                    'release_date': '',
                    'total_tracks': len(track_items),
                    'album_type': 'album',
                    'images': [],
                    'tracks': track_items
                })
        except Exception as e:
            logger.warning(f"Hydrabase album_tracks failed for '{album_id}', falling back to Spotify: {e}")

    # Source override: when user clicked from a specific search tab
    source_override = request.args.get('source', '').strip().lower()

    if source_override == 'jiosaavn':
        try:
            from core.metadata.registry import (
                get_jiosaavn_client,
                experimental_source_rejected,
            )
            if experimental_source_rejected(source_override):
                return jsonify({"error": "JioSaavn is not enabled"}), 503
            client = get_jiosaavn_client()
            if not client:
                return jsonify({"error": "JioSaavn client unavailable"}), 503
            album_data = client.get_album(album_id)
            if not album_data:
                return jsonify({"error": "Album not found"}), 404
            tracks = album_data.get('tracks', [])
            if not isinstance(tracks, list):
                tracks = []
            return jsonify({
                'id': album_data['id'],
                'name': album_data['name'],
                'artists': album_data.get('artists', []),
                'release_date': album_data.get('release_date', ''),
                'total_tracks': album_data.get('total_tracks', len(tracks)),
                'album_type': album_data.get('album_type', 'album'),
                'images': album_data.get('images', []),
                'tracks': tracks,
            })
        except Exception as e:
            logger.error(f"JioSaavn album detail failed: {e}")
            return jsonify({"error": str(e)}), 500

    if source_override == 'bandcamp':
        try:
            from core.metadata.registry import (
                get_bandcamp_client,
                experimental_source_rejected,
            )
            if experimental_source_rejected(source_override):
                return jsonify({"error": "Bandcamp is not enabled"}), 503
            client = get_bandcamp_client()

            # Fast path: the click carried the exact release URL (Search
            # results and Discover cards do). Falls back to a name search
            # when it didn't (e.g. a release clicked from within an artist's
            # discography grid, which only has a title/id) — Bandcamp has no
            # numeric-ID lookup API, so a URL or a name is all it can work from.
            bandcamp_url = request.args.get('bandcamp_url', '').strip()
            album_name = request.args.get('name', '')
            album_artist = request.args.get('artist', '')

            release = client.get_release_metadata(bandcamp_url) if bandcamp_url else None
            if not release and album_artist and album_name:
                release = client.search_album(album_artist, album_name)
            if not release:
                return jsonify({"error": "Album not found"}), 404

            from core.bandcamp_client import release_to_spotify_shape
            return jsonify(release_to_spotify_shape(release, album_id, album_name, album_artist))
        except Exception as e:
            logger.error(f"Bandcamp album detail failed: {e}")
            return jsonify({"error": str(e)}), 500

    if not spotify_client or not spotify_client.is_authenticated():
        return jsonify({"error": "Spotify not authenticated."}), 401
    try:
        # Use explicit source client when overridden (prevents numeric ID misrouting)
        client = spotify_client
        if source_override == 'itunes':
            client = _get_itunes_client()
        elif source_override == 'hydrabase':
            # Hydrabase IDs originate from whichever plugin the peer runs.
            # 'plugin' param is authoritative; fall back to ID format detection.
            plugin = request.args.get('plugin', '').lower()
            if plugin == 'itunes' or (not plugin and album_id.isdigit()):
                client = _get_itunes_client()
            elif plugin == 'deezer':
                client = _get_deezer_client()
            # else: spotify (default)
        elif source_override == 'deezer':
            client = _get_deezer_client()
        elif source_override == 'discogs':
            client = _get_discogs_client()
        elif source_override == 'amazon':
            from core.metadata.registry import get_amazon_client
            client = get_amazon_client()
        elif source_override == 'musicbrainz':
            try:
                from core.musicbrainz_search import MusicBrainzSearchClient
                mb_search = MusicBrainzSearchClient()
                album_data = mb_search.get_album(album_id)
                if not album_data:
                    return jsonify({"error": "Album not found on MusicBrainz"}), 404
                return jsonify(album_data)
            except Exception as e:
                logger.error(f"MusicBrainz album detail failed: {e}")
                return jsonify({"error": str(e)}), 500

        album_data = client.get_album(album_id)
        if not album_data:
            return jsonify({"error": "Album not found"}), 404

        # Extract tracks — handle Spotify {items, total} or flat-list formats
        tracks_container = album_data.get('tracks', {})
        if isinstance(tracks_container, list):
            tracks = tracks_container
        else:
            tracks = tracks_container.get('items', [])

        # If no tracks in album data (iTunes format), fetch them separately
        if not tracks:
            tracks_data = client.get_album_tracks(album_id)
            if tracks_data and 'items' in tracks_data:
                tracks = tracks_data['items']

        # Format response
        album_dict = {
            'id': album_data['id'],
            'name': album_data['name'],
            'artists': album_data.get('artists', []),
            'release_date': album_data.get('release_date', ''),
            'total_tracks': album_data.get('total_tracks', 0),
            'album_type': album_data.get('album_type', 'album'),
            'images': album_data.get('images', []),
            'tracks': tracks
        }
        return jsonify(album_dict)
    except Exception as e:
        logger.error(f"Error fetching album tracks: {e}")
        return jsonify({"error": str(e)}), 500


@app.route('/api/spotify/track/<track_id>', methods=['GET'])
def get_spotify_track(track_id):
    """Fetches full track details including album data for a specific track."""
    source_override = request.args.get('source', '').strip().lower()

    if source_override == 'jiosaavn':
        try:
            from core.metadata.registry import (
                get_jiosaavn_client,
                experimental_source_rejected,
            )
            if experimental_source_rejected(source_override):
                return jsonify({"error": "JioSaavn is not enabled"}), 503
            client = get_jiosaavn_client()
            if not client:
                return jsonify({"error": "JioSaavn client unavailable"}), 503
            track_data = client.get_track_details(track_id)
            if not track_data:
                return jsonify({"error": "Track not found"}), 404
            return jsonify(track_data)
        except Exception as e:
            logger.error(f"JioSaavn track detail failed: {e}")
            return jsonify({"error": str(e)}), 500

    if source_override == 'bandcamp':
        try:
            from core.metadata.registry import (
                get_bandcamp_client,
                experimental_source_rejected,
            )
            if experimental_source_rejected(source_override):
                return jsonify({"error": "Bandcamp is not enabled"}), 503
            client = get_bandcamp_client()

            bandcamp_url = request.args.get('bandcamp_url', '').strip()
            track_name = request.args.get('name', '')
            track_artist = request.args.get('artist', '')

            release = client.get_release_metadata(bandcamp_url) if bandcamp_url else None
            result = None
            if release:
                result = {
                    'title': release.get('title', track_name),
                    'url': bandcamp_url,
                    'artist': release.get('artist') or track_artist,
                    'image_url': release.get('image_url'),
                }
            elif track_artist and track_name:
                result = client.search_track(track_artist, track_name)
            if not result:
                return jsonify({"error": "Track not found"}), 404

            return jsonify({
                'id': result.get('url', ''),
                'name': result.get('title', track_name),
                'artists': [{'name': result.get('artist') or track_artist}],
                'album': {'name': '', 'images': [{'url': result['image_url']}] if result.get('image_url') else []},
                'duration_ms': 0,
                'preview_url': None,
                'external_urls': {'bandcamp': result.get('url', '')},
                'popularity': 0,
            })
        except Exception as e:
            logger.error(f"Bandcamp track detail failed: {e}")
            return jsonify({"error": str(e)}), 500

    # Try Hydrabase first when active and track name provided
    if _is_hydrabase_active():
        track_name = request.args.get('name', '')
        track_artist = request.args.get('artist', '')
        if track_name:
            try:
                query = f"{track_artist} {track_name}".strip() if track_artist else track_name
                hydra_tracks = hydrabase_client.search_tracks(query, limit=1)
                if hydra_tracks:
                    t = hydra_tracks[0]
                    artist_list = t.artists if isinstance(t.artists, list) else [t.artists] if t.artists else []
                    return jsonify({
                        'id': t.id,
                        'name': t.name,
                        'artists': [{'name': a} if isinstance(a, str) else a for a in artist_list],
                        'album': {'name': t.album, 'images': [{'url': t.image_url}] if t.image_url else []},
                        'duration_ms': t.duration_ms,
                        'preview_url': t.preview_url,
                        'external_urls': t.external_urls or {},
                        'popularity': t.popularity,
                    })
            except Exception as e:
                logger.warning(f"Hydrabase track lookup failed for '{track_name}', falling back to Spotify: {e}")

    if not spotify_client or not spotify_client.is_authenticated():
        return jsonify({"error": "Spotify not authenticated."}), 401
    try:
        track_data = spotify_client.get_track_details(track_id)
        if not track_data:
            return jsonify({"error": "Track not found"}), 404

        return jsonify(track_data)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


