@app.route('/api/mirror-playlist', methods=['POST'])
def mirror_playlist_endpoint():
    """Save or update a mirrored playlist."""
    try:
        data = request.get_json()
        if not data:
            return jsonify({"error": "No data received"}), 400

        source = data.get('source')
        source_playlist_id = data.get('source_playlist_id')
        name = data.get('name')
        tracks = data.get('tracks', [])

        if not all([source, source_playlist_id, name]):
            return jsonify({"error": "source, source_playlist_id, and name are required"}), 400

        database = get_database()
        profile_id = get_current_profile_id()
        quality_profile_id = data.get('quality_profile_id')
        if quality_profile_id is not None:
            try:
                quality_profile_id = int(quality_profile_id)
            except (TypeError, ValueError):
                return jsonify({"error": "Invalid quality_profile_id"}), 400
            if not database.quality_profile_exists(quality_profile_id):
                return jsonify({"error": "Unknown quality_profile_id"}), 400

        playlist_id = database.mirror_playlist(
            source=source,
            source_playlist_id=str(source_playlist_id),
            name=name,
            tracks=tracks,
            profile_id=profile_id,
            quality_profile_id=quality_profile_id,
            description=data.get('description'),
            owner=data.get('owner'),
            image_url=data.get('image_url')
        )

        if playlist_id is None:
            return jsonify({"error": "Failed to mirror playlist"}), 500

        # Membership just changed — if organize-by-playlist, rebuild its folder
        # (with prune) so a removed track's symlink is cleaned up now. Gated +
        # non-fatal, so it can never break the mirror response.
        try:
            from core.playlists.materialize_service import rebuild_mirrored_playlist_if_organized
            rebuild_mirrored_playlist_if_organized(database, config_manager, playlist_id, profile_id=profile_id)
        except Exception as _mat_err:
            logger.debug("[Playlist Folder] mirror-time cleanup skipped: %s", _mat_err)

        try:
            if automation_engine:
                automation_engine.emit('mirrored_playlist_created', {
                    'playlist_name': name,
                    'source': source,
                    'track_count': str(len(tracks)),
                })
        except Exception as e:
            logger.debug("mirrored_playlist_created emit failed: %s", e)

        return jsonify({"success": True, "playlist_id": playlist_id})
    except ValueError as ve:
        # #990: malformed/all-empty track payload — a client error, not a 500.
        logger.warning(f"mirror-playlist rejected: {ve}")
        return jsonify({"error": str(ve)}), 400
    except Exception as e:
        logger.error(f"Error mirroring playlist: {e}")
        return jsonify({"error": str(e)}), 500

