def _spotify_status_with_availability(spotify_status):
    """Augment the spotify status dict with the Spotify-Free availability flags
    the UI needs: ``metadata_available`` (search picker) and ``free_installed``
    (Settings source selector — 'Spotify Free' is selectable when the package is
    installed, since selecting it is the opt-in). Used by BOTH the /status
    endpoint and the WebSocket status push so they never drift."""
    out = dict(spotify_status or {})
    try:
        out['metadata_available'] = bool(
            spotify_client and spotify_client.is_spotify_metadata_available())
    except Exception:
        out['metadata_available'] = bool(out.get('authenticated'))
    try:
        from core.spotify_free_metadata import spotify_free_installed
        out['free_installed'] = spotify_free_installed()
    except Exception:
        out['free_installed'] = False
    return out


def _build_status_payload():
    """Build the same status payload used by GET /status, reading from the cache."""
    download_mode = config_manager.get('download_source.mode', 'hybrid')
    soulseek_data = dict(_status_cache.get('soulseek', {}))
    soulseek_data['source'] = download_mode
    metadata_status = get_metadata_status_snapshot(spotify_client=spotify_client)

    # Count active downloads for nav badge
    active_dl_count = 0
    try:
        with tasks_lock:
            for t in download_tasks.values():
                if t.get('status') in ('downloading', 'searching', 'post_processing', 'queued', 'pending'):
                    active_dl_count += 1
    except Exception as e:
        logger.debug("active download count failed: %s", e)

    return {
        'metadata_source': metadata_status['metadata_source'],
        'spotify': _spotify_status_with_availability(metadata_status['spotify']),
        'media_server': _status_cache.get('media_server', {}),
        'soulseek': soulseek_data,
        'active_media_server': config_manager.get_active_media_server(),
        'enrichment': _get_enrichment_status(),
        'active_downloads': active_dl_count,
    }

def _build_watchlist_count_payload(profile_id=1):
    """Build the same payload used by GET /api/watchlist/count."""
    try:
        database = get_database()
        count = database.get_watchlist_count(profile_id=profile_id)
    except Exception:
        count = 0
    next_run_in_seconds = automation_engine.get_system_automation_next_run_seconds('scan_watchlist') if automation_engine else 0
    return {
        'success': True,
        'count': count,
        'next_run_in_seconds': next_run_in_seconds
    }

def _hydrabase_reconnect_loop():
    """Background thread that monitors Hydrabase connection and auto-reconnects if needed."""
    from api import hydrabase_routes as _hb
    _consecutive_failures = 0

    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(30)
        try:
            # Only attempt reconnect if auto_connect is enabled
            hydra_cfg = config_manager.get_hydrabase_config()
            if not hydra_cfg.get('auto_connect') or not hydra_cfg.get('url') or not hydra_cfg.get('api_key'):
                _consecutive_failures = 0
                continue

            # Check if already connected
            try:
                if _hb._hydrabase_ws is not None and _hb._hydrabase_ws.connected:
                    _consecutive_failures = 0
                    continue
            except Exception as e:
                logger.debug("hydrabase socket check: %s", e)

            # Disconnected with auto_connect enabled — try to reconnect
            # Back off: 30s, 60s, 120s, max 300s between attempts
            backoff = min(30 * (2 ** _consecutive_failures), 300)
            if _consecutive_failures > 0:
                socketio.sleep(backoff - 30)  # Already slept 30s at top of loop

            import websocket
            try:
                with _hb._hydrabase_lock:
                    if _hb._hydrabase_ws:
                        try:
                            _hb._hydrabase_ws.close()
                        except Exception as e:
                            logger.debug("hydrabase reconnect close: %s", e)
                    ws = websocket.create_connection(
                        hydra_cfg['url'],
                        header={"x-api-key": hydra_cfg['api_key']},
                        timeout=10
                    )
                    _hb._hydrabase_ws = ws
                _consecutive_failures = 0
                logger.info(f"[Hydrabase] Auto-reconnected to {hydra_cfg['url']}")
            except Exception as e:
                _consecutive_failures += 1
                if _consecutive_failures <= 3:
                    logger.error(f"[Hydrabase] Reconnect attempt failed ({_consecutive_failures}): {e}")
                elif _consecutive_failures == 4:
                    logger.error("[Hydrabase] Reconnect failing repeatedly — suppressing further logs until success")
        except Exception as e:
            logger.debug("hydrabase monitor loop: %s", e)

# --- Global connected-client tracking (gates idle broadcast loops below) ---
# Same pattern as _activity_sids, but for "is anyone listening at all" rather
# than a specific room: dashboard-wide push loops have no per-client work to
# skip, only an all-or-nothing "does this broadcast have an audience".
_connected_sids = set()
_connected_sids_lock = threading.Lock()
_log_live_sids = set()
_log_live_sids_lock = threading.Lock()


def _has_connected_clients() -> bool:
    with _connected_sids_lock:
        return bool(_connected_sids)


