# Library Manager v2 — the UI-facing API mounted on /api/library/v2/*.
# NOT opt-in: the cutover happened, lib2_* is the maintained catalogue, and
# zero runtime SQL touches the legacy tables (enforced by
# tests/library2/test_legacy_usage_ratchet.py against a 0-reads/0-writes
# baseline). See core/library2/__init__.py.
# Library V2 is the native, non-disableable catalogue surface.
from api.library_v2 import register_library_v2_routes as _register_library_v2_routes


def _library_v2_submission_adapter(source):
    if source != "usenet" or download_orchestrator is None:
        return None
    plugin = download_orchestrator.registry.get("usenet")
    if plugin is None:
        return None
    from core.acquisition.submission import UsenetSubmissionAdapter
    return UsenetSubmissionAdapter(
        monitor_callback=(
            usenet_acquisition_monitor.notify_submission
            if usenet_acquisition_monitor is not None else None
        ))


def _library_v2_scoped_wishlist_search(track_ids, profile_id):
    """Submit a manual wishlist batch scoped to exactly ``track_ids`` — same
    executors/pools ``/api/wishlist/download_missing`` uses. Injected into
    the Library-v2 scoped Automatic Search endpoint (C1) so it dispatches
    through the identical download path instead of a second one."""
    from database.music_database import MusicDatabase
    db = MusicDatabase()
    runtime = _WishlistManualDownloadRuntime(
        get_music_database=lambda: db,
        download_batches=download_batches,
        tasks_lock=tasks_lock,
        # Its own small pool (not the shared missing_download_executor) so a
        # scoped/manual single-item search is never starved by a busy
        # periodic wishlist auto-cycle (docs §69.3) — same precedent as
        # album_bundle_executor below.
        missing_download_executor=scoped_search_executor,
        album_bundle_executor=album_bundle_executor,
        run_full_missing_tracks_process=_run_full_missing_tracks_process,
        get_batch_max_concurrent=_get_batch_max_concurrent,
        add_activity_item=add_activity_item,
        active_server=config_manager.get_active_media_server(),
        profile_id=profile_id,
    )
    payload, _status = _start_manual_wishlist_download_batch(runtime, track_ids=track_ids)
    return payload


def _library_v2_scoped_direct_search(tracks, profile_id):
    """Run transient Library-v2 payloads through the shared download engine.

    Unlike the Wishlist-scoped adapter above, this is used for one concrete
    track click and never persists the track in Wishlist merely to make the
    existing worker see it.
    """
    from database.music_database import MusicDatabase
    from core.imports.upgrade_intent import CONTEXT_KEY, issue_upgrade_intent
    tracks = [dict(track) for track in tracks]
    for track in tracks:
        source_info = track.get('source_info') or {}
        if isinstance(source_info, str):
            try:
                source_info = json.loads(source_info)
            except (TypeError, ValueError):
                source_info = {}
        track_id = source_info.get('lib2_track_id') if isinstance(source_info, dict) else None
        if track_id:
            track[CONTEXT_KEY] = issue_upgrade_intent(
                track_id, origin='scoped_automatic_search')
    db = MusicDatabase()
    runtime = _WishlistManualDownloadRuntime(
        get_music_database=lambda: db,
        download_batches=download_batches,
        tasks_lock=tasks_lock,
        missing_download_executor=scoped_search_executor,
        album_bundle_executor=album_bundle_executor,
        run_full_missing_tracks_process=_run_full_missing_tracks_process,
        get_batch_max_concurrent=_get_batch_max_concurrent,
        add_activity_item=add_activity_item,
        active_server=config_manager.get_active_media_server(),
        profile_id=profile_id,
    )
    payload, _status = _start_direct_track_download_batch(runtime, tracks)
    return payload


# core.library2.match_status.SERVICES ids that spell their "configured" flag
# under a different key in _get_enrichment_status() (the enrichment workers'
# keys carry a '_enrichment' suffix for some services; others match as-is).
_LIB2_MATCH_SERVICE_ENRICHMENT_KEYS = {
    "spotify": "spotify_enrichment",
    "deezer": "deezer_enrichment",
    "itunes": "itunes_enrichment",
    "tidal": "tidal_enrichment",
    "qobuz": "qobuz_enrichment",
    "amazon": "amazon_enrichment",
    "jiosaavn": "jiosaavn_enrichment",
    "bandcamp": "bandcamp_enrichment",
}


def _library_v2_live_artist_stats(spotify_id):
    """On-demand single-artist Spotify lookup for the settings modal's
    current-match identity card (§52.5/§56.2) — same pattern the legacy
    ``/api/watchlist/artist/<id>/config`` endpoint already uses: one call per
    load, gated on auth + the global rate-limit flag, ``None`` on any
    failure so the identity card just omits the stat row."""
    if not spotify_client or not spotify_client.is_authenticated() or _spotify_rate_limited():
        return None
    try:
        from core.api_call_tracker import api_call_tracker
        api_call_tracker.record_call('spotify', endpoint='artist')
        artist_data = spotify_client.sp.artist(spotify_id)
    except Exception as e:
        logger.debug(f"live artist stats fetch failed for {spotify_id}: {e}")
        return None
    if not artist_data:
        return None
    images = artist_data.get('images') or []
    return {
        'name': artist_data.get('name') or None,
        'image_url': images[0].get('url') if images and isinstance(images[0], dict) else None,
        'followers': artist_data.get('followers', {}).get('total', 0),
        'popularity': artist_data.get('popularity', 0),
        'genres': artist_data.get('genres') or [],
    }


def _library_v2_configured_match_services() -> set:
    """Which match_status.SERVICES ids are actually configured on this
    instance right now (deep-dive A8) — reuses the exact 'configured' flags
    the Settings enrichment-status cards already show, so the lib2 match
    chips never drift from what Enrich/Settings consider usable. A service
    absent from ``_get_enrichment_status()`` (worker not running, or gated
    behind an experimental flag) is correctly treated as not configured."""
    from core.library2.match_status import SERVICES as _lib2_match_services
    try:
        status = _get_enrichment_status()
    except Exception:
        return set()
    configured = set()
    for service, _label, _id_cols in _lib2_match_services:
        key = _LIB2_MATCH_SERVICE_ENRICHMENT_KEYS.get(service, service)
        entry = status.get(key)
        if entry and entry.get("configured"):
            configured.add(service)
    # MusicBrainz has no credentials to configure and no longer needs its
    # worker to answer a search, so it is available whenever the app is.
    # _get_enrichment_status() reports only services that HAVE a worker object,
    # so a failed worker init used to drop MusicBrainz out of every enrich walk
    # — silently, since the walk swallows per-provider failures. A missing MBID
    # is what leaves the AcoustID check without an artist's alternate
    # spellings, so this is the one service that must not go missing quietly.
    configured.add("musicbrainz")
    return configured


def _acquisition_runtime_evidence():
    """Take short, lock-protected copies before any client or DB I/O."""
    with tasks_lock:
        runtime_tasks = {
            str(task_id): dict(task)
            for task_id, task in download_tasks.items()
            if isinstance(task, dict)
        }
    with matched_context_lock:
        matched_contexts = [
            dict(context)
            for context in matched_downloads_context.values()
            if isinstance(context, dict)
        ]
    from api.quarantine import _get_quarantine_dir
    from core.imports.quarantine import (
        get_quarantine_entry_context,
        list_quarantine_entries,
    )
    quarantine_entries = []
    for entry in list_quarantine_entries(_get_quarantine_dir()):
        item = dict(entry)
        item["context"] = get_quarantine_entry_context(
            _get_quarantine_dir(), str(entry.get("id") or ""),
        )
        quarantine_entries.append(item)
    return runtime_tasks, matched_contexts, quarantine_entries


def _acquisition_client_observations():
    if download_orchestrator is None:
        return {}
    try:
        # dd28-17: this runs inside the Usenet monitor's cycle lock via
        # persistent_reconciler_runner, so an unbounded wait on slskd would
        # freeze Usenet reconciliation and the import pipeline too.
        from core.acquisition.client_monitor import CLIENT_CALL_TIMEOUT_S
        statuses = run_async(
            download_orchestrator.get_all_downloads(),
            timeout=CLIENT_CALL_TIMEOUT_S,
        ) or []
    except Exception as exc:  # external evidence is optional, never inferred
        logger.warning("Persistent acquisition client snapshot failed: %s", exc)
        return {}
    observations = {}
    for status in statuses:
        download_id = str(getattr(status, "id", "") or "").strip()
        if not download_id:
            continue
        observations[download_id] = {
            "state": getattr(status, "state", None),
            "file_path": getattr(status, "file_path", None),
            "filename": getattr(status, "filename", None),
        }
    return observations


def _run_persistent_acquisition_reconciliation(*, dry_run=True):
    """Reconcile restart-lost legacy grabs from independently observed facts."""
    from core.acquisition import ensure_acquisition_schema
    from core.acquisition.reconciler import reconcile_persistent_grabs

    runtime_tasks, matched_contexts, quarantine_entries = (
        _acquisition_runtime_evidence()
    )
    client_observations = _acquisition_client_observations()
    conn = get_database()._get_connection()
    try:
        ensure_acquisition_schema(conn)
        report = reconcile_persistent_grabs(
            conn,
            runtime_tasks=runtime_tasks,
            matched_contexts=matched_contexts,
            client_observations=client_observations,
            quarantine_entries=quarantine_entries,
            dry_run=bool(dry_run),
            evidence_ttl_seconds=config_manager.get(
                "acquisition.reconciliation_evidence_ttl_seconds", 24 * 60 * 60,
            ),
        )
        if dry_run:
            conn.rollback()
        else:
            conn.commit()
        return report.to_public_dict()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _library_v2_media_server_state():
    active_server = config_manager.get_active_media_server()
    connected = False
    if media_server_engine is not None:
        try:
            connected = bool(media_server_engine.is_connected())
        except Exception as exc:
            logger.debug("Integrity report media-server probe failed: %s", exc)
    return {
        "available": media_server_engine is not None,
        "active_server": active_server,
        "connected": connected,
        # The cross-server contract has no uniform full track-path read. The
        # scoped mapping table is the comparable recognition index; file paths
        # themselves remain local Library-v2 ownership.
        "path_projection": "tracks.file_path",
    }


def _run_library_v2_integrity_report(*, max_findings=1000):
    """One read-only cross-index snapshot; no schema ensure or repair writes."""
    from api.quarantine import _get_quarantine_dir
    from core.acquisition.reconciler import reconcile_persistent_grabs
    from core.library2.integrity_reconciler import build_integrity_report

    runtime_tasks, matched_contexts, quarantine_entries = (
        _acquisition_runtime_evidence()
    )
    client_observations = _acquisition_client_observations()
    conn = get_database()._get_connection()
    try:
        has_acquisition = all(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (table,),
            ).fetchone() is not None
            for table in ("acquisition_requests", "acquisition_grabs")
        )
        acquisition_report = None
        if has_acquisition:
            acquisition_report = reconcile_persistent_grabs(
                conn,
                runtime_tasks=runtime_tasks,
                matched_contexts=matched_contexts,
                client_observations=client_observations,
                quarantine_entries=quarantine_entries,
                dry_run=True,
                evidence_ttl_seconds=config_manager.get(
                    "acquisition.reconciliation_evidence_ttl_seconds",
                    24 * 60 * 60,
                ),
            ).to_public_dict()
        report = build_integrity_report(
            conn,
            runtime_tasks=runtime_tasks,
            matched_contexts=matched_contexts,
            client_observations=client_observations,
            quarantine_entries=quarantine_entries,
            quarantine_dir=_get_quarantine_dir(),
            acquisition_report=acquisition_report,
            media_server=_library_v2_media_server_state(),
            config_manager=config_manager,
            max_findings=max_findings,
        )
        # A read endpoint owns no commit boundary, even if a future path helper
        # accidentally begins a transaction.
        conn.rollback()
        return report.to_public_dict()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _library_v2_profile_page_allowed(page_id):
    """Apply the persisted profile page ACL to Library v2 API reads.

    Library v2 intentionally shares the legacy ``library`` permission instead
    of introducing a second checkbox during the cutover.
    """
    profile_id = get_current_profile_id()
    if profile_id == 1:
        return True
    profile = get_database().get_profile(profile_id)
    if not profile:
        return False
    allowed_pages = profile.get('allowed_pages')
    return allowed_pages is None or page_id in allowed_pages


_register_library_v2_routes(
    app,
    get_database=get_database,
    config_get=lambda key, default=None: config_manager.get(key, default),
    config_manager=config_manager,
    profile_id_getter=get_current_profile_id,
    profile_page_allowed_getter=_library_v2_profile_page_allowed,
    acquisition_submission_adapter_getter=_library_v2_submission_adapter,
    run_enrichment=_run_single_enrichment,
    scoped_wishlist_search_dispatcher=_library_v2_scoped_wishlist_search,
    scoped_track_search_dispatcher=_library_v2_scoped_direct_search,
    configured_match_services_getter=_library_v2_configured_match_services,
    live_artist_stats_getter=_library_v2_live_artist_stats,
    make_context_key=_make_context_key,
    get_cached_transfer_data=get_cached_transfer_data,
    acquisition_reconciliation_runner=(
        _run_persistent_acquisition_reconciliation
    ),
    integrity_report_runner=_run_library_v2_integrity_report,
)


def _emit_rate_monitor_loop():
    """Background thread that pushes API call rate data every 1 second for speedometer gauges.
    Also includes enrichment worker status so the combined cards have everything."""
    # Map rate monitor service keys to enrichment status keys
    _enrichment_key_map = {
        'spotify': 'spotify_enrichment', 'itunes': 'itunes_enrichment',
        'deezer': 'deezer_enrichment', 'lastfm': 'lastfm', 'genius': 'genius',
        'musicbrainz': 'musicbrainz', 'audiodb': 'audiodb', 'discogs': 'discogs',
        'tidal': 'tidal_enrichment', 'qobuz': 'qobuz_enrichment', 'amazon': 'amazon_enrichment',
        'jiosaavn': 'jiosaavn_enrichment',
    }

    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(1)
        if not _has_connected_clients():
            continue
        try:
            from core.api_call_tracker import api_call_tracker
            payload = api_call_tracker.get_all_rates()

            # Merge enrichment worker status into each service
            try:
                enrichment = _get_enrichment_status()
                for svc_key, entry in payload.items():
                    enr_key = _enrichment_key_map.get(svc_key)
                    enr = enrichment.get(enr_key) if enr_key else None
                    if enr:
                        entry['worker'] = {
                            'status': 'not_configured' if not enr.get('configured') else
                                      'paused' if enr.get('paused') else
                                      'idle' if enr.get('idle') else
                                      'running' if enr.get('running') else 'stopped',
                            'yield_reason': enr.get('yield_reason', ''),
                            'calls_1h': enr.get('calls_1h', 0),
                            'calls_24h': enr.get('calls_24h', 0),
                        }
                        if svc_key == 'spotify' and enr.get('daily_budget'):
                            entry['worker']['daily_budget'] = enr['daily_budget']
                            # Budget ring styling: purple when the worker has
                            # bridged to Spotify Free after spending the budget.
                            entry['worker']['using_free'] = bool(enr.get('using_free'))
            except Exception as e:
                logger.debug("enrichment worker status build failed: %s", e)

            # Add Spotify rate limit state
            try:
                spotify_status = get_spotify_status(spotify_client=spotify_client)
                rl_info = spotify_status.get('rate_limit')
                if spotify_status.get('rate_limited') and rl_info:
                    payload['spotify']['rate_limited'] = True
                    payload['spotify']['rl_remaining'] = rl_info.get('remaining_seconds', 0)
                    payload['spotify']['rl_endpoint'] = rl_info.get('endpoint', '')
            except Exception as e:
                logger.debug("spotify rate-limit status read failed: %s", e)

            socketio.emit('rate-monitor:update', payload)
        except Exception as e:
            logger.debug(f"Error emitting rate monitor: {e}")


# Idle-worker stats cache for the enrichment socket loop: name → (monotonic,
# status). Emits still happen every 2s (the UI heartbeat is untouched) — this
# only spaces out the DATABASE reads behind them for workers that are idle.
_enrich_stats_cache: dict = {}
_ENRICH_IDLE_STATS_TTL = 30.0


def _emit_enrichment_status_loop():
    """Background thread that pushes all enrichment worker statuses every 2 seconds.
    Also auto-pauses rate-limited enrichment workers during active downloads."""
    workers = {
        'musicbrainz': lambda: mb_worker,
        'audiodb': lambda: audiodb_worker,
        'discogs': lambda: discogs_worker,
        'deezer': lambda: deezer_worker,
        'jiosaavn': lambda: jiosaavn_worker,
        'spotify-enrichment': lambda: spotify_enrichment_worker,
        'itunes-enrichment': lambda: itunes_enrichment_worker,
        'lastfm-enrichment': lambda: lastfm_worker,
        'genius-enrichment': lambda: genius_worker,
        'tidal-enrichment': lambda: tidal_enrichment_worker,
        'qobuz-enrichment': lambda: qobuz_enrichment_worker,
        'amazon-enrichment': lambda: amazon_worker,
        'bandcamp-enrichment': lambda: bandcamp_worker,
        'similar_artists': lambda: similar_artists_worker,
        'hydrabase': lambda: hydrabase_worker,
        'soulid': lambda: soulid_worker,
        'listening-stats': lambda: listening_stats_worker,
        'repair': lambda: repair_worker,
    }

    # Yield policy: downloads pause EVERYTHING (post-processing touches every
    # metadata source — measured 4m+/track when MusicBrainz contended with its
    # own worker); discovery pauses the API-contention five. The name lists +
    # decision live in core.enrichment.yield_policy (tested); this loop owns
    # the pause/resume side effects and the user-override bookkeeping.
    from core.enrichment.yield_policy import ALL_YIELD_WORKERS, worker_yield_reason
    yield_workers = {name: workers[name] for name in ALL_YIELD_WORKERS if name in workers}

    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(2)

        # Auto-pause/resume workers while foreground work runs
        try:
            downloading = _has_active_downloads()
            discovering = _has_active_discovery()
            if not downloading and not discovering:
                _download_yield_override.clear()  # Reset overrides when work finishes
            for name, get_w in yield_workers.items():
                w = get_w()
                if w is None or not hasattr(w, 'paused'):
                    continue
                reason = worker_yield_reason(name, downloading, discovering)
                if reason and not w.paused and name not in _download_yield_override:
                    w.paused = True
                    _download_auto_paused.add(name)
                    _auto_yield_cause[name] = reason
                    logger.debug(f"Auto-paused {name} during active {reason}")
                elif not reason and name in _download_auto_paused:
                    # Don't override an explicit user pause. If config says the worker
                    # was paused via the UI, leave it paused and just drop the auto-pause
                    # marker so the next auto-pause/resume cycle behaves normally.
                    config_key = f"{name.replace('-', '_')}_paused"
                    user_paused = config_manager.get(config_key, False)
                    _download_auto_paused.discard(name)
                    _auto_yield_cause.pop(name, None)
                    if not user_paused:
                        w.paused = False
                        logger.debug(f"Auto-resumed {name} after foreground work finished")
                    else:
                        logger.debug(f"Foreground work finished but {name} remains paused by user")
        except Exception as e:
            logger.debug(f"Error in download-yield check: {e}")

        # Auto-pause/resume above must run regardless of listeners; the stats
        # gather + broadcast below is pure UI and costs nothing to skip.
        if not _has_connected_clients():
            continue

        for name, get_worker in workers.items():
            try:
                worker = get_worker()
                if worker is None:
                    continue
                # Idle workers don't earn fresh aggregates every 2s: each
                # get_stats() is ~6 whole-table scans of the (10 GB) library
                # db, and 18 workers made this loop ~108 scans per tick,
                # forever, while any tab was open (perf sweep, Aug 2026). A
                # RUNNING worker's numbers actually move, so it stays on the
                # 2s beat; an idle one re-reads every 30s. Transitions are
                # caught instantly via the worker's IN-MEMORY running/paused
                # attributes (free to read), so starting or pausing a worker
                # never shows stale for even one tick.
                now_mono = time.monotonic()
                hit = _enrich_stats_cache.get(name)
                fresh_needed = (
                    hit is None
                    or hit[1].get('running')
                    or getattr(worker, 'running', False) != bool(hit[1].get('running'))
                    or getattr(worker, 'paused', False) != bool(hit[1].get('paused'))
                    or now_mono - hit[0] >= _ENRICH_IDLE_STATS_TTL
                )
                if fresh_needed:
                    status = worker.get_stats()
                    _enrich_stats_cache[name] = (now_mono, status)
                else:
                    status = hit[1]
                # Flag workers that were auto-paused for foreground work
                if name in _download_auto_paused:
                    status['yield_reason'] = _auto_yield_cause.get(name, 'downloads')
                else:
                    status.pop('yield_reason', None)
                socketio.emit(f'enrichment:{name}', status)
            except Exception as e:
                logger.debug(f"Error emitting {name} status: {e}")

def _emit_video_enrichment_status_loop():
    """Push the VIDEO enrichment worker statuses over the socket every 2s, exactly
    like the music enrichment loop — so the video dashboard listens instead of
    polling /api/video/enrichment/<svc>/status (that browser polling was flooding
    the access log). No-op until the video engine is actually running, so this
    never spins it up on the music side."""
    from core.video.enrichment.engine import peek_video_enrichment_engine
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(2)
        eng = peek_video_enrichment_engine()
        if eng is None:
            continue
        # Emit for EVERY registered worker (matchers + backfill: fanart / opensubtitles
        # / ryd / sponsorblock) so new dashboard buttons get live status with no extra
        # wiring here.
        for svc, w in (eng.workers or {}).items():
            try:
                socketio.emit(f'enrichment:{svc}', w.get_stats())
            except Exception as e:
                logger.debug(f"Error emitting video {svc} status: {e}")
        # The YouTube date enricher is a standalone daemon (not an engine worker),
        # but it reports the SAME stats shape — push it on the same socket so its
        # dashboard orb listens like the others (no /enrichment/youtube/status poll).
        try:
            from core.video.youtube_enrichment import get_youtube_date_enricher
            socketio.emit('enrichment:youtube', get_youtube_date_enricher().stats())
        except Exception as e:
            logger.debug(f"Error emitting video youtube status: {e}")


def _emit_tool_progress_loop():
    """Background thread that pushes all tool progress statuses every 1 second."""
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(1)
        # NOTE: no 'tool:stream' broadcast here. Stream state is PER-LISTENER
        # (Phase 3b sessions) and this thread has no request context, so it can
        # only ever read the DEFAULT session — which no real browser uses. The
        # old global emit told every client "stopped" forever, and the player
        # (which skipped HTTP polling while the socket was up) never learned
        # its stream was ready. Each client polls /api/stream/status instead,
        # which resolves its own session from the cookie.
        # Self-heal a hung DB-update job (#859) — functional, must run even
        # when nobody's watching the broadcast below.
        try:
            _check_db_update_stall()
        except Exception as e:
            logger.debug(f"Error in db update stall self-heal: {e}")

        if not _has_connected_clients():
            continue

        # Duplicate Cleaner (add computed space_freed_mb)
        try:
            with duplicate_cleaner_lock:
                state_copy = duplicate_cleaner_state.copy()
                state_copy["space_freed_mb"] = duplicate_cleaner_state["space_freed"] / (1024 * 1024)
                socketio.emit('tool:duplicate-cleaner', state_copy)
        except Exception as e:
            logger.debug(f"Error emitting duplicate cleaner status: {e}")
        # DB Update
        try:
            with db_update_lock:
                socketio.emit('tool:db-update', dict(db_update_state))
        except Exception as e:
            logger.debug(f"Error emitting db update status: {e}")
        # Metadata Update (match HTTP wrapper: {success, status})
        try:
            state_copy = metadata_update_state.copy()
            if state_copy.get('started_at'):
                state_copy['started_at'] = state_copy['started_at'].isoformat()
            if state_copy.get('completed_at'):
                state_copy['completed_at'] = state_copy['completed_at'].isoformat()
            socketio.emit('tool:metadata', {"success": True, "status": state_copy})
        except Exception as e:
            logger.debug(f"Error emitting metadata status: {e}")
        # Logs (format activity_feed same as HTTP endpoint)
        try:
            with activity_feed_lock:
                recent = activity_feed[-50:][::-1]
                formatted = []
                for a in recent:
                    ts = a.get('time', 'Unknown')
                    icon = a.get('icon', '•')
                    title = a.get('title', 'Activity')
                    sub = a.get('subtitle', '')
                    formatted.append(f"[{ts}] {icon} {title} - {sub}" if sub else f"[{ts}] {icon} {title}")
                if not formatted:
                    formatted = ["No recent activity.", "Sync and download operations..."]
                socketio.emit('tool:logs', {'logs': formatted})
        except Exception as e:
            logger.debug(f"Error emitting logs: {e}")

def _emit_live_log_loop():
    """Background thread that tails app.log and pushes new lines via WebSocket."""
    _last_pos = {}  # {source: file_position}
    _active_source = 'app'
    log_map = {
        'app': Path(_log_path),
        'acoustid': _log_dir / 'acoustid.log',
        'post_processing': _log_dir / 'post_processing.log',
        'source_reuse': _log_dir / 'source_reuse.log',
    }
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(0.5)
        try:
            with _log_live_sids_lock:
                if not _log_live_sids:
                    continue
            # Read which source clients want (stored by subscribe handler)
            source = getattr(_emit_live_log_loop, '_source', 'app')
            log_path = log_map.get(source, log_map['app'])
            if not os.path.exists(log_path):
                continue

            file_size = os.path.getsize(log_path)
            last_pos = _last_pos.get(source, 0)

            # File was truncated or rotated
            if file_size < last_pos:
                last_pos = 0

            if file_size == last_pos:
                continue  # No new data

            new_lines = []
            with open(log_path, 'r', encoding='utf-8', errors='replace') as f:
                f.seek(last_pos)
                for line in f:
                    stripped = line.rstrip()
                    if stripped:
                        new_lines.append(stripped)
                _last_pos[source] = f.tell()

            if new_lines:
                # Cap at 50 lines per push to avoid flooding
                socketio.emit('logs:live', {
                    'lines': new_lines[-50:],
                    'source': source,
                })
        except Exception as e:
            logger.debug(f"Error in live log emitter: {e}")

_emit_live_log_loop._source = 'app'


@socketio.on('logs:subscribe')
def handle_logs_subscribe(data):
    """Client subscribes to live log stream with optional source."""
    source = data.get('source', 'app')
    _emit_live_log_loop._source = source
    join_room('logs:live')
    with _log_live_sids_lock:
        _log_live_sids.add(request.sid)


@socketio.on('logs:unsubscribe')
def handle_logs_unsubscribe(data):
    leave_room('logs:live')
    with _log_live_sids_lock:
        _log_live_sids.discard(request.sid)


def _playlist_room_allowed(raw_id, spid, is_admin) -> bool:
    """May THIS session join a playlist-keyed push room (sync:/discovery:)?

    Ids that resolve to a mirrored playlist get the owner-or-admin rule (the
    push-side twin of the HTTP IDOR fix). Every other key shape — YouTube url
    hashes, Beatport chart ids, 'mirrored_<n>' composites, ids with no row
    behind them — joins exactly as before: those rooms carry no per-profile
    data (or no data at all), and refusing them would break legit
    subscriptions whose key shapes aren't numeric."""
    s = str(raw_id)
    if s.isdigit():
        n = int(s)
    elif s.startswith('mirrored_') and s[len('mirrored_'):].isdigit():
        n = int(s[len('mirrored_'):])
    else:
        return True
    try:
        pl = get_database().get_mirrored_playlist(n)
    except Exception:
        return True
    if not pl:
        return True   # no row = empty room, nothing to leak
    return is_admin or int(pl.get('profile_id') or 1) == spid


@socketio.on('sync:subscribe')
def handle_sync_subscribe(data):
    _spid, _is_admin = _ws_session_profile()
    for pid in data.get('playlist_ids', []):
        if _playlist_room_allowed(pid, _spid, _is_admin):
            join_room(f'sync:{pid}')

@socketio.on('sync:unsubscribe')
def handle_sync_unsubscribe(data):
    for pid in data.get('playlist_ids', []):
        leave_room(f'sync:{pid}')

@socketio.on('discovery:subscribe')
def handle_discovery_subscribe(data):
    _spid, _is_admin = _ws_session_profile()
    for pid in data.get('ids', []):
        if _playlist_room_allowed(pid, _spid, _is_admin):
            join_room(f'discovery:{pid}')

@socketio.on('discovery:unsubscribe')
def handle_discovery_unsubscribe(data):
    for pid in data.get('ids', []):
        leave_room(f'discovery:{pid}')

_SYNC_ACTIVE_STATUSES = ('starting', 'syncing', 'running', 'in_progress', 'discovering', 'analyzing')
_SYNC_AUTOMATION_TYPES = ('playlist_pipeline', 'sync_playlist', 'refresh_mirrored')


def _any_playlist_sync_running() -> bool:
    """True while ANY playlist sync work is running anywhere: a manual
    per-playlist sync, the UI-triggered mirrored pipeline, or a scheduled
    auto-sync pipeline (which runs as a playlist-flavored automation)."""
    with sync_lock:
        if any((s or {}).get('status') in _SYNC_ACTIVE_STATUSES for s in sync_states.values()):
            return True
    with playlist_pipeline_progress_lock:
        if any((s or {}).get('status') == 'running' for s in playlist_pipeline_progress_states.values()):
            return True
    with _auto_progress.progress_lock:
        return any(
            s.get('status') == 'running' and s.get('action_type') in _SYNC_AUTOMATION_TYPES
            for s in _auto_progress.progress_states.values()
        )


def _active_playlist_sync_summaries():
    """Small unscoped payload for the bell/dashboard: no track lists, just live
    labels and counters. The detailed sync:progress stream stays room-scoped."""
    summaries = []
    with sync_lock:
        for pid, state in list(sync_states.items()):
            if not state or state.get('status') not in _SYNC_ACTIVE_STATUSES:
                continue
            progress = state.get('progress') or {}
            summaries.append({
                'playlist_id': pid,
                'playlist_name': state.get('playlist_name') or progress.get('playlist_name') or '',
                'status': state.get('status'),
                'progress': progress,
            })
    return summaries


def _reconcile_discovery_sync_phases():
    """Server-side backstop for the 'syncing' -> terminal phase transition (#972).

    That transition used to happen ONLY inside the get_*_sync_status HTTP poll, so
    a socket-driven client — which never hits that endpoint (see the
    `if (socketConnected) return` fast-path in sync-services.js) — left the server
    stuck in 'syncing' after a sync finished: re-syncing 400'd with 'not ready for
    sync' and a reload showed a phantom, never-progressing sync. This runs every
    second regardless of how (or whether) the client observes progress, using the
    SAME reconcile helper the poll uses so the activity item still fires once.

    Beatport is intentionally excluded — it has its own sync-status lifecycle, not
    the shared get_sync_status."""
    targets = (
        (tidal_discovery_states, "Tidal playlist", _pl_name_attr_or_unknown),
        (deezer_discovery_states, "Deezer playlist", _pl_name_strict),
        (qobuz_discovery_states, "Qobuz playlist", _pl_name_strict),
        (spotify_public_discovery_states, "Spotify Link playlist", _pl_name_strict),
        (itunes_link_discovery_states, "iTunes Link", _pl_name_strict),
        (youtube_playlist_states, "YouTube playlist", _pl_name_safe),
        (ytmusic_discovery_states, "YouTube Music playlist", _pl_name_safe),
        (listenbrainz_playlist_states, "ListenBrainz playlist", _pl_name_safe),
    )
    for states_dict, activity_subject, name_getter in targets:
        for state in list(states_dict.values()):
            if state.get('phase') != 'syncing':
                continue
            spid = state.get('sync_playlist_id')
            if not spid:
                continue
            with sync_lock:
                sync_state = dict(sync_states.get(spid) or {})
            try:
                _reconcile_sync_phase(
                    state, sync_state,
                    activity_subject=activity_subject,
                    playlist_name_getter=name_getter,
                    add_activity_item=add_activity_item,
                )
            except Exception as e:
                logger.debug("sync phase reconcile failed for %s: %s", spid, e)


def _emit_sync_progress_loop():
    """Push sync progress to subscribed rooms every 1 second."""
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(1)
        try:
            # Reconcile stuck 'syncing' discovery states — this is a functional
            # self-heal (#972), not just UI push, so it must run even when no
            # client is connected to see the emit below.
            _reconcile_discovery_sync_phases()

            if not _has_connected_clients():
                continue

            with sync_lock:
                for pid, state in list(sync_states.items()):
                    try:
                        socketio.emit('sync:progress', {
                            'playlist_id': pid, **state
                        }, room=f'sync:{pid}')
                    except Exception as e:
                        logger.debug("sync progress emit failed: %s", e)

            # Quick Actions gauge heartbeat — UNSCOPED, unlike sync:progress
            # which only reaches clients subscribed to a playlist room. The
            # dashboard's Auto-Sync tile needs to light for ALL pipeline
            # work, including the scheduled auto-sync (an automation).
            # Emitted only while active; the frontend decays on silence.
            active_syncs = _active_playlist_sync_summaries()
            if active_syncs or _any_playlist_sync_running():
                socketio.emit('sync:active', {'active': True, 'syncs': active_syncs})
        except Exception as e:
            logger.debug(f"Error in sync progress loop: {e}")

def _emit_discovery_progress_loop():
    """Push discovery progress to subscribed rooms every 1 second."""
    platform_states = {
        'tidal': lambda: tidal_discovery_states,
        'qobuz': lambda: qobuz_discovery_states,
        'deezer': lambda: deezer_discovery_states,
        'youtube': lambda: youtube_playlist_states,
        'ytmusic': lambda: ytmusic_discovery_states,
        'beatport': lambda: beatport_chart_states,
        'listenbrainz': lambda: listenbrainz_playlist_states,
        'spotify_public': lambda: spotify_public_discovery_states,
        'itunes_link': lambda: itunes_link_discovery_states,
    }
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(1)
        for platform_name, get_states in platform_states.items():
            try:
                states_dict = get_states()
                for pid, state in list(states_dict.items()):
                    try:
                        phase = state.get('phase', '')
                        if phase in ('', 'idle'):
                            continue
                        payload = {
                            'platform': platform_name,
                            'id': pid,
                            'phase': state.get('phase'),
                            'status': state.get('status', 'unknown'),
                            'progress': state.get('discovery_progress', 0),
                            'discovery_progress': state.get('discovery_progress', {}),
                            'spotify_matches': state.get('spotify_matches', 0),
                            'spotify_total': state.get('spotify_total', 0),
                            'results': state.get('discovery_results', state.get('results', [])),
                            'complete': state.get('phase') == 'discovered',
                        }
                        socketio.emit('discovery:progress', payload, room=f'discovery:{pid}')
                    except Exception as e:
                        logger.debug("discovery progress emit failed: %s", e)
            except Exception as e:
                logger.debug(f"Error in {platform_name} discovery loop: {e}")

def _emit_scan_status_loop():
    """Push watchlist and media scan status every 2 seconds.
    Skipped entirely while no client is connected."""
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(2)
        if not _has_connected_clients():
            continue
        # Watchlist scan
        try:
            state = watchlist_scan_state.copy()
            if state.get('started_at'):
                state['started_at'] = state['started_at'].isoformat()
            if state.get('completed_at'):
                state['completed_at'] = state['completed_at'].isoformat()
            state.pop('results', None)
            socketio.emit('scan:watchlist', {"success": True, **state})
        except Exception as e:
            logger.debug(f"Error emitting watchlist scan: {e}")
        # Media scan
        try:
            if web_scan_manager:
                scan_status = web_scan_manager.get_scan_status()
                socketio.emit('scan:media', {"success": True, "status": scan_status})
        except Exception as e:
            logger.debug(f"Error emitting media scan: {e}")
        # Wishlist stats (auto-processing detection + countdown refresh)
        try:
            next_run = automation_engine.get_system_automation_next_run_seconds('process_wishlist') if automation_engine else 0
            active_batches = 0
            with tasks_lock:
                active_batches = sum(
                    1
                    for batch in download_batches.values()
                    if batch.get('playlist_id') == 'wishlist'
                    and batch.get('phase') not in ['complete', 'error', 'cancelled']
                )
            socketio.emit('wishlist:stats', {
                "is_auto_processing": is_wishlist_actually_processing(),
                "active_batches": active_batches,
                "next_run_in_seconds": next_run,
            })
        except Exception as e:
            logger.debug(f"Error emitting wishlist stats: {e}")

def _emit_automation_progress_loop():
    """Push automation:progress events every 1 second for running automations."""
    _auto_progress.emit_progress_loop(
        socketio,
        is_shutting_down=lambda: globals().get('IS_SHUTTING_DOWN', False),
    )

def _emit_repair_progress_loop():
    """Push repair:progress events every 1 second for running repair jobs."""
    while not globals().get('IS_SHUTTING_DOWN', False):
        socketio.sleep(1)
        try:
            if repair_worker is None:
                continue
            # Access the progress states set up during repair worker init
            lock = getattr(repair_worker, '_progress_lock_ref', None)
            states = getattr(repair_worker, '_progress_states_ref', None)
            if lock is None or states is None:
                continue
            with lock:
                active = {}
                stale = []
                now = datetime.now()
                for jid, state in states.items():
                    if state['status'] == 'running':
                        cp = dict(state)
                        cp['log'] = list(state['log'])
                        active[jid] = cp
                    elif state['status'] in ('finished', 'error') and state.get('finished_at'):
                        try:
                            finished_time = datetime.fromisoformat(state['finished_at'])
                            if (now - finished_time).total_seconds() > 60:
                                stale.append(jid)
                        except (ValueError, TypeError):
                            stale.append(jid)
                        # Still include recently finished states so frontend sees final state
                        if jid not in stale:
                            cp = dict(state)
                            cp['log'] = list(state['log'])
                            active[jid] = cp
                for jid in stale:
                    del states[jid]
            if active:
                socketio.emit('repair:progress', active)
        except Exception as e:
            logger.debug(f"Error emitting repair progress: {e}")

# ================================================================================================
# END WEBSOCKET HANDLERS
# ================================================================================================

_runtime_start_lock = threading.Lock()
_runtime_started = False


def start_runtime_services():
    """Start one-time server background services for direct and WSGI launches."""
    global _runtime_started

    with _runtime_start_lock:
        if _runtime_started:
            return

        logger.info("Starting SoulSync runtime services...")

        # Dump SOULSYNC_* env vars for diagnostics (helps debug Docker/Unraid env issues)
        _soulsync_env = {k: v for k, v in os.environ.items() if k.startswith('SOULSYNC_')}
        if _soulsync_env:
            logger.info(f"[Startup] SOULSYNC environment variables: {_soulsync_env}")
        else:
            logger.warning("[Startup] No SOULSYNC_* environment variables detected")

        # Start OAuth callback servers
        logger.info("Starting OAuth callback servers...")
        start_oauth_callback_servers()

        # One-time repair: purge artist album-list cache entries poisoned by
        # partial watchlist probes (limit=5/max_pages=1 results stored in the
        # full-discography slot — artist pages showed only the newest handful
        # of releases for every watchlist artist). The writer is fixed; this
        # clears what's already bad. Guarded so it runs once per install.
        try:
            if not config_manager.get('maintenance.album_cache_purge_v1', False):
                from core.metadata.cache import get_metadata_cache as _gmc
                _purged = _gmc().purge_artist_album_lists('spotify')
                config_manager.set('maintenance.album_cache_purge_v1', True)
                if _purged:
                    logger.warning(
                        "[Startup] Purged %d poisoned artist album-list cache "
                        "entries (partial watchlist probes); artist pages will "
                        "refetch full discographies lazily", _purged)
        except Exception as _purge_err:
            logger.debug("album cache purge skipped: %s", _purge_err)

        # Startup diagnostics: Check and recover stuck flags
        logger.info("Running startup diagnostics...")
        stuck_flags_recovered = check_and_recover_stuck_flags()
        if stuck_flags_recovered:
            logger.warning("Recovered stuck flags from previous session")
        else:
            logger.warning("No stuck flags detected - system healthy")

        # Album-bundle staging sweep — remove orphan ``<batch_id>``
        # dirs left behind by previous-session crashes, errored
        # batches, or pre-fix Soulseek bundles that the per-batch
        # cleanup gate excluded. Runs once at startup, before any
        # new batch can register a staging dir, so we can't race a
        # starting batch. download_batches is empty at this point
        # (no batches survive a process restart) — every dir on
        # disk is by definition an orphan.
        try:
            from core.downloads.lifecycle import sweep_orphan_album_bundle_staging
            _staging_root = config_manager.get(
                'download_source.album_bundle_staging_path',
                'storage/album_bundle_staging',
            ) or 'storage/album_bundle_staging'
            # rescue_root: a stalled atomic-album batch leaves finished audio
            # here. Deleting it on the next start took people's downloads with
            # one log line to show for it (#1210), so anything still holding
            # audio goes to the recycle bin instead and can be restored.
            from core.repair_jobs.base import deleted_quarantine_root
            _rescue_root = None
            try:
                _rescue_root = deleted_quarantine_root(
                    docker_resolve_path(config_manager.get('soulseek.transfer_path', './Transfer'))
                )
            except Exception as _rescue_err:
                # No quarantine root means the sweep falls back to its old
                # delete-only behaviour; better than skipping the sweep.
                logger.warning("[Startup] Could not resolve recycle bin for staging sweep: %s", _rescue_err)
            _swept = sweep_orphan_album_bundle_staging(
                _staging_root,
                active_batch_ids=set(download_batches.keys()),
                rescue_root=_rescue_root,
            )
            if _swept:
                logger.warning(
                    "[Startup] Swept %d orphan album-bundle staging dir(s) from %s",
                    _swept, _staging_root,
                )
        except Exception as _sweep_err:
            # Sweep must not crash startup — log and continue.
            logger.warning("[Startup] Album-bundle staging sweep failed: %s", _sweep_err)

        # Establish the barrier before any runtime service that can mutate the
        # music catalogue. It treats an unclaimed-but-required upgrade as
        # active too, closing the old startup race before try_claim().
        try:
            from core.library2.migration_gate import (
                MigrationPauseSupervisor, defer_or_call,
            )
            library_v2_migration_gate = MigrationPauseSupervisor(
                get_database(), _enrichment_workers, automation_engine,
            ).start()
            library_v2_migration_gate.tick()
        except Exception as _lib2_gate_err:
            logger.debug(f"could not start lib2 migration pause supervisor: {_lib2_gate_err}")

        defer_or_call(start_simple_background_monitor, get_database(), "download monitor")
        if usenet_acquisition_monitor is not None:
            defer_or_call(usenet_acquisition_monitor.start, get_database(), "acquisition monitor")

        # Existing-installation bootstrap: import legacy -> lib2_* on its own the
        # native catalogue bootstrap, no UI click required (§78).
        try:
            start_library_v2_bootstrap_autostart()
        except Exception as _lib2_bootstrap_err:
            logger.debug(f"could not start lib2 bootstrap import autostart: {_lib2_bootstrap_err}")

        # Name the holder when SQLite's single write lock gets stuck. Without
        # this the log only ever shows victims ("database is locked" from
        # notifications, automations, repair jobs, UI preferences) and the
        # thread actually holding the lock stays anonymous. Silent on a healthy
        # installation; see core/db_lock_watchdog.py.
        try:
            from core.db_lock_watchdog import start_watchdog as _start_lock_watchdog
            _start_lock_watchdog(get_database())
        except Exception as _lock_watchdog_err:
            logger.debug(f"could not start db lock watchdog: {_lock_watchdog_err}")

        # Wishlist/watchlist timers are now managed by AutomationEngine system automations

        # Pre-build import suggestions cache in background
        logger.info("Pre-building import suggestions cache...")
        defer_or_call(start_import_suggestions_cache, get_database(), "import suggestions cache")

        # Initialize app start time for uptime tracking
        app.start_time = time.time()

        # Growth-triggered garbage collection (#802 / resource usage). plexapi builds large XML
        # Element trees whose nodes reference each other in cycles; Python's generational GC
        # parks those in gen2 and sweeps it rarely, so they accumulate and RSS climbs (measured:
        # ~300MB fresh -> 1.8-2.2GB after browsing every page, most of it reclaimable cyclic
        # garbage a full gc.collect() frees instantly). A FIXED timer overshoots — browsing piles
        # garbage faster than once-a-minute catches it. Instead, poll RSS cheaply and collect as
        # soon as it has grown GROW_MB since the last sweep, so it kicks in DURING a heavy browse
        # and caps the peak near (floor + GROW_MB) instead of letting it run to 2GB+. A backstop
        # interval still collects slow accumulation when idle.
        def _growth_triggered_gc():
            import gc
            CHECK_SECONDS = 8       # cheap RSS poll cadence
            GROW_MB = 200           # collect once RSS climbs this much since the last sweep
            BACKSTOP_SECONDS = 120  # ...or at least this often regardless
            try:
                import psutil
                proc = psutil.Process(os.getpid())
                rss_mb = lambda: proc.memory_info().rss / (1024 * 1024)
            except Exception:
                rss_mb = lambda: 0.0
            # glibc malloc_trim hands freed arenas back to the OS — WITHOUT it gc.collect() frees
            # the Python objects but glibc hoards the memory, so RSS never drops and the peak still
            # runs to 2GB+. Best-effort: absent on musl/Alpine or non-Linux, where we just skip it
            # (gc still helps, RSS just sticks closer to the high-water mark there).
            _trim = None
            try:
                import ctypes
                import ctypes.util
                _libc = ctypes.CDLL(ctypes.util.find_library('c') or 'libc.so.6')
                if hasattr(_libc, 'malloc_trim'):
                    _trim = _libc.malloc_trim
            except Exception:  # noqa: S110 — malloc_trim absent on musl/non-Linux; just skip it
                pass
            floor = rss_mb()
            last = time.time()
            while True:
                time.sleep(CHECK_SECONDS)
                try:
                    if (rss_mb() - floor) >= GROW_MB or (time.time() - last) >= BACKSTOP_SECONDS:
                        gc.collect()
                        if _trim is not None:
                            try:
                                _trim(0)
                            except Exception:  # noqa: S110 — best-effort OS reclaim, never fatal
                                pass
                        floor = rss_mb()
                        last = time.time()
                except Exception:  # noqa: S110 — best-effort housekeeping, never crash the app
                    pass
        threading.Thread(target=_growth_triggered_gc, daemon=True, name='gc-sweeper').start()
        logger.info("GC sweeper started (collect + malloc_trim on +200MB growth, backstop 120s)")

        # Register action handlers; the engine itself starts only after the
        # exclusive Library-v2 upgrade barrier has cleared.
        _register_automation_handlers()
        if automation_engine:
            def _start_automation_after_upgrade():
                automation_engine.resume_after_migration()
                logger.info("Starting automation engine...")
                automation_engine.start()
                logger.info("Automation engine started")
                try:
                    automation_engine.emit('app_started', {})
                except Exception as e:
                    logger.debug("app_started emit failed: %s", e)
            try:
                defer_or_call(
                    _start_automation_after_upgrade, get_database(), "automation engine")
            except AttributeError as e:
                logger.error(f"Automation engine failed to start: {e}")
                logger.info("   If using Docker, check that your volume mount is /app/data (not /app/database)")
                logger.error(f"Automation engine start error (possible stale Docker volume): {e}")
            except Exception as e:
                logger.error(f"Automation engine failed to start: {e}")
                logger.error(f"Automation engine start error: {e}")

        # Add startup activity
        add_activity_item("", "System Started", "SoulSync Web UI Server initialized", "Now")

        # Start WebSocket background emitters
        logger.info("Starting WebSocket background emitters...")
        # Phase 1: Global pollers
        socketio.start_background_task(_emit_service_status_loop)
        socketio.start_background_task(_emit_watchlist_count_loop)
        socketio.start_background_task(_emit_download_status_loop)
        socketio.start_background_task(_emit_chat_push_loop)
        socketio.start_background_task(_chat_auto_prove_loop)
        # Server Activity — subscriber-gated live push (idle when no drawer open)
        socketio.start_background_task(_emit_server_activity_loop)
        # Phase 2: Dashboard pollers
        socketio.start_background_task(_emit_system_stats_loop)
        socketio.start_background_task(_emit_activity_feed_loop)
        socketio.start_background_task(_emit_db_stats_loop)
        socketio.start_background_task(_emit_wishlist_count_loop)
        # Phase 3: Enrichment sidebar workers
        socketio.start_background_task(_emit_enrichment_status_loop)
        # Phase 3 (video): push video enrichment status so the video dashboard
        # listens instead of polling (matches music; no access-log flood).
        socketio.start_background_task(_emit_video_enrichment_status_loop)
        # Phase 4: Tool progress pollers
        socketio.start_background_task(_emit_tool_progress_loop)
        # Phase 5: Sync/discovery progress + scans
        socketio.start_background_task(_emit_sync_progress_loop)
        socketio.start_background_task(_emit_discovery_progress_loop)
        socketio.start_background_task(_emit_scan_status_loop)
        # Phase 6: Automation progress
        socketio.start_background_task(_emit_automation_progress_loop)
        # Phase 7: Repair job progress
        socketio.start_background_task(_emit_repair_progress_loop)
        # Hydrabase auto-reconnect monitor
        socketio.start_background_task(_hydrabase_reconnect_loop)
        # API Rate Monitor — 1s push for speedometer gauges
        socketio.start_background_task(_emit_rate_monitor_loop)
        # Live log tail — streams new log lines to the log viewer
        socketio.start_background_task(_emit_live_log_loop)
        logger.info("WebSocket emitters started (Phase 1-7: global/dashboard/enrichment/tools/sync/automations/repair + rate monitor + live logs)")

        _runtime_started = True


# Module import is complete — provider clients may now perform network probes.
from core.boot_phase import mark_boot_complete
mark_boot_complete()

# Auto-run the Discover popularity backfill in the background (no manual trigger). Self-limits: it
# sleeps past startup, fills whatever's still missing, and exits when there's nothing left.
try:
    import threading as _pb_threading
    _pb_threading.Thread(target=_autostart_popularity_backfill, daemon=True,
                         name='PopularityBackfillAutostart').start()
except Exception as _pb_autostart_err:
    logger.debug(f"could not start popularity backfill autostart: {_pb_autostart_err}")


# Direct execution: python web_server.py (dev/Windows fallback)
# Production should use: gunicorn -c gunicorn.conf.py wsgi:application
if _DIRECT_RUN:
    web_run_host = os.environ.get('SOULSYNC_WEB_BIND_HOST', '0.0.0.0')
    web_run_port = int(os.environ.get('SOULSYNC_WEB_BIND_PORT', '8008'))
    display_host = '127.0.0.1' if web_run_host in {'0.0.0.0', '::'} else web_run_host
    logger.info("Starting SoulSync Web UI Server...")
    logger.info(f"Open your browser and navigate to http://{display_host}:{web_run_port}")
    logger.info("Tip: For production, use gunicorn -c gunicorn.conf.py wsgi:application")
    start_runtime_services()
    socketio.run(app, host=web_run_host, port=web_run_port, debug=False, allow_unsafe_werkzeug=True)
